function getListAttachmentsModalScript(): string {
  return `
  var listAttCustomerId = null;
  var listAttRequestId = null;
  function openListAttachmentsFromRow(btn, requestId) {
    if (!btn) return;
    var customerId = btn.getAttribute('data-customer-id');
    var name = btn.getAttribute('data-customer-name') || '';
    var att = btn.getAttribute('data-attachments') || '[]';
    if (!customerId && btn.closest) {
      var tr = btn.closest('tr');
      if (tr) {
        customerId = tr.getAttribute('data-customer-id');
        name = tr.getAttribute('data-customer-name') || tr.getAttribute('data-name') || name;
        att = tr.getAttribute('data-attachments') || att;
      }
    }
    if (!customerId) return;
    openListAttachmentsModal(customerId, name, att, requestId || null);
  }
  function portalListAttachmentsModal(modal) {
    if (!modal || modal.parentElement === document.body) return;
    modal.__listAttRestore = { parent: modal.parentElement, next: modal.nextSibling };
    document.body.appendChild(modal);
  }
  function restoreListAttachmentsModal(modal) {
    if (!modal || !modal.__listAttRestore) return;
    var r = modal.__listAttRestore;
    modal.__listAttRestore = null;
    if (!r.parent) return;
    try {
      if (r.next && r.next.parentNode === r.parent) r.parent.insertBefore(modal, r.next);
      else r.parent.appendChild(modal);
    } catch (e) {
      try { document.body.appendChild(modal); } catch (e2) {}
    }
  }
  function openListAttachmentsModal(customerId, customerName, attachmentsJson, requestId) {
    listAttCustomerId = customerId;
    listAttRequestId = requestId || null;
    var modal = document.getElementById('listAttachmentsModal');
    if (!modal) return;
    var title = document.getElementById('listAttachmentsModalTitle');
    if (title) {
      var titleSpan = title.querySelector('span');
      var label = 'المرفقات — ' + (customerName || ('عميل #' + customerId));
      if (titleSpan) titleSpan.textContent = label;
      else title.textContent = label;
    }
    portalListAttachmentsModal(modal);
    var listEl = document.getElementById('list_attachments_list');
    var addBtn = document.getElementById('list_attachments_add');
    if (listEl) listEl.innerHTML = '';
    if (addBtn && addBtn.parentNode) {
      var freshAdd = addBtn.cloneNode(true);
      addBtn.parentNode.replaceChild(freshAdd, addBtn);
    }
    if (typeof window.initDynamicCustomerAttachments === 'function') {
      window.initDynamicCustomerAttachments({
        hiddenInputId: 'list_attachments_json',
        listContainerId: 'list_attachments_list',
        addButtonId: 'list_attachments_add',
        customerId: String(customerId),
        initialAttachments: attachmentsJson || '[]'
      });
    }
    modal.classList.remove('hidden');
    document.body.classList.add('list-attachments-modal-open');
  }
  function closeListAttachmentsModal() {
    var modal = document.getElementById('listAttachmentsModal');
    if (modal) {
      modal.classList.add('hidden');
      restoreListAttachmentsModal(modal);
    }
    document.body.classList.remove('list-attachments-modal-open');
    listAttCustomerId = null;
    listAttRequestId = null;
  }
  (function () {
    var modal = document.getElementById('listAttachmentsModal');
    if (!modal) return;
    modal.addEventListener('click', function (e) { if (e.target === modal) closeListAttachmentsModal(); });
    document.addEventListener('keydown', function (e) {
      if (e && e.key === 'Escape' && !modal.classList.contains('hidden')) closeListAttachmentsModal();
    });
  })();
  async function saveListAttachments() {
    if (!listAttCustomerId) return;
    var saveBtn = document.getElementById('listAttachmentsSaveBtn');
    if (saveBtn) saveBtn.disabled = true;
    try {
      var uploaded = [];
      if (typeof window.uploadDynamicCustomerAttachments === 'function') {
        uploaded = await window.uploadDynamicCustomerAttachments({
          customerId: String(listAttCustomerId),
          onProgress: function (msg) {
            if (typeof showToast === 'function') showToast(msg, 'info');
          }
        });
      }
      var attJson = JSON.stringify(uploaded || []);
      if (listAttRequestId) {
        var resp = await fetch('/api/financing-requests/' + listAttRequestId, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          credentials: 'include',
          body: JSON.stringify({ attachments_json: attJson })
        });
        var data = await resp.json();
        if (!resp.ok || !data.success) throw new Error(data.error || 'فشل الحفظ');
      } else {
        var fd = new FormData();
        fd.append('attachments_only', '1');
        fd.append('attachments_json', attJson);
        var resp2 = await fetch('/api/customers/' + listAttCustomerId, {
          method: 'POST',
          credentials: 'include',
          body: fd
        });
        var data2 = await resp2.json();
        if (!resp2.ok || !data2.success) throw new Error(data2.error || 'فشل الحفظ');
      }
      var row = document.querySelector('tr[data-customer-id="' + listAttCustomerId + '"]');
      if (row) row.setAttribute('data-attachments', attJson);
      document.querySelectorAll('button.actions-dropdown-item[data-customer-id="' + listAttCustomerId + '"]').forEach(function (b) {
        b.setAttribute('data-attachments', attJson);
      });
      closeListAttachmentsModal();
      if (typeof showToast === 'function') showToast('تم حفظ المرفقات بنجاح', 'success');
    } catch (e) {
      console.error('[listAttachments]', e);
      if (typeof showToast === 'function') showToast('فشل حفظ المرفقات: ' + (e.message || e), 'error');
      else alert('فشل حفظ المرفقات: ' + (e.message || e));
    } finally {
      if (saveBtn) saveBtn.disabled = false;
    }
  }`
}

const OBLIGATION_DROPDOWN_CUSTOM_VALUE = '__custom__'

function getObligationDropdownHelpersScript(): string {
  return `
if (!window.__obligationDropdownHelpersLoaded) {
  window.__obligationDropdownHelpersLoaded = true;
  window.OBLIGATION_DROPDOWN_CUSTOM_VALUE = ${JSON.stringify(OBLIGATION_DROPDOWN_CUSTOM_VALUE)};
  window.collectObligationDropdownFromRow = function (tr, selectClass, customClass) {
    var sel = tr.querySelector('.' + selectClass);
    if (!sel) return '';
    if (sel.value === window.OBLIGATION_DROPDOWN_CUSTOM_VALUE) {
      var custom = tr.querySelector('.' + customClass);
      return custom ? String(custom.value || '').trim() : '';
    }
    return String(sel.value || '').trim();
  };
  window.collectObligationTypeFromRow = window.collectObligationDropdownFromRow;
  window.buildObligationDropdownCellHtml = function (selectedValue, selectClass, customClass, optionNames, esc, emptyLabel, customLabel, placeholder) {
    esc = esc || function (s) { return String(s == null ? '' : s); };
    emptyLabel = emptyLabel || '— اختر —';
    customLabel = customLabel || 'أخرى (إدخال يدوي)';
    placeholder = placeholder || '';
    var sel = selectedValue == null ? '' : String(selectedValue).trim();
    var isKnown = sel && optionNames.indexOf(sel) >= 0;
    var isCustom = sel && !isKnown;
    var opts = '<option value="">' + esc(emptyLabel) + '</option>';
    for (var i = 0; i < optionNames.length; i++) {
      var name = optionNames[i];
      opts += '<option value="' + esc(name) + '"' + (sel === name ? ' selected' : '') + '>' + esc(name) + '</option>';
    }
    opts += '<option value="' + window.OBLIGATION_DROPDOWN_CUSTOM_VALUE + '"' + (isCustom ? ' selected' : '') + '>أخرى (إدخال يدوي)</option>';
    var customHidden = isCustom ? '' : ' hidden';
    return '<div class="space-y-1">' +
      '<select class="' + selectClass + ' w-full px-2 py-1.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500">' + opts + '</select>' +
      '<input type="text" class="' + customClass + customHidden + ' w-full px-2 py-1.5 border border-gray-300 rounded-lg text-sm" placeholder="' + esc(placeholder) + '" maxlength="200" value="' + (isCustom ? esc(sel) : '') + '">' +
      '</div>';
  };
  window.buildObligationTypeCellHtml = function (selectedValue, selectClass, customClass, typeNames, esc) {
    return window.buildObligationDropdownCellHtml(selectedValue, selectClass, customClass, typeNames, esc, '— اختر نوع الالتزام —', 'أخرى (إدخال يدوي)', 'أدخل نوع الالتزام');
  };
  window.wireObligationDropdownRow = function (tr, selectClass, customClass) {
    var sel = tr.querySelector('.' + selectClass);
    var custom = tr.querySelector('.' + customClass);
    if (!sel || !custom) return;
    function sync() {
      if (sel.value === window.OBLIGATION_DROPDOWN_CUSTOM_VALUE) {
        custom.classList.remove('hidden');
      } else {
        custom.classList.add('hidden');
      }
    }
    sel.addEventListener('change', sync);
    sync();
  };
  window.wireObligationTypeRow = window.wireObligationDropdownRow;
}`
}

function getCustomerObligationsTableInitScript(options: {
  tbodyId: string
  addBtnId: string
  typeSelectClass: string
  typeCustomInputClass: string
  totalClass: string
  monthlyClass: string
  dueClass: string
  removeClass: string
  obligationTypeNamesJson: string
  initialRowsJson?: string
}): string {
  const {
    tbodyId,
    addBtnId,
    typeSelectClass,
    typeCustomInputClass,
    totalClass,
    monthlyClass,
    dueClass,
    removeClass,
    obligationTypeNamesJson,
    initialRowsJson = '[]',
  } = options
  return `
${getObligationDropdownHelpersScript()}
(function () {
  var tbody = document.getElementById(${JSON.stringify(tbodyId)});
  var addBtn = document.getElementById(${JSON.stringify(addBtnId)});
  if (!tbody || !addBtn) return;
  var obligationTypeNames = ${obligationTypeNamesJson};
  function esc(s) {
    return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;');
  }
  function addRow(data) {
    data = data || {};
    var tr = document.createElement('tr');
    tr.className = 'border-b border-gray-200';
    tr.innerHTML =
      '<td class="py-1 px-2">' +
      window.buildObligationTypeCellHtml(data.obligation_type || '', ${JSON.stringify(typeSelectClass)}, ${JSON.stringify(typeCustomInputClass)}, obligationTypeNames, esc) +
      '</td>' +
      '<td class="py-1 px-2"><input type="number" class="${totalClass} w-full px-2 py-1.5 border rounded" step="0.01" min="0" placeholder="0"></td>' +
      '<td class="py-1 px-2"><input type="number" class="${monthlyClass} w-full px-2 py-1.5 border rounded" step="0.01" min="0" placeholder="0"></td>' +
      '<td class="py-1 px-2"><input type="text" class="${dueClass} w-full px-2 py-1.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500" maxlength="200"></td>' +
      '<td class="py-1 px-2"><button type="button" class="${removeClass} text-red-600 hover:text-red-800" title="حذف"><i class="fas fa-trash"></i></button></td>';
    if (data.total_amount != null) tr.querySelector('.${totalClass}').value = data.total_amount;
    if (data.monthly_installment != null) tr.querySelector('.${monthlyClass}').value = data.monthly_installment;
    if (data.due_date) tr.querySelector('.${dueClass}').value = data.due_date;
    window.wireObligationTypeRow(tr, ${JSON.stringify(typeSelectClass)}, ${JSON.stringify(typeCustomInputClass)});
    tr.querySelector('.${removeClass}').onclick = function () { tr.remove(); };
    tbody.appendChild(tr);
  }
  var initialRows = ${initialRowsJson};
  if (initialRows && initialRows.length) initialRows.forEach(function (o) { addRow(o); });
  else addRow();
  addBtn.onclick = function () { addRow(); };
})();`
}

function getDynamicCustomerAttachmentsScript(): string {
  return `
(function () {
  if (window.initDynamicCustomerAttachments) return;
  var MAX_ATTACHMENTS = ${MAX_CUSTOMER_ATTACHMENTS};
  var MAX_FILE_BYTES = ${MAX_ATTACHMENT_SIZE_BYTES};
  var MAX_FILE_MB = ${MAX_ATTACHMENT_SIZE_MB};
  var PDFJS_VERSION = '3.11.174';
  var pdfJsLoading = null;
  function esc(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }
  function newId() {
    return 'att_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 9);
  }
  function isPdfFile(file) {
    var name = String(file.name || '').toLowerCase();
    return file.type === 'application/pdf' || name.endsWith('.pdf');
  }
  function loadPdfJsLib() {
    if (window.pdfjsLib) return Promise.resolve(window.pdfjsLib);
    if (!pdfJsLoading) {
      pdfJsLoading = new Promise(function (resolve, reject) {
        var script = document.createElement('script');
        script.src = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/' + PDFJS_VERSION + '/pdf.min.js';
        script.onload = function () {
          if (window.pdfjsLib) {
            window.pdfjsLib.GlobalWorkerOptions.workerSrc =
              'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/' + PDFJS_VERSION + '/pdf.worker.min.js';
            resolve(window.pdfjsLib);
          } else {
            reject(new Error('pdf.js unavailable'));
          }
        };
        script.onerror = function () { reject(new Error('pdf.js load failed')); };
        document.head.appendChild(script);
      });
    }
    return pdfJsLoading;
  }
  async function readPdfPageCount(file) {
    try {
      var pdfjsLib = await loadPdfJsLib();
      var data = await file.arrayBuffer();
      var doc = await pdfjsLib.getDocument({ data: data }).promise;
      var count = doc.numPages;
      if (doc.destroy) await doc.destroy();
      return count > 0 ? count : null;
    } catch (e) {
      console.warn('PDF page count failed', e);
      return null;
    }
  }
  function pageCountHint(it) {
    if (it.page_count_pending) {
      return '<span class="text-xs text-gray-600 block mt-1"><i class="fas fa-spinner fa-spin ml-1"></i>جاري حساب عدد الصفحات...</span>';
    }
    if (it.page_count != null && it.page_count > 0) {
      return '<span class="text-xs text-gray-600 block mt-1"><i class="fas fa-file-alt ml-1"></i>' + it.page_count + ' صفحة</span>';
    }
    return '';
  }
  window.initDynamicCustomerAttachments = function (opts) {
    opts = opts || {};
    var hidden = document.getElementById(opts.hiddenInputId);
    var listEl = document.getElementById(opts.listContainerId);
    var addBtn = document.getElementById(opts.addButtonId);
    if (!hidden || !listEl || !addBtn) return;
    var customerId = opts.customerId != null ? String(opts.customerId) : '';
    var items = [];
    try {
      var initial = opts.initialAttachments;
      if (typeof initial === 'string' && initial.trim()) initial = JSON.parse(initial);
      if (Array.isArray(initial)) {
        initial.forEach(function (entry) {
          if (!entry) return;
          var label = String(entry.label || '').trim();
          var url = String(entry.url || '').trim();
          var id = String(entry.id || '').trim() || newId();
          var pageCount = entry.page_count != null ? Number(entry.page_count) : null;
          if (pageCount != null && (!Number.isFinite(pageCount) || pageCount <= 0)) pageCount = null;
          if (!label || !url) return;
          items.push({
            id: id,
            label: label,
            url: url,
            file: null,
            page_count: pageCount != null ? Math.floor(pageCount) : null,
            page_count_pending: false
          });
        });
      }
    } catch (e) {}
    function attachmentPayload(it) {
      var row = { id: it.id, label: it.label, url: it.url };
      if (it.page_count != null && it.page_count > 0) row.page_count = it.page_count;
      return row;
    }
    function syncHidden() {
      var payload = items
        .filter(function (it) { return it.url; })
        .map(attachmentPayload);
      hidden.value = JSON.stringify(payload);
    }
    function updateAddButton() {
      addBtn.style.display = items.length >= MAX_ATTACHMENTS ? 'none' : '';
    }
    function render() {
      listEl.innerHTML = '';
      items.forEach(function (it, index) {
        var row = document.createElement('div');
        row.className = 'border border-gray-200 rounded-lg p-3 bg-gray-50';
        var hasUrl = !!it.url;
        var fileHint = it.file
          ? '<span class="text-xs text-green-700 block mt-1"><i class="fas fa-check-circle ml-1"></i>تم اختيار: ' + esc(it.file.name) + '</span>'
          : (hasUrl
            ? '<span class="text-xs text-blue-700 block mt-1"><i class="fas fa-link ml-1"></i>مرفق محفوظ</span>'
            : '');
        var pagesHint = pageCountHint(it);
        row.innerHTML =
          '<div class="flex flex-wrap items-start gap-2 justify-between mb-2">' +
            '<label class="block text-xs font-medium text-gray-600 w-full">اسم المرفق</label>' +
            '<input type="text" class="dyn-att-label flex-1 min-w-[140px] px-3 py-2 border border-gray-300 rounded-lg text-sm" placeholder="مثال: عقد الإيجار" value="' + esc(it.label) + '">' +
            '<button type="button" class="dyn-att-remove text-red-600 hover:text-red-800 px-2 py-2" title="حذف"><i class="fas fa-trash"></i></button>' +
          '</div>' +
          '<input type="file" accept="image/*,application/pdf" class="dyn-att-file w-full px-3 py-2 border border-gray-300 rounded-lg text-sm bg-white">' +
          fileHint +
          pagesHint +
          (hasUrl
            ? '<a href="' + esc(it.url) + '" target="_blank" rel="noopener" class="inline-block mt-2 text-blue-600 text-xs hover:underline"><i class="fas fa-external-link-alt ml-1"></i>عرض الملف الحالي</a>'
            : '');
        var labelInput = row.querySelector('.dyn-att-label');
        var fileInput = row.querySelector('.dyn-att-file');
        var removeBtn = row.querySelector('.dyn-att-remove');
        labelInput.addEventListener('input', function () {
          it.label = String(labelInput.value || '').trim();
          syncHidden();
        });
        fileInput.addEventListener('change', function () {
          var file = fileInput.files && fileInput.files[0] ? fileInput.files[0] : null;
          if (!file) {
            it.file = null;
            it.page_count = null;
            it.page_count_pending = false;
            render();
            return;
          }
          if (file.size > MAX_FILE_BYTES) {
            fileInput.value = '';
            alert('الملف كبير جداً. الحد الأقصى ' + MAX_FILE_MB + 'MB');
            return;
          }
          it.file = file;
          it.page_count = null;
          it.page_count_pending = isPdfFile(file);
          render();
          if (isPdfFile(file)) {
            readPdfPageCount(file).then(function (count) {
              if (it.file !== file) return;
              it.page_count_pending = false;
              it.page_count = count;
              render();
              syncHidden();
            });
          }
        });
        removeBtn.addEventListener('click', function () {
          items.splice(index, 1);
          syncHidden();
          render();
          updateAddButton();
        });
        listEl.appendChild(row);
      });
      updateAddButton();
      syncHidden();
    }
    addBtn.addEventListener('click', function () {
      if (items.length >= MAX_ATTACHMENTS) return;
      items.push({ id: newId(), label: '', url: '', file: null, page_count: null, page_count_pending: false });
      render();
      updateAddButton();
    });
    window.uploadDynamicCustomerAttachments = async function (uploadOpts) {
      uploadOpts = uploadOpts || {};
      var onProgress = typeof uploadOpts.onProgress === 'function' ? uploadOpts.onProgress : function () {};
      for (var i = 0; i < items.length; i++) {
        var it = items[i];
        if (!it.file) continue;
        if (!String(it.label || '').trim()) {
          throw new Error('يرجى إدخال اسم لكل مرفق قبل الرفع');
        }
        onProgress('جاري رفع: ' + it.label);
        var formData = new FormData();
        formData.append('file', it.file);
        formData.append('attachment_id', it.id);
        if (customerId) formData.append('customer_id', customerId);
        var response = await fetch('/api/attachments/upload', {
          method: 'POST',
          body: formData,
          credentials: 'include'
        });
        var payload = await response.json();
        if (!response.ok || !payload.success || !payload.url) {
          throw new Error(payload.error || 'فشل رفع المرفق');
        }
        it.url = payload.url;
        it.file = null;
      }
      syncHidden();
      return items.filter(function (it) { return it.url; }).map(attachmentPayload);
    };
    render();
    updateAddButton();
  };
})();
`
}

function isMissingCustomerLocationIdColumnError(e: unknown): boolean {
  const m = String((e as Error)?.message ?? e ?? '')
  return m.includes('location_id') && (m.includes('no such column') || m.includes('no column named'))
}

const CUSTOMER_PRODUCT_TYPE_OPTIONS = [
  'شراء عقار',
  'رهن حر',
  'فك رهن',
  'شراء مديونية',
  'بناء ذاتي',
  'أرض وقرض',
  'قرض شخصي',
  'تمويل مؤسسات ( نقاط بيع)',
  'إعادة تمويل',
] as const

function normalizeCustomerJobType(raw: unknown): 'civilian' | 'military' | 'retired' {
  const v = String(raw ?? '').trim()
  if (v === 'military' || v === 'retired') return v
  return 'civilian'
}

function normalizeCustomerProductType(raw: unknown): string | null {
  const v = String(raw ?? '').trim()
  if (!v) return null
  return (CUSTOMER_PRODUCT_TYPE_OPTIONS as readonly string[]).includes(v) ? v : null
}

function renderCustomerProductTypeFieldHtml(
  selected: string | null | undefined,
  inputClass: string
): string {
  const sel = String(selected ?? '').trim()
  const options = [
    '<option value="">-- اختر نوع المنتج --</option>',
    ...CUSTOMER_PRODUCT_TYPE_OPTIONS.map((label) => {
      const esc = escapeHtml(label)
      const selectedAttr = label === sel ? ' selected' : ''
      return `<option value="${esc}"${selectedAttr}>${esc}</option>`
    }),
  ].join('')
  return `<select name="product_type" class="${escapeHtmlAttr(inputClass)}">${options}</select>`
}

const CUSTOMER_PROPERTY_TYPE_OPTIONS = [
  'ارض',
  'فيلا',
  'شقه',
  'عمارة تجاريه',
  'أرض زراعيه',
  'استراحة',
  'دور',
] as const

function normalizeCustomerPropertyType(raw: unknown): string | null {
  const v = String(raw ?? '').trim()
  if (!v) return null
  return (CUSTOMER_PROPERTY_TYPE_OPTIONS as readonly string[]).includes(v) ? v : null
}

function renderCustomerPropertyTypeFieldHtml(
  selected: string | null | undefined,
  inputClass: string
): string {
  const sel = String(selected ?? '').trim()
  const options = [
    '<option value="">-- اختر نوع العقار --</option>',
    ...CUSTOMER_PROPERTY_TYPE_OPTIONS.map((label) => {
      const esc = escapeHtml(label)
      const selectedAttr = label === sel ? ' selected' : ''
      return `<option value="${esc}"${selectedAttr}>${esc}</option>`
    }),
  ].join('')
  return `<select name="property_type" class="${escapeHtmlAttr(inputClass)}">${options}</select>`
}

function isMissingFinancingRequestLocationIdColumnError(e: unknown): boolean {
  const m = String((e as Error)?.message ?? e ?? '')
  return m.includes('location_id') && (m.includes('no such column') || m.includes('no column named'))
}

async function syncFinancingRequestsLocationForCustomer(
  db: any,
  customerId: string | number | null | undefined,
  locationId: number | null
) {
  if (!customerId) return
  try {
    await db
      .prepare(`UPDATE financing_requests SET location_id = ? WHERE customer_id = ?`)
      .bind(locationId, customerId)
      .run()
  } catch (e: unknown) {
    if (!isMissingFinancingRequestLocationIdColumnError(e)) throw e
  }
}

type AttachmentSyncPayload = {
  identity_attachment_url?: string | null
  signature_attachment_url?: string | null
  salary_profile_attachment_url?: string | null
  gosi_attachment_url?: string | null
  tax_exemption_attachment_url?: string | null
  additional_1_attachment_url?: string | null
  additional_2_attachment_url?: string | null
  additional_3_attachment_url?: string | null
}

async function syncAttachmentsForCustomer(
  db: any,
  customerId: string | number | null | undefined,
  attachments: AttachmentSyncPayload
) {
  if (!customerId) return

  const entries = Object.entries(attachments).filter(([, value]) => value !== undefined)
  if (entries.length === 0) return

  const setSql = entries.map(([column]) => `${column} = ?`).join(', ')
  const values = entries.map(([, value]) => value ?? null)

  try {
    await db.prepare(`
      UPDATE customers
      SET ${setSql}
      WHERE id = ?
    `).bind(...values, customerId).run()
  } catch (customerAttachmentError) {
    if (!isMissingCustomerAttachmentsColumnError(customerAttachmentError)) throw customerAttachmentError
  }

  await db.prepare(`
    UPDATE financing_requests
    SET ${setSql}
    WHERE customer_id = ?
  `).bind(...values, customerId).run()
}

function normalizeArabicAndPersianDigits(value: string): string {
  return value
    .replace(/[٠-٩]/g, (d) => String(d.charCodeAt(0) - 1632))
    .replace(/[۰-۹]/g, (d) => String(d.charCodeAt(0) - 1776))
}

function normalizeCustomerPhoneForStorage(rawPhone: string | null | undefined): { normalized: string | null; error: string | null } {
  const raw = normalizeArabicAndPersianDigits(String(rawPhone ?? '').trim())
  let digits = raw.replace(/[^\d]/g, '')
  if (!digits) {
    return { normalized: null, error: 'يرجى إدخال رقم الجوال (بدون +966). مثال صحيح: 5XXXXXXXX' }
  }

  if (digits.startsWith('00966')) {
    digits = digits.slice(2)
  } else if (!digits.startsWith('966')) {
    digits = `966${digits.replace(/^0+/, '')}`
  }

  const localPart = digits.startsWith('966') ? digits.slice(3) : digits
  if (!/^5\d{8}$/.test(localPart)) {
    return {
      normalized: null,
      error: 'صيغة رقم الجوال غير صحيحة. أدخل 9 أرقام تبدأ بـ 5 فقط (بدون +966). الصيغة: 5XXXXXXXX'
    }
  }

  return { normalized: `966${localPart}`, error: null }
}

function customerPhoneInputValue(rawPhone: string | null | undefined): string {
  const digits = normalizeArabicAndPersianDigits(String(rawPhone ?? '').trim()).replace(/[^\d]/g, '')
  if (!digits) return ''
  if (digits.startsWith('00966')) return digits.slice(5)
  if (digits.startsWith('966')) return digits.slice(3)
  if (digits.startsWith('05') && digits.length === 10) return digits.slice(1)
  return digits
}

const RESERVED_ROOT_SLUGS = new Set([
  'admin',
  'api',
  'c',
  'calculator',
  'calculator-old',
  'contracts-module',
  'forgot-password',
  'login',
  'packages',
  'subscribe',
  'test'
])

function normalizeTenantSlug(value: unknown): string {
  return String(value ?? '').trim().toLowerCase()
}

function isReservedRootSlug(slug: string): boolean {
  return RESERVED_ROOT_SLUGS.has(slug)
}

/** URL segment for a branch location under /{companySlug}/{locationSlug}/… */
function deriveLocationSlugFromName(name: string, tenantSlugFallback: string): string {
  const latin = String(name ?? '')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, '')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 64)
  if (latin) return latin
  const fb = normalizeTenantSlug(tenantSlugFallback)
  return fb || 'main'
}

async function ensureUniqueTenantLocationSlug(
  db: D1Database,
  tenantId: number,
  baseSlug: string
): Promise<string> {
  let candidate = normalizeTenantSlug(baseSlug) || 'location'
  if (!candidate || isReservedRootSlug(candidate)) {
    candidate = 'loc-' + (candidate || 'branch')
  }
  for (let i = 0; i < 60; i++) {
    const suffix = i === 0 ? '' : `-${i + 1}`
    const trySlug = (candidate + suffix).slice(0, 64)
    const row = await db
      .prepare(`SELECT id FROM tenant_locations WHERE tenant_id = ? AND slug = ? LIMIT 1`)
      .bind(tenantId, trySlug)
      .first<{ id: number }>()
    if (!row) return trySlug
  }
  return `${candidate}-${Date.now()}`.slice(0, 64)
}

function escapeHtml(value: unknown): string {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;')
}

/** For double-quoted HTML attributes (not full HTML escaping of URL schemes). */
function escapeHtmlAttr(value: unknown): string {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/"/g, '&quot;')
}

/** For href/src and other attributes (alias used in attachment list HTML). */
function escapeAttr(value: unknown): string {
  return escapeHtml(value)
}

function contractStatusBadge(status: string | null | undefined): string {
  if (!status) return '<span class="text-xs text-gray-400">لا يوجد عقد</span>'
  const map: Record<string, string> = {
    'نشط': 'bg-green-100 text-green-800 border-green-200',
    'بانتظار موافقة ممثل البنك': 'bg-amber-100 text-amber-800 border-amber-200',
    'بانتظار موافقة الإدارة': 'bg-blue-100 text-blue-800 border-blue-200',
    'بانتظار التمويل': 'bg-purple-100 text-purple-800 border-purple-200',
    'مكتمل': 'bg-teal-100 text-teal-800 border-teal-200',
    'مؤرشف': 'bg-gray-100 text-gray-600 border-gray-200',
  }
  const cls = map[status] ?? 'bg-gray-100 text-gray-700 border-gray-200'
  return `<span class="inline-block text-xs font-semibold px-2 py-0.5 rounded-full border ${cls}">${escapeHtml(status)}</span>`
}

/** Saudi mobile digits only (9665xxxxxxxx); null if not a valid KSA mobile after normalization. */
function normalizePublicContactPhoneDigits(rawPhone: string): string | null {
  const n = normalizeArabicAndPersianDigits(String(rawPhone ?? '').trim())
  let d = n.replace(/[^\d]/g, '')
  if (!d) return null
  if (d.startsWith('00966')) d = d.slice(5)
  else if (d.startsWith('966')) d = d.slice(3)
  else if (d.startsWith('05') && d.length === 10) d = d.slice(1)
  else if (d.startsWith('0')) d = d.replace(/^0+/, '')
  // Prepend country code for bare local numbers
  if (d.length === 9 && d.startsWith('5')) d = '966' + d             // mobile: 5XXXXXXXX
  else if (d.length === 9 && /^1[1-9]/.test(d)) d = '966' + d        // geographic landline: 1XYYYYYYY
  else if (d.length === 9 && d.startsWith('920')) d = '966' + d       // unified commercial: 920XXXXXX
  if (/^9665\d{8}$/.test(d)) return d          // Saudi mobile
  if (/^9661[1-9]\d{7}$/.test(d)) return d     // Saudi geographic landline (area codes 11–19)
  if (/^966920\d{6}$/.test(d)) return d        // Saudi unified commercial (920)
  return null
}

/** WhatsApp chat URL — only for Saudi mobile numbers (landlines don't support WhatsApp). */
function buildPublicWhatsappHref(rawPhone: string): string | null {
  const d = normalizePublicContactPhoneDigits(rawPhone)
  if (!d || !/^9665\d{8}$/.test(d)) return null
  return `https://wa.me/${d}`
}

function normalizeAffiliatePathSegment(value: unknown): string {
  return String(value ?? '')
    .trim()
    .toLowerCase()
    .replace(/^\/+/g, '')
}

function isValidAffiliatePathSegment(seg: string): boolean {
  if (!seg || seg.length > 64) return false
  if (!/^[a-z0-9_-]+$/.test(seg)) return false
  if (RESERVED_ROOT_SLUGS.has(seg)) return false
  return true
}

/** Label for contact follow-ups submitted via the tenant root contact URL (no affiliate path). */
const CONTACT_COMPANY_LINK_SOURCE_LABEL = 'رابط الشركة'

function resolveContactFollowupSourceLabel(
  affiliateLabel: unknown,
  affiliatePathSegment: unknown
): string {
  const label = String(affiliateLabel ?? '').trim()
  if (label) return label
  const path = String(affiliatePathSegment ?? '').trim()
  if (!path) return CONTACT_COMPANY_LINK_SOURCE_LABEL
  return ''
}

function normalizeContactFollowupRowForApi<T extends Record<string, unknown>>(row: T): T {
  if (!row || typeof row !== 'object') return row
  const resolved = resolveContactFollowupSourceLabel(row.affiliate_label, row.affiliate_path_segment)
  if (!resolved) return row
  return { ...row, affiliate_label: resolved }
}

const MAX_TENANT_LOGO_URL_LEN = 2000
const MAX_TENANT_ADDRESS_LEN = 2000

function normalizeTenantAddressField(raw: unknown): { ok: true; value: string | null } | { ok: false; error: string } {
  if (raw == null || String(raw).trim() === '') return { ok: true, value: null }
  const s = String(raw).trim()
  if (s.length > MAX_TENANT_ADDRESS_LEN) {
    return { ok: false, error: `العنوان يتجاوز ${MAX_TENANT_ADDRESS_LEN} حرفاً` }
  }
  return { ok: true, value: s }
}

function normalizeTenantCityField(raw: unknown): { ok: true; value: string | null } | { ok: false; error: string } {
  if (raw == null || String(raw).trim() === '') return { ok: true, value: null }
  const t = String(raw).trim()
  if (!isValidSaudiCityName(t)) {
    return { ok: false, error: 'يرجى اختيار مدينة من القائمة' }
  }
  return { ok: true, value: t }
}

/** Accepts https/http absolute URLs or same-origin paths (e.g. `/api/attachments/...`). */
function normalizeTenantLogoUrl(raw: unknown): string | null {
  const s = String(raw ?? '').trim()
  if (!s) return null
  if (s.length > MAX_TENANT_LOGO_URL_LEN) return null
  if (s.includes('..') || s.includes('\\')) return null
  if (/^https?:\/\//i.test(s)) {
    try {
      const u = new URL(s)
      if (u.protocol !== 'http:' && u.protocol !== 'https:') return null
      return s
    } catch {
      return null
    }
  }
  if (s.startsWith('/')) {
    if (!/^\/[\w\-./?=&%:#+]*$/i.test(s)) return null
    return s
  }
  return null
}

function clampWatermarkOpacity(raw: unknown, fallback = 0.12): number {
  const n = Number(raw)
  if (!Number.isFinite(n)) return fallback
  return Math.min(1, Math.max(0.03, n))
}

/** Letterhead header/footer opacity: 10%–100%, default 100%. */
function clampLetterheadOpacity(raw: unknown, fallback = 1): number {
  const n = Number(raw)
  if (!Number.isFinite(n)) return fallback
  return Math.min(1, Math.max(0.1, n))
}

function formatTenantDocumentBrandingFields(row: {
  document_watermark_url?: string | null
  document_watermark_enabled?: number | null
  document_watermark_opacity?: number | null
  document_header_url?: string | null
  document_header_enabled?: number | null
  document_header_opacity?: number | null
  document_footer_url?: string | null
  document_footer_enabled?: number | null
  document_footer_opacity?: number | null
}) {
  return {
    document_watermark_url: row.document_watermark_url ?? null,
    document_watermark_enabled: Number(row.document_watermark_enabled) === 1,
    document_watermark_opacity: clampWatermarkOpacity(row.document_watermark_opacity, 0.12),
    document_header_url: row.document_header_url ?? null,
    document_header_enabled: Number(row.document_header_enabled) === 1,
    document_header_opacity: clampLetterheadOpacity(row.document_header_opacity, 1),
    document_footer_url: row.document_footer_url ?? null,
    document_footer_enabled: Number(row.document_footer_enabled) === 1,
    document_footer_opacity: clampLetterheadOpacity(row.document_footer_opacity, 1),
  }
}

type PublicContactTenantRow = {
  company_name: string
  slug: string
  contact_email: string | null
  contact_phone: string | null
  primary_color: string | null
  secondary_color: string | null
  logo_url: string | null
  /** Branch / marketing location — shown under title */
  public_city?: string | null
  public_address?: string | null
  /** Optional solid background color for the contact page (overrides primary/secondary gradient) */
  contact_bg_color?: string | null
  /** Optional solid background color for the form card (overrides white) */
  contact_form_color?: string | null
  /** Text color for form fields: 'white' | 'black' | null (null = default dark) */
  contact_text_color?: string | null
  /** JSON array of up to 3 custom fields: [{label:string, required:boolean}] */
  contact_custom_fields?: string | null
  /** Full-bleed background image URL (overrides bg color) */
  contact_bg_image_url?: string | null
  /** JSON array of trust badge objects {icon, text} shown below the form */
  contact_trust_badges?: string | null
  /** JSON array of trust badge objects {icon, text} shown inside the form, above the divider line */
  contact_form_badges?: string | null
  /** Hero title shown above the form card (default: أرسل بياناتك) */
  contact_hero_title?: string | null
  /** Hero subtitle shown above the form card in accent color */
  contact_hero_subtitle?: string | null
  /** Accent color for divider lines, subtitle, and badge icons */
  contact_accent_color?: string | null
}

function pickFirstNonEmptyContactField(
  ...vals: Array<string | null | undefined>
): string | null {
  for (const v of vals) {
    if (v != null && String(v).trim() !== '') return String(v).trim()
  }
  return null
}

type ContactPageDesignFields = {
  contact_bg_color: string | null
  contact_form_color: string | null
  contact_text_color: string | null
  contact_custom_fields: string | null
  contact_bg_image_url?: string | null
  contact_logo_url?: string | null
  contact_trust_badges?: string | null
  contact_form_badges?: string | null
  contact_hero_title?: string | null
  contact_hero_subtitle?: string | null
  contact_accent_color?: string | null
}

type AffiliateContactLinkRow = {
  id: number
  path_segment: string
  label: string
} & ContactPageDesignFields

/** Apply an affiliate link's isolated contact-page design onto the tenant branding row. */
function withAffiliateContactDesign(
  tenant: PublicContactTenantRow,
  affiliate: ContactPageDesignFields | null | undefined
): PublicContactTenantRow {
  if (!affiliate) return tenant
  return {
    ...tenant,
    contact_bg_color: affiliate.contact_bg_color ?? tenant.contact_bg_color,
    contact_form_color: affiliate.contact_form_color ?? tenant.contact_form_color,
    contact_text_color: affiliate.contact_text_color ?? tenant.contact_text_color,
    contact_custom_fields: affiliate.contact_custom_fields ?? tenant.contact_custom_fields,
    contact_bg_image_url: affiliate.contact_bg_image_url ?? tenant.contact_bg_image_url ?? null,
    contact_trust_badges: affiliate.contact_trust_badges ?? tenant.contact_trust_badges ?? null,
    contact_form_badges: affiliate.contact_form_badges ?? tenant.contact_form_badges ?? null,
    contact_hero_title: affiliate.contact_hero_title ?? tenant.contact_hero_title ?? null,
    contact_hero_subtitle: affiliate.contact_hero_subtitle ?? tenant.contact_hero_subtitle ?? null,
    contact_accent_color: affiliate.contact_accent_color ?? tenant.contact_accent_color ?? null,
    logo_url: affiliate.contact_logo_url ?? tenant.logo_url,
  }
}

async function recordContactLinkVisit(
  db: D1Database,
  tenantId: number,
  affiliateLinkId: number | null
): Promise<void> {
  try {
    await db.prepare(`
      INSERT INTO contact_link_visits (tenant_id, affiliate_link_id, visit_date, visit_count)
      VALUES (?, ?, date('now'), 1)
      ON CONFLICT(tenant_id, affiliate_link_id, visit_date)
      DO UPDATE SET visit_count = visit_count + 1
    `).bind(tenantId, affiliateLinkId ?? 0).run()
  } catch (_) {
    // Do not make the public contact page unavailable while a migration is being deployed.
  }
}

function isAnonymousPublicContactView(c: any): boolean {
  return !c.req.header('Authorization') && !String(c.req.header('Cookie') ?? '').includes('authToken=')
}

function hasCookie(cookieHeader: string, name: string): boolean {
  for (const part of cookieHeader.split(';')) {
    const trimmed = part.trimStart()
    if (trimmed.startsWith(name + '=') || trimmed === name) return true
  }
  return false
}

/** Records a unique visit (per browser, per day) using a short-lived cookie to deduplicate refreshes. */
async function recordContactLinkVisitWithDedup(
  c: any,
  db: D1Database,
  tenantId: number,
  affiliateLinkId: number | null
): Promise<void> {
  if (!isAnonymousPublicContactView(c)) return
  const cookieName = `vlv_${affiliateLinkId ?? 0}`
  const cookieHeader = String(c.req.header('Cookie') ?? '')
  if (hasCookie(cookieHeader, cookieName)) return
  await recordContactLinkVisit(db, tenantId, affiliateLinkId)
  c.header('Set-Cookie', `${cookieName}=1; Max-Age=86400; Path=/; HttpOnly; SameSite=Lax`)
}

async function recordContactLinkFormInitiation(
  db: D1Database,
  tenantId: number,
  affiliateLinkId: number | null
): Promise<void> {
  try {
    await db.prepare(`
      INSERT INTO contact_link_form_initiations (tenant_id, affiliate_link_id, initiation_date, initiation_count)
      VALUES (?, ?, date('now'), 1)
      ON CONFLICT(tenant_id, affiliate_link_id, initiation_date)
      DO UPDATE SET initiation_count = initiation_count + 1
    `).bind(tenantId, affiliateLinkId ?? 0).run()
  } catch (_) {
    // Do not block the public contact form while a migration is being deployed.
  }
}

/** Records a unique form initiation (per browser, per day) when the visitor first types in a field. */
async function recordContactLinkFormInitiationWithDedup(
  c: any,
  db: D1Database,
  tenantId: number,
  affiliateLinkId: number | null
): Promise<void> {
  if (!isAnonymousPublicContactView(c)) return
  const cookieName = `vfi_${affiliateLinkId ?? 0}`
  const cookieHeader = String(c.req.header('Cookie') ?? '')
  if (hasCookie(cookieHeader, cookieName)) return
  await recordContactLinkFormInitiation(db, tenantId, affiliateLinkId)
  c.header('Set-Cookie', `${cookieName}=1; Max-Age=86400; Path=/; HttpOnly; SameSite=Lax`)
}

const CONTACT_FORM_BUILTIN_FIELD_KEYS = new Set(['name', 'phone', 'message'])

/** Sanitize field keys from abandon beacons (keys only — never values). */
function normalizeContactFormAbandonFieldKeys(raw: unknown): string[] {
  if (!Array.isArray(raw)) return []
  const out: string[] = []
  const seen = new Set<string>()
  for (const item of raw) {
    if (out.length >= 12) break
    const key = String(item ?? '').trim().slice(0, 80)
    if (!key || seen.has(key)) continue
    if (CONTACT_FORM_BUILTIN_FIELD_KEYS.has(key) || key.startsWith('cf:')) {
      seen.add(key)
      out.push(key)
    }
  }
  return out
}

function parseContactCustomFieldLabels(raw: string | null | undefined): string[] {
  if (!raw) return []
  try {
    const parsed = JSON.parse(raw)
    if (!Array.isArray(parsed)) return []
    return parsed
      .filter((f: any) => f && typeof f === 'object' && String(f.label || '').trim())
      .slice(0, 3)
      .map((f: any) => String(f.label).trim())
  } catch {
    return []
  }
}

/** Form-order field list for abandon stats (built-ins + current custom labels). */
function buildContactFormFieldOrder(customLabels: string[]): { key: string; label: string }[] {
  return [
    { key: 'name', label: 'الاسم' },
    { key: 'phone', label: 'رقم الجوال' },
    ...customLabels.map((label) => ({ key: `cf:${label}`, label })),
    { key: 'message', label: 'رسالتك' },
  ]
}

async function recordContactLinkFormAbandon(
  db: D1Database,
  tenantId: number,
  affiliateLinkId: number | null,
  fieldKeys: string[]
): Promise<void> {
  const linkId = affiliateLinkId ?? 0
  try {
    const stmts = [
      db.prepare(`
        INSERT INTO contact_link_form_abandons (tenant_id, affiliate_link_id, abandon_date, abandon_count)
        VALUES (?, ?, date('now'), 1)
        ON CONFLICT(tenant_id, affiliate_link_id, abandon_date)
        DO UPDATE SET abandon_count = abandon_count + 1
      `).bind(tenantId, linkId),
    ]
    for (const fieldKey of fieldKeys) {
      stmts.push(
        db.prepare(`
          INSERT INTO contact_link_form_field_fills (tenant_id, affiliate_link_id, field_key, fill_date, fill_count)
          VALUES (?, ?, ?, date('now'), 1)
          ON CONFLICT(tenant_id, affiliate_link_id, field_key, fill_date)
          DO UPDATE SET fill_count = fill_count + 1
        `).bind(tenantId, linkId, fieldKey)
      )
    }
    await db.batch(stmts)
  } catch (_) {
    // Do not block the public contact form while a migration is being deployed.
  }
}

/** Records a unique abandon (per browser, per day) with which fields were filled — submitters are never counted. */
async function recordContactLinkFormAbandonWithDedup(
  c: any,
  db: D1Database,
  tenantId: number,
  affiliateLinkId: number | null,
  fieldKeys: string[]
): Promise<void> {
  if (!isAnonymousPublicContactView(c)) return
  const cookieName = `vfa_${affiliateLinkId ?? 0}`
  const cookieHeader = String(c.req.header('Cookie') ?? '')
  if (hasCookie(cookieHeader, cookieName)) return
  await recordContactLinkFormAbandon(db, tenantId, affiliateLinkId, fieldKeys)
  c.header('Set-Cookie', `${cookieName}=1; Max-Age=86400; Path=/; HttpOnly; SameSite=Lax`)
}

/**
 * Parse contact page design fields from a PATCH/POST body.
 * Only keys present on `body` are included in `updates`.
 */
function parseContactDesignBodyFields(
  body: Record<string, unknown>
): { ok: true; updates: Partial<ContactPageDesignFields> } | { ok: false; error: string } {
  const updates: Partial<ContactPageDesignFields> = {}
  if ('contact_bg_color' in body) {
    const raw = String(body.contact_bg_color ?? '').trim()
    if (raw === '') {
      updates.contact_bg_color = null
    } else if (/^#[0-9a-fA-F]{3,8}$/.test(raw)) {
      updates.contact_bg_color = raw
    } else {
      return { ok: false, error: 'لون الخلفية غير صالح، استخدم صيغة hex مثل #0f766e' }
    }
  }
  if ('contact_form_color' in body) {
    const raw = String(body.contact_form_color ?? '').trim()
    if (raw === '') {
      updates.contact_form_color = null
    } else if (/^#[0-9a-fA-F]{3,8}$/.test(raw)) {
      updates.contact_form_color = raw
    } else {
      return { ok: false, error: 'لون النافذة غير صالح، استخدم صيغة hex مثل #ffffff' }
    }
  }
  if ('contact_text_color' in body) {
    const raw = String(body.contact_text_color ?? '').trim()
    if (raw === '' || raw === 'black') {
      updates.contact_text_color = raw === '' ? null : 'black'
    } else if (raw === 'white') {
      updates.contact_text_color = 'white'
    } else {
      return { ok: false, error: 'لون النص يجب أن يكون black أو white' }
    }
  }
  if ('contact_custom_fields' in body) {
    const raw = body.contact_custom_fields
    if (raw == null || (Array.isArray(raw) && raw.length === 0)) {
      updates.contact_custom_fields = null
    } else if (Array.isArray(raw)) {
      const items = (raw as any[])
        .filter((f: any) => f && typeof f === 'object' && String(f.label ?? '').trim())
        .slice(0, 3)
        .map((f: any) => {
          const type = ['text', 'number', 'select', 'checkbox'].includes(String(f.type || 'text'))
            ? String(f.type)
            : 'text'
          return { label: String(f.label).trim().slice(0, 100), required: !!f.required, type }
        })
      updates.contact_custom_fields = items.length > 0 ? JSON.stringify(items) : null
    } else {
      return { ok: false, error: 'contact_custom_fields يجب أن يكون مصفوفة' }
    }
  }
  if ('contact_trust_badges' in body) {
    const VALID_ICONS = new Set([
      'fas fa-shield-alt', 'fas fa-bolt', 'fas fa-check-circle', 'fas fa-star',
      'fas fa-lock', 'fas fa-handshake', 'fas fa-gem', 'fas fa-award',
      'fas fa-phone', 'fas fa-clock'
    ])
    const raw = body.contact_trust_badges
    if (raw == null) {
      updates.contact_trust_badges = null
    } else if (Array.isArray(raw)) {
      const items = (raw as any[])
        .map((x: any) => {
          const iconRaw = x?.icon == null || String(x.icon).trim() === '' ? null : String(x.icon).trim()
          if (iconRaw !== null && !VALID_ICONS.has(iconRaw)) return null
          return { icon: iconRaw, text: String(x?.text ?? '').trim() }
        })
        .filter((x): x is { icon: string | null; text: string } => x !== null && x.text.length > 0)
        .slice(0, 4)
      updates.contact_trust_badges = JSON.stringify(items)
    } else {
      return { ok: false, error: 'contact_trust_badges يجب أن يكون مصفوفة' }
    }
  }
  if ('contact_form_badges' in body) {
    const VALID_ICONS = new Set([
      'fas fa-shield-alt', 'fas fa-bolt', 'fas fa-check-circle', 'fas fa-star',
      'fas fa-lock', 'fas fa-handshake', 'fas fa-gem', 'fas fa-award',
      'fas fa-phone', 'fas fa-clock'
    ])
    const raw = body.contact_form_badges
    if (raw == null || (Array.isArray(raw) && raw.length === 0)) {
      updates.contact_form_badges = null
    } else if (Array.isArray(raw)) {
      const items = (raw as any[])
        .map((x: any) => {
          const iconRaw = x?.icon == null || String(x.icon).trim() === '' ? null : String(x.icon).trim()
          if (iconRaw !== null && !VALID_ICONS.has(iconRaw)) return null
          return { icon: iconRaw, text: String(x?.text ?? '').trim() }
        })
        .filter((x): x is { icon: string | null; text: string } => x !== null && x.text.length > 0)
        .slice(0, 3)
      updates.contact_form_badges = JSON.stringify(items)
    } else {
      return { ok: false, error: 'contact_form_badges يجب أن يكون مصفوفة' }
    }
  }
  if ('contact_hero_title' in body) {
    const raw = body.contact_hero_title
    updates.contact_hero_title = (raw == null || String(raw).trim() === '') ? null : String(raw).trim().slice(0, 80)
  }
  if ('contact_hero_subtitle' in body) {
    const raw = body.contact_hero_subtitle
    updates.contact_hero_subtitle = (raw == null || String(raw).trim() === '') ? null : String(raw).trim().slice(0, 80)
  }
  if ('contact_accent_color' in body) {
    const raw = String(body.contact_accent_color ?? '').trim()
    if (raw === '') {
      updates.contact_accent_color = null
    } else if (/^#[0-9a-fA-F]{3,8}$/.test(raw)) {
      updates.contact_accent_color = raw
    } else {
      return { ok: false, error: 'لون التمييز غير صالح، استخدم صيغة hex مثل #d97706' }
    }
  }
  return { ok: true, updates }
}

function mergePublicContactForLocation(
  tenant: PublicContactTenantRow & { id?: number },
  loc: {
    name: string
    city: string
    address: string
    contact_phone: string | null
    contact_email: string | null
    logo_url: string | null
  },
  primary: {
    contact_phone: string | null
    contact_email: string | null
    logo_url: string | null
  } | null
): PublicContactTenantRow {
  return {
    company_name: loc.name,
    slug: tenant.slug,
    contact_email: pickFirstNonEmptyContactField(
      loc.contact_email,
      primary?.contact_email,
      tenant.contact_email
    ),
    contact_phone: pickFirstNonEmptyContactField(
      loc.contact_phone,
      primary?.contact_phone,
      tenant.contact_phone
    ),
    logo_url: pickFirstNonEmptyContactField(loc.logo_url, primary?.logo_url, tenant.logo_url),
    primary_color: tenant.primary_color,
    secondary_color: tenant.secondary_color,
    public_city: loc.city,
    public_address: loc.address,
    contact_bg_color: tenant.contact_bg_color ?? null,
    contact_form_color: tenant.contact_form_color ?? null,
    contact_text_color: tenant.contact_text_color ?? null,
    contact_custom_fields: tenant.contact_custom_fields ?? null,
  }
}

function buildPublicContactPageHtml(
  tenant: PublicContactTenantRow,
  affiliate: null | { path_segment: string; label: string },
  opts?: { locationSlug?: string | null }
): string {
  const companyName = escapeHtml(tenant.company_name)
  const phoneRaw = String(tenant.contact_phone ?? '').trim()
  const emailRaw = String(tenant.contact_email ?? '').trim()
  const contactEmail = escapeHtml(emailRaw)
  const contactPhone = escapeHtml(phoneRaw)
  const waHref = buildPublicWhatsappHref(phoneRaw)
  const waHrefAttr = waHref ? escapeHtmlAttr(waHref) : ''
  const telHref = phoneRaw && !waHref ? `tel:+${phoneRaw}` : null
  const telHrefAttr = telHref ? escapeHtmlAttr(telHref) : ''
  const primaryColor = escapeHtml(tenant.primary_color || '#0f766e')
  const secondaryColor = escapeHtml(tenant.secondary_color || '#14b8a6')
  const bgStyle = tenant.contact_bg_image_url
    ? `background:url(${escapeHtmlAttr(tenant.contact_bg_image_url)}) center/cover no-repeat;`
    : tenant.contact_bg_color
      ? `background:${escapeHtmlAttr(tenant.contact_bg_color)};`
      : `background:linear-gradient(135deg,${primaryColor},${secondaryColor});`
  const formCardStyle = tenant.contact_form_color
    ? `background:${escapeHtmlAttr(tenant.contact_form_color)};`
    : 'background:#ffffff;'
  const isWhiteText = tenant.contact_text_color === 'white'
  const textColorCss = isWhiteText ? `
    <style>
      #contactForm label, #contactForm .block { color: rgba(255,255,255,0.88) !important; }
      #contactForm p, #contactForm span.text-xs { color: rgba(255,255,255,0.65) !important; }
      .field-icon-wrap { border-color: rgba(255,255,255,0.25) !important; background: rgba(255,255,255,0.05); }
      .field-icon-wrap input, .field-icon-wrap textarea {
        color: #ffffff !important;
        background-color: transparent !important;
      }
      .field-icon-wrap input::placeholder, .field-icon-wrap textarea::placeholder { color: rgba(255,255,255,0.45) !important; }
      .field-icon-wrap .fi { background: rgba(255,255,255,0.08) !important; border-color: rgba(255,255,255,0.2) !important; color: rgba(255,255,255,0.5) !important; }
      .phone-prefix { background: rgba(255,255,255,0.12) !important; border-color: rgba(255,255,255,0.2) !important; color: rgba(255,255,255,0.85) !important; }
      .section-divider span { color: rgba(255,255,255,0.9) !important; }
      .trust-item { color: rgba(255,255,255,0.6) !important; }
      .trust-row { border-color: rgba(255,255,255,0.12) !important; }
    </style>` : ''
  const affiliatePathJson = JSON.stringify(affiliate?.path_segment ?? null)
  const locationSlugJson = JSON.stringify(opts?.locationSlug ?? null)
  const logoNorm = normalizeTenantLogoUrl(tenant.logo_url)
  const logoAttr = logoNorm ? escapeHtmlAttr(logoNorm) : ''

  // Parse custom fields
  type CustomField = { label: string; required: boolean; type?: string }
  let customFields: CustomField[] = []
  if (tenant.contact_custom_fields) {
    try {
      const parsed = JSON.parse(tenant.contact_custom_fields)
      if (Array.isArray(parsed)) {
        customFields = parsed
          .filter((f: any) => f && typeof f === 'object' && String(f.label || '').trim())
          .slice(0, 3)
          .map((f: any) => {
            const type = ['text', 'number', 'select', 'checkbox'].includes(String(f.type || 'text'))
              ? String(f.type)
              : 'text'
            return { label: String(f.label).trim(), required: !!f.required, type }
          })
      }
    } catch (_) {}
  }
  const customFieldsJson = JSON.stringify(customFields)

  // Responsive grid class for custom fields
  const customFieldsGridClass =
    customFields.length === 3
      ? 'grid grid-cols-1 sm:grid-cols-3 gap-4'
      : customFields.length === 2
        ? 'grid grid-cols-1 sm:grid-cols-2 gap-4'
        : ''

  const customFieldsHtml = customFields.length > 0
    ? `<div class="${customFieldsGridClass}">
        ${customFields.map((f, i) => {
          const fieldType = f.type || 'text'
          if (fieldType === 'checkbox') {
            return `
          <div class="flex items-end">
            <label class="flex items-center gap-2 text-sm font-medium text-gray-700 cursor-pointer select-none">
              <input id="custom_field_${i}" type="checkbox"
                class="rounded border-gray-300 text-emerald-600 focus:ring-emerald-500 h-4 w-4"
                ${f.required ? 'required' : ''} />
              ${escapeHtml(f.label)}${f.required ? '<span class="text-red-500 mr-1">*</span>' : ''}
            </label>
          </div>`
          }
          const inputType = fieldType === 'number' ? 'number' : 'text'
          const inputMode = fieldType === 'number' ? ' inputmode="numeric"' : ''
          return `
          <div>
            <label class="block text-sm font-medium text-gray-700 mb-2">
              ${escapeHtml(f.label)}${f.required ? '<span class="text-red-500 mr-1">*</span>' : ''}
            </label>
            <input id="custom_field_${i}" type="${inputType}"${inputMode}
              class="w-full border border-gray-300 rounded-lg px-4 py-3 focus:outline-none focus:ring-2 focus:ring-emerald-500"
              placeholder="${escapeHtmlAttr(f.label)}"
              ${f.required ? 'required' : ''} />
          </div>`
        }).join('')}
      </div>`
    : ''

  const hasBgImage = !!tenant.contact_bg_image_url
  const headerOnDark = hasBgImage || !!tenant.contact_bg_color
  const headerTextColor = isWhiteText || headerOnDark ? 'rgba(255,255,255,0.95)' : '#111827'
  const headerSubColor = isWhiteText || headerOnDark ? 'rgba(255,255,255,0.7)' : '#4b5563'
  const accentColor = escapeHtml((tenant.contact_accent_color ?? null) || '#d97706')
  const submitBtnStyle = `background:${accentColor};color:#fff;`
  const locationStr = [tenant.public_city, tenant.public_address].filter(Boolean).join(' — ')

  // Build badges HTML — shared helper
  type BadgeItem = { icon: string | null; text: string }
  const DEFAULT_BADGES: BadgeItem[] = [
    { icon: 'fas fa-shield-alt', text: 'سرية تامة' },
    { icon: 'fas fa-bolt', text: 'رد سريع' },
    { icon: 'fas fa-check-circle', text: 'استشارة مجانية' },
  ]
  function buildBadgesInner(jsonStr: string | null | undefined, useDefault: boolean): string {
    let badges: BadgeItem[] | null = null
    if (jsonStr) {
      try {
        const parsed = JSON.parse(jsonStr)
        if (Array.isArray(parsed)) {
          badges = parsed.map((x: any) =>
            typeof x === 'string'
              ? { icon: 'fas fa-check-circle', text: String(x) }
              : { icon: (x?.icon == null || String(x.icon).trim() === '') ? null : String(x.icon).trim(), text: String(x?.text ?? '') }
          ).filter(x => x.text)
        }
      } catch { /* ignore */ }
    }
    if (badges === null) badges = useDefault ? DEFAULT_BADGES : []
    if (badges.length === 0) return ''
    return badges.map((b) =>
      `<div class="trust-item">${b.icon ? `<i class="${escapeHtmlAttr(b.icon)}" style="color:${accentColor};"></i>` : ''}<span>${escapeHtml(b.text)}</span></div>`
    ).join('')
  }
  // Below the divider line — uses default badges if none configured
  const badgesInner = buildBadgesInner(tenant.contact_trust_badges, true)
  // Inside the form, above the divider line — only shown if explicitly configured (no default)
  const formBadgesInner = buildBadgesInner(tenant.contact_form_badges, false)

  return `
    <!DOCTYPE html>
    <html lang="ar" dir="rtl">
    <head>
      <meta charset="UTF-8">
      <meta name="viewport" content="width=device-width, initial-scale=1.0">
      <title>تواصل مع ${companyName}</title>
      <script src="https://cdn.tailwindcss.com"></script>
      <link href="https://cdn.jsdelivr.net/npm/@fortawesome/fontawesome-free@6.4.0/css/all.min.css" rel="stylesheet">
      ${textColorCss}
      <style>
        .field-icon-wrap { display:flex; align-items:center; border:1px solid #d1d5db; border-radius:0.75rem; overflow:hidden; transition:box-shadow .15s; }
        .field-icon-wrap:focus-within { box-shadow:0 0 0 2px ${escapeHtmlAttr(primaryColor)}40; border-color:${escapeHtmlAttr(primaryColor)}; }
        .field-icon-wrap input, .field-icon-wrap textarea { flex:1; padding:.75rem 1rem; border:0; outline:none; background:transparent; min-width:0; }
        .field-icon-wrap .fi { display:flex; align-items:center; justify-content:center; width:2.75rem; background:#f9fafb; border-left:1px solid #e5e7eb; color:#9ca3af; flex-shrink:0; align-self:stretch; }
        .field-icon-wrap textarea { resize:none; }
        .phone-prefix { display:flex; align-items:center; padding:0 .75rem; background:#f3f4f6; border-right:1px solid #e5e7eb; color:#374151; font-weight:600; font-size:.9rem; white-space:nowrap; flex-shrink:0; }
        .submit-btn { width:100%; padding:.9rem 1.5rem; border-radius:.75rem; font-size:1.1rem; font-weight:700; border:0; cursor:pointer; display:flex; align-items:center; justify-content:center; gap:.6rem; transition:opacity .15s,transform .1s; }
        .submit-btn:hover { opacity:.9; }
        .submit-btn:active { transform:scale(.99); }
        .submit-btn:disabled { opacity:.6; cursor:not-allowed; }
        .trust-row { display:flex; align-items:center; justify-content:center; gap:0.65rem 1rem; flex-wrap:wrap; padding:1.25rem 0.15rem 0.35rem; margin-top:1.25rem; border-top:1px solid rgba(0,0,0,0.07); }
        .trust-item { display:inline-flex; align-items:center; gap:.4rem; font-size:.75rem; line-height:1.45; color:#6b7280; flex:0 1 auto; max-width:100%; min-width:0; overflow:visible; white-space:normal; text-align:center; }
        .trust-item i { font-size:.8rem; line-height:1; flex-shrink:0; }
        .section-divider { display:flex; align-items:center; gap:.75rem; margin-bottom:1.5rem; }
        .section-divider span { font-size:.95rem; font-weight:700; white-space:nowrap; color:#111827; }
        .section-divider .line { flex:1; height:1px; }
        .contact-chips { display:flex; flex-wrap:wrap; justify-content:center; gap:.5rem; margin-bottom:1.25rem; }
        .contact-chip { display:inline-flex; align-items:center; gap:.5rem; padding:.4rem .85rem; border-radius:9999px; font-size:.8rem; font-weight:600; }
      </style>
    </head>
    <body style="margin:0;background:#f3f4f6;">
      <div style="position:relative;min-height:100vh;${bgStyle}">
        ${hasBgImage ? `<div style="position:absolute;inset:0;background:rgba(0,0,0,0.45);pointer-events:none;z-index:0;"></div>` : ''}
        <div style="position:relative;z-index:1;" class="min-h-screen py-10 px-4">
          <div class="w-full max-w-xl mx-auto">

            <!-- ── Header ── -->
            <div id="contactCardHeader" style="text-align:center;margin-bottom:1.75rem;">
              ${
                logoNorm
                  ? `<div style="display:flex;justify-content:center;margin-bottom:1rem;">
                       <img src="${logoAttr}" alt="" style="max-height:88px;max-width:200px;object-fit:contain;border-radius:.75rem;background:#fff;padding:.5rem .75rem;box-shadow:0 4px 20px rgba(0,0,0,0.18);" loading="lazy" decoding="async" />
                     </div>`
                  : `<div style="width:72px;height:72px;border-radius:50%;margin:0 auto 1rem;display:flex;align-items:center;justify-content:center;font-size:1.6rem;color:#fff;box-shadow:0 4px 20px rgba(0,0,0,0.22);background:${escapeHtmlAttr(primaryColor)};">
                       <i class="fas fa-comments"></i>
                     </div>`
              }
              <h1 style="margin:0 0 .35rem;font-size:1.55rem;font-weight:800;color:${escapeHtmlAttr(headerTextColor)};text-shadow:${hasBgImage ? '0 2px 8px rgba(0,0,0,0.4)' : 'none'};">${companyName}</h1>
              ${locationStr ? `<p style="margin:.3rem 0 0;font-size:.82rem;color:${escapeHtmlAttr(headerSubColor)};display:flex;align-items:center;justify-content:center;gap:.5rem;">
                <span style="height:1px;width:28px;background:${accentColor};display:inline-block;opacity:.7;"></span>
                ${escapeHtml(locationStr)}
                <span style="height:1px;width:28px;background:${accentColor};display:inline-block;opacity:.7;"></span>
              </p>` : ''}
              ${tenant.contact_hero_title != null ? `<p style="margin:.9rem 0 0;font-size:1.25rem;font-weight:700;color:${escapeHtmlAttr(headerTextColor)};text-shadow:${hasBgImage ? '0 2px 8px rgba(0,0,0,0.35)' : 'none'};">${escapeHtml(tenant.contact_hero_title)}</p>` : `<p style="margin:.9rem 0 0;font-size:1.25rem;font-weight:700;color:${escapeHtmlAttr(headerTextColor)};text-shadow:${hasBgImage ? '0 2px 8px rgba(0,0,0,0.35)' : 'none'};">أرسل بياناتك</p>`}
              ${tenant.contact_hero_subtitle != null ? `<p style="margin:.15rem 0 0;font-size:1.05rem;font-weight:600;color:${accentColor};text-shadow:${hasBgImage ? '0 2px 6px rgba(0,0,0,0.3)' : 'none'};">${escapeHtml(tenant.contact_hero_subtitle)}</p>` : `<p style="margin:.15rem 0 0;font-size:1.05rem;font-weight:600;color:${accentColor};text-shadow:${hasBgImage ? '0 2px 6px rgba(0,0,0,0.3)' : 'none'};">وسيتم التواصل معك</p>`}
              ${(phoneRaw || emailRaw) ? `
              <div class="contact-chips" style="margin-top:1rem;">
                ${waHref ? `<a href="${waHrefAttr}" target="_blank" rel="noopener noreferrer" class="contact-chip" style="background:#25D366;color:#fff;"><i class="fab fa-whatsapp"></i>${contactPhone}</a>` : ''}
                ${telHref ? `<a href="${telHrefAttr}" class="contact-chip" style="background:rgba(255,255,255,0.18);color:${escapeHtmlAttr(headerTextColor)};border:1px solid rgba(255,255,255,0.3);"><i class="fas fa-phone"></i>${contactPhone}</a>` : ''}
                ${emailRaw ? `<span class="contact-chip" style="background:rgba(255,255,255,0.18);color:${escapeHtmlAttr(headerTextColor)};border:1px solid rgba(255,255,255,0.3);">
                  <i class="fas fa-envelope"></i>${contactEmail}
                </span>` : ''}
              </div>` : ''}
            </div>

            <!-- ── Form card ── -->
            <div style="${formCardStyle}border-radius:1.25rem;box-shadow:0 24px 64px rgba(0,0,0,0.18),0 0 0 1px rgba(0,0,0,0.04);padding:2rem 1.75rem 2.25rem;overflow:visible;">
              <div class="section-divider">
                <div class="line" style="background:linear-gradient(to left,${accentColor},transparent);"></div>
                <span>بيانات التواصل</span>
                <div class="line" style="background:linear-gradient(to right,${accentColor},transparent);"></div>
              </div>

              <form id="contactForm" style="display:flex;flex-direction:column;gap:1.1rem;">
                <div>
                  <label class="block text-sm font-medium text-gray-700 mb-1.5">الاسم <span class="text-red-500">*</span></label>
                  <div class="field-icon-wrap">
                    <span class="fi"><i class="fas fa-user text-sm"></i></span>
                    <input id="customer_name" type="text" placeholder="اكتب اسمك الكامل" required />
                  </div>
                </div>
                <div>
                  <label class="block text-sm font-medium text-gray-700 mb-1.5">رقم الجوال <span class="text-red-500">*</span></label>
                  <div class="field-icon-wrap">
                    <span class="phone-prefix" dir="ltr">+966</span>
                    <input id="customer_phone" type="tel" required inputmode="numeric" maxlength="9" pattern="5[0-9]{8}" dir="ltr"
                           style="text-align:right;"
                           placeholder="5xxxxxxxx"
                           oninput="this.value = this.value.replace(/[^0-9٠-٩۰-۹]/g, '').slice(0, 9); this.setCustomValidity('');"
                           oninvalid="this.setCustomValidity('أدخل 9 أرقام تبدأ بـ 5')" />
                  </div>
                </div>
                ${customFieldsHtml}
                <div>
                  <label class="block text-sm font-medium text-gray-700 mb-1.5">رسالتك <span class="text-red-500">*</span></label>
                  <div class="field-icon-wrap" style="align-items:flex-start;">
                    <span class="fi" style="padding-top:.85rem;align-items:flex-start;"><i class="fas fa-comment-dots text-sm"></i></span>
                    <textarea id="customer_message" rows="4" placeholder="اكتب رسالتك هنا..." required style="padding-top:.75rem;"></textarea>
                  </div>
                </div>
                <button id="submitBtn" type="submit" class="submit-btn" style="${submitBtnStyle}margin-top:.25rem;">
                  <i class="fas fa-paper-plane"></i>احصل على استشارة مجانية
                </button>
                <p id="formStatus" class="text-sm" style="margin:0;text-align:center;"></p>
                ${formBadgesInner ? `<div class="trust-row" style="border-top:none;margin-top:.5rem;padding-top:.5rem;">${formBadgesInner}</div>` : ''}
              </form>

              <!-- Trust badges below divider line -->
              ${badgesInner ? `<div class="trust-row">${badgesInner}</div>` : ''}
            </div>

          </div>
        </div>
      </div>
      <script>
        const AFFILIATE_PATH = ${affiliatePathJson};
        const LOCATION_SLUG = ${locationSlugJson};
        const CUSTOM_FIELDS = ${customFieldsJson};
        const form = document.getElementById('contactForm');
        const statusEl = document.getElementById('formStatus');
        const submitBtn = document.getElementById('submitBtn');
        const filledFields = new Set();
        let formStarted = false;
        let formSubmitted = false;
        let abandonSent = false;

        function fieldKeyForEl(el) {
          if (!el || !el.id) return null;
          if (el.id === 'customer_name') return 'name';
          if (el.id === 'customer_phone') return 'phone';
          if (el.id === 'customer_message') return 'message';
          const m = String(el.id).match(/^custom_field_(\\d+)$/);
          if (!m) return null;
          const field = CUSTOM_FIELDS[Number(m[1])];
          return field && field.label ? ('cf:' + String(field.label).trim().slice(0, 76)) : null;
        }

        function syncFilledField(el) {
          const key = fieldKeyForEl(el);
          if (!key) return;
          const filled = el.type === 'checkbox'
            ? !!el.checked
            : String(el.value || '').trim().length > 0;
          if (filled) filledFields.add(key);
          else filledFields.delete(key);
        }

        function sendAbandonBeacon() {
          if (formSubmitted || abandonSent || !formStarted) return;
          abandonSent = true;
          const payload = { fields: Array.from(filledFields) };
          if (AFFILIATE_PATH) payload.affiliate_path = AFFILIATE_PATH;
          const body = JSON.stringify(payload);
          const url = '/api/public/${tenant.slug}/contact-form-abandons';
          try {
            if (navigator.sendBeacon) {
              navigator.sendBeacon(url, new Blob([body], { type: 'application/json' }));
              return;
            }
          } catch (_) {}
          fetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body,
            keepalive: true,
          }).catch(() => {});
        }

        form.addEventListener('input', () => {
          formStarted = true;
          const payload = {};
          if (AFFILIATE_PATH) payload.affiliate_path = AFFILIATE_PATH;
          fetch('/api/public/${tenant.slug}/contact-form-initiations', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload),
            keepalive: true,
          }).catch(() => {});
        }, { once: true });

        form.addEventListener('input', (e) => {
          formStarted = true;
          syncFilledField(e.target);
        });
        form.addEventListener('change', (e) => {
          formStarted = true;
          syncFilledField(e.target);
        });

        document.addEventListener('visibilitychange', () => {
          if (document.visibilityState === 'hidden') sendAbandonBeacon();
        });
        window.addEventListener('pagehide', sendAbandonBeacon);

        form.addEventListener('submit', async (e) => {
          e.preventDefault();
          statusEl.textContent = '';
          statusEl.className = 'text-sm';
          submitBtn.disabled = true;
          submitBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i>جاري الإرسال...';

          const payload = {
            customer_name: document.getElementById('customer_name').value.trim(),
            customer_phone: document.getElementById('customer_phone').value.trim(),
            customer_message: document.getElementById('customer_message').value.trim()
          };
          if (AFFILIATE_PATH) payload.affiliate_path = AFFILIATE_PATH;
          if (LOCATION_SLUG) payload.location_slug = LOCATION_SLUG;
          if (CUSTOM_FIELDS.length > 0) {
            payload.custom_fields = {};
            CUSTOM_FIELDS.forEach((f, i) => {
              const el = document.getElementById('custom_field_' + i);
              if (!el) return;
              if (f.type === 'checkbox') {
                payload.custom_fields[f.label] = el.checked ? 'نعم' : 'لا';
              } else {
                payload.custom_fields[f.label] = el.value.trim();
              }
            });
          }

          try {
            const res = await fetch('/api/public/${tenant.slug}/contact-submissions', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify(payload)
            });
            const data = await res.json().catch(() => ({}));
            if (!res.ok || !data.success) {
              throw new Error(data.error || 'تعذر إرسال الطلب');
            }

            formSubmitted = true;
            form.reset();
            form.setAttribute('aria-disabled', 'true');
            form.querySelectorAll('input, textarea, select, button').forEach((field) => {
              field.disabled = true;
            });
            form.querySelectorAll('.field-icon-wrap').forEach((el) => {
              el.style.opacity = '0.4';
              el.style.pointerEvents = 'none';
            });
            form.querySelectorAll('label').forEach((el) => {
              el.style.opacity = '0.4';
            });
            submitBtn.style.display = 'none';
            statusEl.style.cssText = 'margin:0;text-align:center;font-size:1rem;font-weight:700;padding:1rem 0 .25rem;';
            statusEl.textContent = data.message || 'تم الإرسال بنجاح';
            statusEl.className = 'text-green-700';
          } catch (err) {
            statusEl.textContent = err?.message || 'حدث خطأ أثناء الإرسال';
            statusEl.className = 'text-sm text-red-700';
            submitBtn.disabled = false;
            submitBtn.innerHTML = '<i class="fas fa-paper-plane"></i>احصل على استشارة مجانية';
          }
        });
      </script>
    </body>
    </html>
  `
}

/** Schema has no ON DELETE CASCADE from banks; clear dependents so DELETE FROM banks succeeds. */
async function deleteBankAndDependents(db: D1Database, bankId: string | number) {
  await db.batch([
    db.prepare('DELETE FROM bank_financing_rates WHERE bank_id = ?').bind(bankId),
    db.prepare('UPDATE customers SET best_bank_id = NULL WHERE best_bank_id = ?').bind(bankId),
    db.prepare('UPDATE financing_requests SET selected_bank_id = NULL WHERE selected_bank_id = ?').bind(bankId),
    db.prepare('DELETE FROM calculations WHERE bank_id = ?').bind(bankId),
    db.prepare('DELETE FROM banks WHERE id = ?').bind(bankId),
  ])
}

/** Same as deleteBankAndDependents for all banks with tenant_id IS NULL (super-admin bulk delete). */
async function deleteGlobalBanksAndDependents(db: D1Database) {
  return db.batch([
    db.prepare(
      'DELETE FROM bank_financing_rates WHERE bank_id IN (SELECT id FROM banks WHERE tenant_id IS NULL)'
    ),
    db.prepare(
      'UPDATE customers SET best_bank_id = NULL WHERE best_bank_id IN (SELECT id FROM banks WHERE tenant_id IS NULL)'
    ),
    db.prepare(
      'UPDATE financing_requests SET selected_bank_id = NULL WHERE selected_bank_id IN (SELECT id FROM banks WHERE tenant_id IS NULL)'
    ),
    db.prepare(
      'DELETE FROM calculations WHERE bank_id IN (SELECT id FROM banks WHERE tenant_id IS NULL)'
    ),
    db.prepare('DELETE FROM banks WHERE tenant_id IS NULL'),
  ])
}

/** When users with roles supervisor (3), employee (4), or bank_agent (5) are created, mirror them into hr_employees for /admin/hr flows. */
async function syncNewUserToHrEmployees(
  db: D1Database,
  opts: {
    tenantId: number
    userId: number
    roleId: number
    fullName: string
    username: string
    email: string | null
    phone: string | null
    /** Shown as «القسم» on HR employees list (hr_employees.department). */
    department: string | null
  }
): Promise<boolean> {
  // employee_code is globally UNIQUE — keep the USR{globalId} scheme as the
  // technical key. employee_number is the human-facing serial and gets the
  // tenant-local number so it stays consistent with every other view.
  const code = `USR${opts.userId}`
  const already = await db
    .prepare('SELECT id FROM hr_employees WHERE employee_code = ? LIMIT 1')
    .bind(code)
    .first()
  if (already) return false

  const linkedUser = await db
    .prepare('SELECT tenant_user_number FROM users WHERE id = ?')
    .bind(opts.userId)
    .first() as { tenant_user_number: number | null } | null
  const employeeNumber =
    linkedUser?.tenant_user_number != null ? String(linkedUser.tenant_user_number) : code

  let jobTitle = 'موظف'
  if (opts.roleId === 3) jobTitle = 'مشرف المبيعات'
  else if (opts.roleId === 5) jobTitle = 'موظف التمويل'

  const displayName = opts.fullName.trim() || opts.username.trim() || code
  const hireDate = new Date().toISOString().slice(0, 10)

  await db
    .prepare(`
      INSERT INTO hr_employees (
        tenant_id, employee_code, employee_number,
        full_name, full_name_ar,
        email, phone, department, job_title, hire_date,
        employment_type, work_schedule, status,
        basic_salary, housing_allowance, transportation_allowance,
        notes
      ) VALUES (
        ?, ?, ?, ?, ?, ?, ?, ?, ?, ?,
        'full_time', 'regular', 'active',
        0, 0, 0,
        ?
      )
    `)
    .bind(
      opts.tenantId,
      code,
      employeeNumber,
      displayName,
      displayName,
      opts.email,
      opts.phone,
      opts.department,
      jobTitle,
      hireDate,
      `linked_user:${opts.userId}`
    )
    .run()
  return true
}

/** TEMP: backfill hr_employees for existing users (roles 3–5). Remove with sync API + UI when done. */
async function bulkSyncUsersToHrEmployees(
  db: D1Database,
  tenantFilter: number | null
): Promise<{
  synced: number
  skipped: number
  errors: { userId: number; message: string }[]
}> {
  // Bank agents (role 5) are external to the tenant's HR. Previously they were
  // excluded indirectly because their users.tenant_id was NULL; after migration
  // 0079 backfilled that column, the intent is now explicit.
  let query = `
    SELECT id, tenant_id, role_id, full_name, username, email, phone, hr_section
    FROM users
    WHERE role_id IN (3, 4, 6, 13, 14) AND tenant_id IS NOT NULL
  `
  const bindVals: number[] = []
  if (tenantFilter != null && typeof tenantFilter === 'number' && !Number.isNaN(tenantFilter)) {
    query += ` AND tenant_id = ?`
    bindVals.push(tenantFilter)
  }
  const stmt = bindVals.length ? db.prepare(query).bind(...bindVals) : db.prepare(query)
  const { results } = await stmt.all()
  let synced = 0
  let skipped = 0
  const errors: { userId: number; message: string }[] = []
  for (const u of results || []) {
    const userId = Number((u as { id: unknown }).id)
    const tid = Number((u as { tenant_id: unknown }).tenant_id)
    let roleId = Number((u as { role_id: unknown }).role_id)
    if (roleId === 13) roleId = 3
    else if (roleId === 14) roleId = 4
    if (!userId || Number.isNaN(userId) || !tid || Number.isNaN(tid)) continue
    const emailRaw = (u as { email: unknown }).email
    const phoneRaw = (u as { phone: unknown }).phone
    const emailStr =
      emailRaw != null && String(emailRaw).trim() !== '' ? String(emailRaw).trim() : null
    const phoneStr =
      phoneRaw != null && String(phoneRaw).trim() !== '' ? String(phoneRaw).trim() : null
    const fullStr =
      (u as { full_name: unknown }).full_name != null
        ? String((u as { full_name: unknown }).full_name).trim()
        : ''
    const secRaw = (u as { hr_section?: unknown }).hr_section
    const deptStr =
      secRaw != null && String(secRaw).trim() !== '' ? String(secRaw).trim() : null
    try {
      const created = await syncNewUserToHrEmployees(db, {
        tenantId: tid,
        userId,
        roleId,
        fullName: fullStr,
        username: String((u as { username: unknown }).username ?? ''),
        email: emailStr,
        phone: phoneStr,
        department: deptStr,
      })
      if (created) synced++
      else skipped++
    } catch (e: unknown) {
      errors.push({ userId, message: String((e as Error)?.message ?? e) })
    }
  }
  return { synced, skipped, errors }
}

/**
 * Legacy fallback: replace `<link href="/tailwind.css">` with an inline `<style>`.
 * Disabled by default — prefer the cacheable `/tailwind.css` asset. Enable with INLINE_TAILWIND=1.
 */
async function maybeInlineTailwindIntoHtmlResponse(c: { res?: Response; env?: Bindings }): Promise<void> {
  if (!inlineTailwindEnabled(c.env as any)) return
  const res = c.res
  if (!res?.body) return
  const ct = res.headers.get('content-type') || ''
  if (!ct.includes('text/html')) return
  if (res.status < 200 || res.status >= 300) return
  try {
    const cloned = res.clone()
    let html = await cloned.text()
    if (html.includes('id="tailwind-inline-budget"')) return
    const linkRe = /<link[^>]+href=["']\/tailwind\.css(?:\?[^"']*)?["'][^>]*\s*\/?>/gi
    if (!linkRe.test(html)) return
    linkRe.lastIndex = 0
    html = html.replace(linkRe, '')
    const block = `<style id="tailwind-inline-budget">\n${tailwindCss}\n</style>`
    const hc = '</head>'
    const hi = html.lastIndexOf(hc)
    if (hi !== -1) html = html.slice(0, hi) + block + html.slice(hi)
    else html = block + html
    const headers = new Headers(res.headers)
    headers.set('content-type', 'text/html; charset=UTF-8')
    c.res = new Response(html, { status: res.status, statusText: res.statusText, headers })
  } catch {
    // keep original response
  }
}

const app = new Hono<{ Bindings: Bindings; Variables: Variables }>()

// Outermost wrapper: optional Tailwind inlining (off by default for performance).
app.use('*', async (c, next) => {
  const t0 = Date.now()
  await next()
  await maybeInlineTailwindIntoHtmlResponse(c)
  if ((c.env?.PERF_DEBUG === '1' || c.env?.PERF_DEBUG === 'true') && c.req.path.startsWith('/admin/')) {
    perfLog(c.env as any, `request ${c.req.method} ${c.req.path}`, Date.now() - t0, {
      status: c.res?.status,
    })
  }
})

// When `_routes.json` omits `/tailwind.css`, Pages sends this URL to the Worker and static
// files are not used — admin/settings/login pages would load unstyled. Serving the same
// file from the bundle fixes that; when routing excludes `/tailwind.css`, the static asset
// is still served first at the edge.
app.get('/tailwind.css', (c) =>
  c.newResponse(tailwindCss, 200, {
    'Content-Type': 'text/css; charset=utf-8',
    'Cache-Control': 'public, max-age=86400, stale-while-revalidate=604800',
  })
)

// Contracts module static assets (JS; CSS is inlined in HTML). Register early so routes are matched.
registerContractsStaticRoutes(app, getUserInfo)

