// Role 5 (bank agent) previously had a separate API whitelist here.
// It now uses the same access as role 4 (employee) — handler-level checks enforce scoping.
app.use('/api/*', async (c, next) => {
  await next()
  return
  const method = c.req.method
  if (p === '/api/financing-requests' && method === 'GET') {
    await next()
    return
  }
  if (
    p.startsWith('/api/financing-requests/') &&
    (method === 'PUT' || method === 'DELETE')
  ) {
    await next()
    return
  }
  if (p === '/api/attachments/upload' && method === 'POST') {
    await next()
    return
  }
  if (p === '/api/customers' && method === 'GET') {
    await next()
    return
  }
  if (p === '/api/customers' && method === 'POST') {
    await next()
    return
  }
  // Update existing customer (edit form); handler enforces canUserAccessCustomer (incl. role 5 via assigned request).
  if (method === 'POST' && /^\/api\/customers\/\d+$/.test(p)) {
    await next()
    return
  }
  if (p === '/api/requests' && method === 'POST') {
    await next()
    return
  }
  if (p === '/api/customers/import-csv' && method === 'POST') {
    await next()
    return
  }
  if (p === '/api/requests/import-csv' && method === 'POST') {
    await next()
    return
  }
  if (
    (p === '/api/rates/import-csv' || p === '/api/rates/upload-excel') &&
    method === 'POST'
  ) {
    await next()
    return
  }
  if (p === '/api/customer-reviews' && method === 'POST') {
    await next()
    return
  }
  if (p.startsWith('/api/customer-reviews/') && method === 'DELETE') {
    await next()
    return
  }
  if (p === '/api/customer-reviews' && method === 'GET') {
    await next()
    return
  }
  if (p.startsWith('/api/customer-reviews/') && method === 'GET') {
    await next()
    return
  }
  if (p === '/api/customer-alarms' && (method === 'GET' || method === 'POST')) {
    await next()
    return
  }
  if (p.startsWith('/api/customer-alarms/') && (method === 'GET' || method === 'PUT' || method === 'DELETE')) {
    await next()
    return
  }
  if (method === 'PUT' && /^\/api\/requests\/\d+\/complete$/.test(p)) {
    await next()
    return
  }
  if (p === '/api/reports/requests-followup' && method === 'GET') {
    await next()
    return
  }
  if (p === '/api/follow-ups' && method === 'GET') {
    await next()
    return
  }
  if (p.startsWith('/api/follow-ups/') && (method === 'GET' || method === 'POST' || method === 'PATCH')) {
    await next()
    return
  }
  if (p === '/api/my-followup-tasks' && (method === 'GET' || method === 'PATCH')) {
    await next()
    return
  }
  if (p.startsWith('/api/my-followup-tasks/') && (method === 'GET' || method === 'PATCH' || method === 'POST')) {
    await next()
    return
  }
  if (p === '/api/my-tenant-followup-staff' && method === 'GET') {
    await next()
    return
  }
  if (p === '/api/my-followup-task-passes/incoming' && method === 'GET') {
    await next()
    return
  }
  if (p.startsWith('/api/my-followup-task-passes/') && method === 'PATCH') {
    await next()
    return
  }
  if (p === '/api/requests/sample-csv' && method === 'GET') {
    await next()
    return
  }
  if (p === '/api/sidebar-filter-counts' && method === 'GET') {
    await next()
    return
  }
  // Own leave history/submit (scoped in handler by user → hr_employees email)
  if (p === '/api/my-leaves' && (method === 'GET' || method === 'POST')) {
    await next()
    return
  }
  // Own tickets history/submit (scoped in handler by user → hr_employees email)
  if (p === '/api/my-tickets' && (method === 'GET' || method === 'POST')) {
    await next()
    return
  }
  // Own employee profile (scoped in handler by user → hr_employees email)
  if (p === '/api/my-profile' && (method === 'GET' || method === 'PATCH')) {
    await next()
    return
  }
  if (method === 'GET' && (
    p === '/api/banks' ||
    p === '/api/rates' ||
    p === '/api/financing-types' ||
    p === '/api/tenants' ||
    p === '/api/admin/bank-agents' ||
    p === '/api/admin/filter-employees'
  )) {
    await next()
    return
  }
  if (method === 'POST' && (
    p === '/api/calculator/save-customer' ||
    p === '/api/calculator/submit-request' ||
    p === '/api/workflow/update-stage' ||
    p === '/api/workflow/add-action' ||
    p === '/api/workflow/add-note' ||
    p === '/api/workflow/create-task' ||
    p === '/api/workflow/customer-update-stage' ||
    p === '/api/workflow/customer-add-action' ||
    p === '/api/workflow/customer-add-note' ||
    p === '/api/workflow/customer-create-task'
  )) {
    await next()
    return
  }
  if (p === '/api/tenant-contact-affiliates' && method === 'GET') {
    await next()
    return
  }
  // Contracts module: `/api/contract-tables/*` + logo upload. Missing here caused 403 for role 5 on every contracts API call.
  if (p.startsWith('/api/contract-tables/')) {
    await next()
    return
  }
  if (p === '/api/contracts/party-logo-upload' && method === 'POST') {
    await next()
    return
  }
  if (p === '/api/contracts/template-stamp-upload' && method === 'POST') {
    await next()
    return
  }
  // Document background watermark (read-only) for contract preview/print.
  if (p === '/api/tenant/document-watermark' && method === 'GET') {
    await next()
    return
  }
  // Contract documents reference party logos stored in R2 at this URL.
  if (method === 'GET' && p.startsWith('/api/attachments/view/')) {
    await next()
    return
  }
  // Company chat: tenant-scoped 1:1 chat. Per-conversation participant gate
  // is enforced inside the handlers (ensureConversationAccess), so allow
  // role 5 through this coarse outer middleware.
  if (p.startsWith('/api/chat/')) {
    await next()
    return
  }
  // Notification center: role 5 needs to read and mark notifications
  if (p === '/api/notifications' && method === 'GET') {
    await next()
    return
  }
  if (p === '/api/notifications/unread-count' && method === 'GET') {
    await next()
    return
  }
  if (p === '/api/notifications/read-all' && method === 'PUT') {
    await next()
    return
  }
  if (/^\/api\/notifications\/\d+\/read$/.test(p) && method === 'PUT') {
    await next()
    return
  }
  return c.json({ success: false, error: 'غير مصرح' }, 403)
})

