// MULTI-TENANT MIDDLEWARE & HELPERS
// ===================================

// Helper: Get tenant from subdomain or slug
async function getTenant(c: any): Promise<any> {
  // Safety check for DB binding
  if (!c.env?.DB) {
    console.error('❌ getTenant: DB binding not available')
    return null
  }
  
  // Try to get from subdomain first (e.g., tamweel1.tamweel.app)
  const host = (c.req.header('host') || '').split(':')[0]
  const subdomain = host.split('.')[0]
  
  // Try to get from URL path (e.g., /c/tamweel-1/calculator)
  const pathMatch = c.req.path.match(/^\/c\/([^\/]+)/)
  const slug = pathMatch ? pathMatch[1] : null
  
  // Search in database
  let tenant = null
  
  if (subdomain && subdomain !== 'localhost' && subdomain !== '3000-ii8t2q2dzwwe7ckmslxss-3844e1b6') {
    tenant = await c.env.DB.prepare(`
      SELECT * FROM tenants 
      WHERE subdomain = ? AND status = 'active'
      LIMIT 1
    `).bind(subdomain).first()
  }
  
  if (!tenant && slug) {
    tenant = await c.env.DB.prepare(`
      SELECT * FROM tenants 
      WHERE slug = ? AND status = 'active'
      LIMIT 1
    `).bind(slug).first()
  }
  
  // Fallback: use tenant_id = 1 (default company) if no tenant found
  if (!tenant) {
    tenant = await c.env.DB.prepare(`
      SELECT * FROM tenants WHERE id = 1 LIMIT 1
    `).bind().first()
  }
  
  return tenant
}

function normalizeAuthToken(rawToken: string): string | null {
  const trimmed = rawToken.trim()
  if (!trimmed) {
    return null
  }

  let decodedToken = trimmed
  try {
    decodedToken = decodeURIComponent(trimmed)
  } catch {
    // If the token isn't URI-encoded, use it as-is.
  }

  const base64 = decodedToken.replace(/-/g, '+').replace(/_/g, '/')
  const remainder = base64.length % 4
  if (remainder === 1) {
    return null
  }

  const padding = remainder === 0 ? '' : '='.repeat(4 - remainder)
  return base64 + padding
}

function parseOptionalInt(value?: string): number | null {
  if (!value || value === 'null' || value === 'undefined') {
    return null
  }
  const parsed = Number.parseInt(value, 10)
  return Number.isNaN(parsed) ? null : parsed
}

function parseLoginTimestampToMs(value?: string | null): number | null {
  if (!value) {
    return null
  }
  // SQLite timestamps are commonly stored as "YYYY-MM-DD HH:MM:SS[.SSS]".
  // Normalize to ISO-8601 UTC to compare against token issue time.
  const normalized = value.includes('T') ? value : value.replace(' ', 'T')
  const withTimezone = /Z$|[+-]\d\d:\d\d$/.test(normalized) ? normalized : `${normalized}Z`
  const ms = Date.parse(withTimezone)
  return Number.isNaN(ms) ? null : ms
}

const DEFAULT_OBLIGATION_TYPE_NAMES = [
  'قرض شخصي',
  'قرض عقاري',
  'تمويل سيارة قائم',
  'بطاقة ائتمان',
  'تمويل تعاوني',
  'تقسيط / شراء بالأقساط',
  'سلفة راتب',
  'التزامات أخرى',
] as const

async function fetchObligationTypeNamesForTenant(
  db: Bindings['DB'],
  tenantId: number | null
): Promise<string[]> {
  try {
    let rows: { type_name?: string }[]
    if (tenantId != null) {
      const r = await db
        .prepare(
          'SELECT type_name FROM obligation_types WHERE is_active = 1 AND (tenant_id IS NULL OR tenant_id = ?) ORDER BY sort_order ASC, type_name ASC'
        )
        .bind(tenantId)
        .all()
      rows = (r.results || []) as { type_name?: string }[]
    } else {
      const r = await db
        .prepare(
          'SELECT type_name FROM obligation_types WHERE is_active = 1 AND tenant_id IS NULL ORDER BY sort_order ASC, type_name ASC'
        )
        .all()
      rows = (r.results || []) as { type_name?: string }[]
    }
    const names = rows.map((row) => row.type_name).filter((n): n is string => typeof n === 'string' && n.length > 0)
    return names.length > 0 ? names : [...DEFAULT_OBLIGATION_TYPE_NAMES]
  } catch {
    return [...DEFAULT_OBLIGATION_TYPE_NAMES]
  }
}

/** Customer summary page (/admin/dashboard) — super admin and company admin only. */
function canAccessCustomerSummaryDashboard(roleId: unknown): boolean {
  const rid = normalizeRoleId(roleId)
  return rid === 1 || rid === 2
}

function getAdminAccessDeniedRedirect(roleId: unknown): string {
  return canAccessCustomerSummaryDashboard(roleId) ? '/admin/dashboard' : '/admin/panel'
}

function jsonForInlineScript(value: unknown): string {
  return JSON.stringify(value).replace(/</g, '\\u003c')
}

function getRoleDisplayName(roleId: unknown, roleName: string | null | undefined): string {
  const normalizedRoleId = normalizeRoleId(roleId)
  const raw = (roleName || '').trim()
  const rn = raw.toLowerCase()

  if (normalizedRoleId === 1) return 'مدير النظام'
  // Prefer DB label (e.g. حساب شركة) for company accounts
  if (normalizedRoleId === 2) return raw || 'حساب شركة'
  // Numeric 3 = sales supervisor (even if an old migration relabeled the roles row as "employee"/موظف)
  if (normalizedRoleId === 3) return 'مشرف المبيعات'
  if (normalizedRoleId === 4) return 'موظف'
  if (normalizedRoleId === 5) return 'موظف التمويل'
  if (normalizedRoleId === 6) return 'موظف مزدوج'

  // Legacy English keys from older seeds / custom role rows (when role_id is missing or non-standard)
  if (rn === 'supervisor') return 'مشرف المبيعات'
  if (rn === 'employee') return 'موظف'
  if (rn === 'dual_agent') return 'موظف مزدوج'
  if (rn === 'company_admin') return 'حساب شركة'
  if (rn === 'super_admin') return 'مدير النظام'
  if (raw === 'موظف') return 'موظف'
  if (raw === 'مشرف' || raw.includes('مشرف')) return 'مشرف المبيعات'

  return raw || 'غير محدد'
}

/** توزيع العملاء: مدير النظام (1) أو حساب شركة (2) فقط — لا يشمل مشرف المبيعات (3) أو الموظف (4) */
function canManageCustomerAssignments(roleId: number | null): boolean {
  return roleId === 1 || roleId === 2
}

function cacheUserInfo(c: any, info: UserInfo): UserInfo {
  try {
    if (typeof c?.set === 'function') c.set('userInfo', info)
  } catch {
    /* context may be unavailable outside request handlers */
  }
  return info
}

// Get tenant_id for current user (for multi-tenancy filtering)
async function getUserInfo(c: any): Promise<UserInfo> {
  try {
    try {
      const cached = typeof c?.get === 'function' ? (c.get('userInfo') as UserInfo | undefined) : undefined
      if (cached) return cached
    } catch {
      /* ignore */
    }

    const dbg = authDebugEnabled(c.env)
    const log = (...args: unknown[]) => { if (dbg) console.log(...args) }

    log('🔍 [getUserInfo] Starting user info retrieval...')
    // Try to get token from Authorization Header (for API calls)
    let token = c.req.header('Authorization')?.replace('Bearer ', '')
    log('🔍 [getUserInfo] Token from header:', token ? 'Found' : 'Not found')
    
    // If not in header, try to get from cookie (for HTML pages)
    if (!token) {
      const cookieHeader = c.req.header('Cookie')
      log('🔍 [getUserInfo] Cookie header:', cookieHeader ? 'Present' : 'Missing')
      if (cookieHeader) {
        const cookies = cookieHeader.split(';').map((cookie: string) => cookie.trim())
        const authCookie = cookies.find((cookie: string) => cookie.startsWith('authToken='))
        if (authCookie) {
          // Do not use split('=')[1] — base64 tokens often contain '=' padding; that truncates the value.
          token = authCookie.startsWith('authToken=')
            ? authCookie.slice('authToken='.length)
            : ''
          log('✅ [getUserInfo] Token found in cookie')
        } else {
          log('❌ [getUserInfo] No authToken cookie found')
        }
      }
    }
    
    if (!token) {
      log('❌ [getUserInfo] No token found in header or cookie')
      const queryTenantId = c.req.query('tenant_id')
      return cacheUserInfo(c, {
        userId: null,
        tenantId: queryTenantId ? parseInt(queryTenantId) : null,
        roleId: null,
        tokenRoleId: null,
        assignedBankId: null
      })
    }

    const normalizedToken = normalizeAuthToken(token)
    if (!normalizedToken) {
      return cacheUserInfo(c, EMPTY_USER_INFO)
    }

    const decoded = atob(normalizedToken)
    const parts = decoded.split(':')
    const userId = parseOptionalInt(parts[0])
    if (!userId) {
      return cacheUserInfo(c, EMPTY_USER_INFO)
    }

    const tenantIdFromToken = parseOptionalInt(parts[1])
    const tokenRoleId = normalizeRoleId(parseOptionalInt(parts[2]))
    const tokenIssuedAtMs = parseOptionalInt(parts[3])
    if (!tokenIssuedAtMs) {
      return cacheUserInfo(c, EMPTY_USER_INFO)
    }
    log('🔍 [getUserInfo] Parsed:', { userId, tenantIdFromToken, tokenRoleId, tokenIssuedAtMs })
    
    // Safety check for DB binding
    if (!c.env?.DB) {
      console.error('❌ [getUserInfo] DB binding not available')
      return cacheUserInfo(c, { ...EMPTY_USER_INFO, tokenRoleId: tokenRoleId ?? null })
    }
    
    const user = await c.env.DB.prepare(`
      SELECT id, tenant_id, role_id, last_login, assigned_bank_id FROM users WHERE id = ?
    `).bind(userId).first()
    
    if (!user) {
      return cacheUserInfo(c, { ...EMPTY_USER_INFO, tokenRoleId })
    }

    const userLastLoginMs = parseLoginTimestampToMs((user as { last_login?: string | null }).last_login ?? null)
    if (userLastLoginMs && tokenIssuedAtMs < userLastLoginMs) {
      log('❌ [getUserInfo] Token invalidated by a newer login', {
        tokenIssuedAtMs,
        userLastLoginMs
      })
      return cacheUserInfo(c, EMPTY_USER_INFO)
    }
    
    // Super Admin (role_id = 1) can see all data
    const normalizedRoleId = normalizeRoleId(user.role_id)
    const assignedBankFromRow = (user as { assigned_bank_id?: number | null }).assigned_bank_id
    const assignedBankId =
      assignedBankFromRow != null && !Number.isNaN(Number(assignedBankFromRow))
        ? Number(assignedBankFromRow)
        : null

    if (normalizedRoleId === 1) {
      const queryTenantId = c.req.query('tenant_id')
      return cacheUserInfo(c, {
        userId: user.id,
        tenantId: queryTenantId ? parseInt(queryTenantId) : null,
        roleId: 1,
        tokenRoleId,
        assignedBankId: null
      })
    }
    
    // For other roles: DB is source of truth for which company (tenant) this user belongs to.
    // Stale JWT tenant segments must not override users.tenant_id (fixes customer/contract scoping).
    const dbTenantId = (user as { tenant_id?: number | null }).tenant_id
    let tenantIdResolved: number | null = dbTenantId != null ? dbTenantId : tenantIdFromToken

    // Bank-agent capable roles (5/6) may be scoped by assigned_bank_id; banks belong to exactly one tenant.
    // Without this, tenantId stays NULL when users.tenant_id was never filled and the JWT segment is null,
    // and every tenant-filtered API (including the whole contracts module) returns zero rows — not just "empty list".
    if (
      tenantIdResolved == null &&
      (normalizedRoleId === 5 || normalizedRoleId === 6) &&
      assignedBankId != null &&
      c.env?.DB
    ) {
      try {
        const bankRow = await c.env.DB.prepare('SELECT tenant_id FROM banks WHERE id = ? LIMIT 1')
          .bind(assignedBankId)
          .first<{ tenant_id: number | null }>()
        if (bankRow?.tenant_id != null && !Number.isNaN(Number(bankRow.tenant_id))) {
          tenantIdResolved = Number(bankRow.tenant_id)
        }
      } catch (_) {
        /* ignore */
      }
    }

    return cacheUserInfo(c, {
      userId: user.id,
      tenantId: tenantIdResolved,
      roleId: normalizedRoleId,
      tokenRoleId,
      assignedBankId: normalizedRoleId === 5 || normalizedRoleId === 6 ? assignedBankId : null
    })
  } catch (error: any) {
    if (authDebugEnabled(c?.env)) {
      console.error('❌ [getUserInfo] ERROR:', error?.message || error)
    }
    return cacheUserInfo(c, EMPTY_USER_INFO)
  }
}

/** Bind params for BANK_AGENT_DROPDOWN_SQL / isActiveBankAgentForTenant (4× tenant id). */
function bankAgentTenantBinds(tenantId: number): [number, number, number, number] {
  const tid = Number(tenantId)
  return [tid, tid, tid, tid]
}

/** Bind params for EMPLOYEE_FILTER_DROPDOWN_SQL (3× tenant id). */
function employeeFilterTenantBinds(tenantId: number): [number, number, number] {
  const tid = Number(tenantId)
  return [tid, tid, tid]
}

/** Staff eligible for contact/follow-up task assignment (normalized roles 4/5/6 + bank-scoped agents). */
const FOLLOWUP_STAFF_SQL = `
  SELECT u.id, u.full_name, u.role_id, u.assigned_location_id
  FROM users u
  WHERE u.is_active = 1
    AND (
      (u.role_id IN (4, 6, 14) AND u.tenant_id = ?)
      OR (
        u.role_id IN (5, 15, 6)
        AND (
          u.tenant_id = ?
          OR EXISTS (
            SELECT 1 FROM banks b
            WHERE b.id = u.assigned_bank_id AND b.tenant_id = ?
          )
        )
      )
    )
  ORDER BY COALESCE(NULLIF(TRIM(u.full_name), ''), u.username) ASC
`

function followupStaffTenantBinds(tenantId: number): [number, number, number] {
  const tid = Number(tenantId)
  return [tid, tid, tid]
}

function isFollowupAssignableRole(roleId: unknown): boolean {
  const r = normalizeRoleId(roleId)
  return r === 4 || r === 5 || r === 6
}

async function listFollowupAssignableStaff(
  db: D1Database,
  tenantId: number
): Promise<{ id: number; full_name: string; role_id: number; assigned_location_id?: number | null }[]> {
  const { results } = await db
    .prepare(FOLLOWUP_STAFF_SQL)
    .bind(...followupStaffTenantBinds(tenantId))
    .all<{ id: number; full_name: string; role_id: number; assigned_location_id?: number | null }>()
  const seen = new Set<number>()
  const out: { id: number; full_name: string; role_id: number; assigned_location_id?: number | null }[] = []
  for (const row of (results || []) as { id: number; full_name: string; role_id: number; assigned_location_id?: number | null }[]) {
    if (seen.has(row.id)) continue
    const normalized = normalizeRoleId(row.role_id)
    if (!isFollowupAssignableRole(normalized)) continue
    seen.add(row.id)
    out.push({ id: row.id, full_name: row.full_name, role_id: normalized as number, assigned_location_id: row.assigned_location_id ?? null })
  }
  return out
}

/** Open follow-up tasks used for custom-roster assignment limits. */
const FOLLOWUP_OPEN_TASK_COUNT_SQL = `
  SELECT COUNT(*)
  FROM company_contact_followup_tasks t
  WHERE t.assigned_user_id = a.user_id
    AND t.tenant_id = ?
    AND (
      t.status IS NULL
      OR TRIM(t.status) = ''
      OR LOWER(TRIM(t.status)) NOT IN ('completed', 'cancelled')
    )
`

/** Auto-assign employee column on new customer (role 4 / dual agent 6). */
async function assignNewCustomerToEmployee(
  db: D1Database,
  customerId: number,
  employeeId: number,
  assignedBy: number,
  notes = ''
): Promise<void> {
  try {
    await db
      .prepare(
        `INSERT INTO customer_assignments (customer_id, employee_id, assigned_by, notes)
         VALUES (?, ?, ?, ?)
         ON CONFLICT(customer_id) DO UPDATE SET
           employee_id = excluded.employee_id,
           assigned_by = excluded.assigned_by,
           notes = excluded.notes`
      )
      .bind(customerId, employeeId, assignedBy, notes)
      .run()
  } catch (e: unknown) {
    const msg = String((e as { message?: string })?.message || e || '')
    if (!/ON CONFLICT|no such column/i.test(msg)) throw e
    await db
      .prepare(
        `INSERT OR REPLACE INTO customer_assignments (customer_id, employee_id, assigned_by, notes)
         VALUES (?, ?, ?, ?)`
      )
      .bind(customerId, employeeId, assignedBy, notes)
      .run()
  }
  try {
    await db
      .prepare(
        `INSERT INTO assignment_history (customer_id, old_employee_id, new_employee_id, changed_by, notes)
         VALUES (?, NULL, ?, ?, ?)`
      )
      .bind(customerId, employeeId, assignedBy, notes)
      .run()
  } catch (_) {
    /* history table may be missing in legacy DBs */
  }
}

/** Same tenant scope as GET /api/users for bank-agent capable assignees (roles 5/6). */
async function isActiveBankAgentForTenant(
  db: D1Database,
  agentUserId: number,
  tenantId: number | null
): Promise<boolean> {
  if (tenantId == null || Number.isNaN(Number(tenantId))) return false
  const [tid, tid2, tid3, tid4] = bankAgentTenantBinds(Number(tenantId))
  const row = await db
    .prepare(
      `SELECT 1 AS ok FROM users u
       WHERE u.id = ? AND u.is_active = 1
         AND (
           (u.role_id IN (5, 15) AND (
             u.tenant_id = ?
             OR EXISTS (
               SELECT 1 FROM banks b
               WHERE b.id = u.assigned_bank_id AND b.tenant_id = ?
             )
           ))
           OR (u.role_id = 6 AND (
             u.tenant_id = ?
             OR EXISTS (
               SELECT 1 FROM banks b
               WHERE b.id = u.assigned_bank_id AND b.tenant_id = ?
             )
           ))
         )
       LIMIT 1`
    )
    .bind(agentUserId, tid, tid2, tid3, tid4)
    .first()
  return Boolean(row)
}

