async function getUserTenantId(c: any): Promise<number | null> {
  const info = await getUserInfo(c)
  return info.tenantId
}

/**
 * Same customer scope as `/admin/requests/new` (role + tenant).
 * Used server-side so lists match without a separate API round-trip.
 *
 * `scopeSuperAdminToTenant`: when true (contracts new form), super-admins are limited to
 * `?tenant_id=` or `users.tenant_id` so the dropdown never lists every company at once.
 */
async function loadCustomersForAdminForms(
  c: any,
  userInfo: { userId: number | null; tenantId: number | null; roleId: number | null },
  opts?: { scopeSuperAdminToTenant?: boolean; filterRole4ByFundingRequests?: boolean }
): Promise<{ results: any[] }> {
  let customersQuery = 'SELECT id, full_name, phone, national_id, city, tenant_id, COALESCE(is_completed, 0) as is_completed FROM customers'
  const customersParams: any[] = []

  if (userInfo.roleId === 1) {
    if (opts?.scopeSuperAdminToTenant) {
      let tid: number | null = null
      const q = c.req.query('tenant_id')
      if (q != null && /^\d+$/.test(String(q))) {
        tid = parseInt(String(q), 10)
      }
      if (tid == null && userInfo.userId) {
        const row = (await c.env.DB.prepare('SELECT tenant_id FROM users WHERE id = ?').bind(userInfo.userId).first()) as {
          tenant_id: number | null
        } | null
        if (row?.tenant_id != null) tid = row.tenant_id
      }
      if (tid == null) {
        return { results: [] }
      }
      customersQuery += ' WHERE tenant_id = ?'
      customersParams.push(tid)
    }
    // else: legacy — SaaS super-admin sees all customers (e.g. financing request form)
  } else if (userInfo.roleId === 2 || userInfo.roleId === 3) {
    if (!userInfo.tenantId) {
      return { results: [] }
    }
    customersQuery += ' WHERE tenant_id = ?'
    customersParams.push(userInfo.tenantId)
  } else if (userInfo.roleId === 4) {
    if (!userInfo.tenantId || !userInfo.userId) {
      return { results: [] }
    }
    if (opts?.filterRole4ByFundingRequests) {
      customersQuery += ` WHERE tenant_id = ? AND EXISTS (
        SELECT 1 FROM customer_assignments ca
        WHERE ca.customer_id = customers.id AND ca.employee_id = ?
      ) AND EXISTS (
        SELECT 1 FROM financing_requests fr
        WHERE fr.customer_id = customers.id AND fr.tenant_id = ?
          AND COALESCE(fr.is_completed, 0) = 0
      ) AND NOT EXISTS (
        SELECT 1 FROM contracts co
        WHERE co.customer_id = customers.id AND co.tenant_id = ?
          AND COALESCE(co.is_archived, 0) = 0
          AND co.status NOT IN ('مكتمل', 'مؤرشف')
      )`
      customersParams.push(userInfo.tenantId, userInfo.userId, userInfo.tenantId, userInfo.tenantId)
    } else {
      customersQuery += ` WHERE tenant_id = ? AND EXISTS (
        SELECT 1 FROM customer_assignments ca
        WHERE ca.customer_id = customers.id AND ca.employee_id = ?
      )`
      customersParams.push(userInfo.tenantId, userInfo.userId)
    }
  } else if (userInfo.roleId === 6) {
    if (!userInfo.tenantId || !userInfo.userId) {
      return { results: [] }
    }
    const role6ScopeSql = `(
      EXISTS (
        SELECT 1 FROM customer_assignments ca
        WHERE ca.customer_id = customers.id AND ca.employee_id = ?
      )
      OR customers.assigned_bank_agent_id = ?
      OR EXISTS (
        SELECT 1 FROM financing_requests fr0
        WHERE fr0.customer_id = customers.id AND fr0.assigned_bank_agent_id = ?
      )
    )`
    if (opts?.filterRole4ByFundingRequests) {
      customersQuery += ` WHERE tenant_id = ? AND ${role6ScopeSql}
      AND EXISTS (
        SELECT 1 FROM financing_requests fr
        WHERE fr.customer_id = customers.id AND fr.tenant_id = ?
          AND COALESCE(fr.is_completed, 0) = 0
      ) AND NOT EXISTS (
        SELECT 1 FROM contracts co
        WHERE co.customer_id = customers.id AND co.tenant_id = ?
          AND COALESCE(co.is_archived, 0) = 0
          AND co.status NOT IN ('مكتمل', 'مؤرشف')
      )`
      customersParams.push(
        userInfo.tenantId,
        userInfo.userId,
        userInfo.userId,
        userInfo.userId,
        userInfo.tenantId,
        userInfo.tenantId
      )
    } else {
      customersQuery += ` WHERE tenant_id = ? AND ${role6ScopeSql}`
      customersParams.push(userInfo.tenantId, userInfo.userId, userInfo.userId, userInfo.userId)
    }
  } else if (normalizeRoleId(userInfo.roleId) === 5) {
    if (!userInfo.tenantId || !userInfo.userId) {
      return { results: [] }
    }
    customersQuery += ` WHERE tenant_id = ? AND (
      created_by = ?
      OR EXISTS (
        SELECT 1 FROM financing_requests fr
        WHERE fr.customer_id = customers.id AND fr.assigned_bank_agent_id = ?
      )
    )`
    customersParams.push(userInfo.tenantId, userInfo.userId, userInfo.userId)
  } else {
    customersQuery += ' WHERE 1 = 0'
  }
  customersQuery += ' ORDER BY full_name'
  let customers: { results?: unknown[] }
  try {
    customers = customersParams.length
      ? await c.env.DB.prepare(customersQuery).bind(...customersParams).all()
      : await c.env.DB.prepare(customersQuery).all()
  } catch (e: any) {
    // Backwards-compatible fallback if is_completed column does not exist yet.
    const msg = String(e?.message || e || '')
    if (/no such column:\s*is_completed/i.test(msg) && userInfo.tenantId != null) {
      const safeQuery = customersQuery.replace('COALESCE(is_completed, 0) as is_completed', '0 as is_completed')
      customers = customersParams.length
        ? await c.env.DB.prepare(safeQuery).bind(...customersParams).all()
        : await c.env.DB.prepare(safeQuery).all()
    } else {
      throw e
    }
  }
  return { results: (customers.results || []) as any[] }
}

/** True if this customer already has any financing_requests row (one request per customer). */
async function customerHasFinancingRequest(db: any, customerId: number | string | null | undefined): Promise<boolean> {
  const id = Number(customerId)
  if (!Number.isFinite(id) || id <= 0) return false
  const row = await db.prepare('SELECT 1 AS ok FROM financing_requests WHERE customer_id = ? LIMIT 1').bind(id).first()
  return row != null
}

function isSuperAdminUser(info: { roleId: number | null; tokenRoleId: number | null }): boolean {
  // Treat as super-admin only if BOTH DB role and token role agree on 1.
  return info.roleId === 1 && (info.tokenRoleId === null || info.tokenRoleId === 1)
}

