// USERS APIs

// Get all users
app.get('/api/users', async (c) => {
  try {
    // Get user info including role_id
    const userInfo = await getUserInfo(c)
    if (!userInfo.userId) {
      return c.json({ success: false, error: 'Unauthorized' }, 401)
    }
    const roleId = userInfo.roleId
    const tenantId = userInfo.tenantId
    
    // Resolve role_name from u.role_id only (scalar subqueries). Avoid GROUP BY + permission JOINs —
    // SQLite can surface inconsistent non-aggregated columns; old rows then showed wrong role_name (e.g. "employee").
    let query = `
      SELECT u.*,
             (SELECT role_name FROM roles WHERE id = u.role_id) AS role_name,
             (SELECT description FROM roles WHERE id = u.role_id) AS role_description,
             t.company_name AS tenant_name,
             (SELECT COUNT(DISTINCT permission_id) FROM role_permissions WHERE role_id = u.role_id) AS permissions_count
      FROM users u
      LEFT JOIN tenants t ON u.tenant_id = t.id`
    
    // Superadmin (role_id = 1) can see all users
    // Other roles see only their tenant's users + bank agents whose bank belongs to the same tenant
    if (roleId !== 1 && tenantId) {
      query += ` WHERE (u.tenant_id = ${tenantId} OR (u.role_id IN (5, 15, 6) AND EXISTS (SELECT 1 FROM banks b WHERE b.id = u.assigned_bank_id AND b.tenant_id = ${tenantId})))`
    }
    
    query += `
      ORDER BY u.id DESC`
    
    const { results } = await c.env.DB.prepare(query).all()
    const normalizedResults = (results || []).map((u: any) => ({
      ...u,
      role_name: getRoleDisplayName(u.role_id, u.role_name),
      company_name: u.tenant_name || null,
    }))
    return c.json({ success: true, data: normalizedResults })
  } catch (error: any) {
    return c.json({ success: false, error: error.message }, 500)
  }
})

// TEMP: HR backfill — remove endpoint + UI when migration complete
app.post('/api/admin/sync-users-to-hr', async (c) => {
  try {
    const userInfo = await getUserInfo(c)
    if (!userInfo.userId) {
      return c.json({ success: false, error: 'Unauthorized' }, 401)
    }
    const superU = isSuperAdminUser(userInfo)
    const companyAdmin = userInfo.roleId === 2
    if (!superU && !companyAdmin) {
      return c.json({ success: false, error: 'Forbidden' }, 403)
    }

    let tenantFilter: number | null = null
    if (superU) {
      const body = (await c.req.json().catch(() => ({}))) as { tenant_id?: unknown }
      const raw = body?.tenant_id
      if (raw != null && String(raw).trim() !== '') {
        const p = parseInt(String(raw), 10)
        tenantFilter = Number.isNaN(p) ? null : p
      }
    } else if (userInfo.tenantId != null && !Number.isNaN(Number(userInfo.tenantId))) {
      tenantFilter = userInfo.tenantId
    } else {
      return c.json({ success: false, error: 'No tenant context' }, 400)
    }

    const { synced, skipped, errors } = await bulkSyncUsersToHrEmployees(c.env.DB, tenantFilter)
    return c.json({
      success: true,
      message: 'تمت المزامنة',
      synced,
      skipped,
      errors,
      tenant_id: tenantFilter,
    })
  } catch (error: any) {
    return c.json({ success: false, error: error.message || 'Sync failed' }, 500)
  }
})

// Add user
app.post('/api/users', async (c) => {
  try {
    const formData = await c.req.formData()
    const username = String(formData.get('username') ?? '').trim()
    const password = formData.get('password')
    const full_name = formData.get('full_name')
    const emailRaw = formData.get('email')
    const email =
      emailRaw != null && String(emailRaw).trim() !== ''
        ? String(emailRaw).trim().toLowerCase()
        : null
    const phone = formData.get('phone')
    const hr_section_raw = formData.get('hr_section')
    const hr_section =
      hr_section_raw != null && String(hr_section_raw).trim() !== ''
        ? String(hr_section_raw).trim()
        : null
    const role_id = formData.get('role_id')
    const subscription_id = formData.get('subscription_id') || null
    const is_active = formData.get('is_active') || '1'
    
    // Get user info to check role
    const userInfo = await getUserInfo(c);
    if (!userInfo.userId) {
      return c.json({ success: false, error: 'Unauthorized' }, 401)
    }

    const requestedRoleId = Number.parseInt(String(role_id || ''), 10)
    if (Number.isNaN(requestedRoleId)) {
      return c.json({ success: false, error: 'Invalid role_id' }, 400)
    }

    // Only super admin can create SaaS super admin users (role_id = 1)
    if (requestedRoleId === 1 && !isSuperAdminUser(userInfo)) {
      return c.json({ success: false, error: 'Forbidden: cannot grant SaaS role' }, 403)
    }
    
    // Get tenant_id from form data (if provided by super admin)
    // If not provided, use the current user's tenant_id (for company admin adding users)
    let tenant_id: number | null = null
    const tenantRaw = formData.get('tenant_id')

    if (isSuperAdminUser(userInfo)) {
      if (tenantRaw != null && String(tenantRaw).trim() !== '') {
        const parsed = parseInt(String(tenantRaw), 10)
        tenant_id = Number.isNaN(parsed) ? null : parsed
      } else {
        tenant_id = null
      }
    } else {
      // Non-superadmin: ignore any provided tenant_id to prevent cross-tenant creation
      if (!userInfo.tenantId) {
        return c.json({ success: false, error: 'No tenant context' }, 400)
      }
      tenant_id = userInfo.tenantId
    }

    let assigned_bank_id: number | null = null
    if (requestedRoleId === 5 || requestedRoleId === 6) {
      const canCreateBankAgent = isSuperAdminUser(userInfo) || userInfo.roleId === 2
      if (!canCreateBankAgent) {
        return c.json({ success: false, error: 'غير مسموح بإنشاء موظف التمويل أو الموظف المزدوج' }, 403)
      }
      const tid = typeof tenant_id === 'number' ? tenant_id : parseInt(String(tenant_id || ''), 10)
      if (!tid || Number.isNaN(tid)) {
        return c.json({ success: false, error: 'يجب اختيار الشركة لهذا الدور' }, 400)
      }
      assigned_bank_id = null
    }
    
    if (!username) {
      return c.json({ success: false, error: 'اسم المستخدم مطلوب' }, 400)
    }

    if (!email) {
      return c.json({
        success: false,
        error: 'البريد الإلكتروني مطلوب — يُستخدم لإرسال رمز استعادة كلمة المرور.',
      }, 400)
    }

    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      return c.json({ success: false, error: 'صيغة البريد الإلكتروني غير صحيحة' }, 400)
    }

    // Check for duplicate username (case-insensitive, trimmed)
    const existingUser = await c.env.DB.prepare(`
      SELECT id FROM users WHERE LOWER(TRIM(username)) = LOWER(?)
    `).bind(username).first()
    
    if (existingUser) {
      return c.json({ 
        success: false, 
        error: 'اسم المستخدم موجود مسبقاً! الرجاء اختيار اسم مستخدم آخر.' 
      }, 400)
    }
    
    const existingEmail = await c.env.DB.prepare(`
      SELECT id FROM users
      WHERE email IS NOT NULL AND LOWER(TRIM(email)) = ?
    `).bind(email).first()

    if (existingEmail) {
      return c.json({
        success: false,
        error: 'البريد الإلكتروني موجود مسبقاً! الرجاء استخدام بريد إلكتروني آخر.',
      }, 400)
    }
    
    const result = await c.env.DB.prepare(`
      INSERT INTO users (username, password, full_name, email, phone, hr_section, role_id, subscription_id, is_active, tenant_id, assigned_bank_id)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `)
      .bind(
        username,
        password,
        full_name,
        email,
        phone,
        hr_section,
        requestedRoleId,
        subscription_id,
        is_active,
        tenant_id,
        assigned_bank_id
      )
      .run()

    const newUserId = result.meta.last_row_id

    if (typeof tenant_id === 'number' && !Number.isNaN(tenant_id) && newUserId != null && Number(newUserId) > 0) {
      await allocateTenantUserNumber(c.env.DB, Number(newUserId), tenant_id)
    }

    const needsHrRow =
      (requestedRoleId === 3 || requestedRoleId === 4 || requestedRoleId === 5 || requestedRoleId === 6) &&
      typeof tenant_id === 'number' &&
      !Number.isNaN(tenant_id)

    if (needsHrRow && newUserId != null && Number(newUserId) > 0 && typeof tenant_id === 'number') {
      try {
        const hrTenantId = tenant_id
        const emailStr = email
        const phoneStr = phone != null && String(phone).trim() !== '' ? String(phone).trim() : null
        const fullStr = full_name != null ? String(full_name).trim() : ''
        await syncNewUserToHrEmployees(c.env.DB, {
          tenantId: hrTenantId,
          userId: Number(newUserId),
          roleId: requestedRoleId,
          fullName: fullStr,
          username: String(username ?? ''),
          email: emailStr,
          phone: phoneStr,
          department: hr_section,
        })
      } catch (hrErr: any) {
        console.error('Error syncing new user to hr_employees:', hrErr)
        await c.env.DB.prepare('DELETE FROM users WHERE id = ?').bind(newUserId).run()
        return c.json(
          {
            success: false,
            error:
              hrErr?.message ||
              'تم إنشاء الحساب لكن تعذر إضافة السجل في الموارد البشرية. لم يتم حفظ المستخدم.',
          },
          500
        )
      }
    }

    return c.json({
      success: true,
      message: 'تم إضافة المستخدم بنجاح',
      userId: newUserId,
    })
  } catch (error: any) {
    console.error('Error adding user:', error)
    const msg = String(error?.message ?? '')
    if (msg.includes('UNIQUE constraint')) {
      if (msg.includes('users.email')) {
        return c.json({
          success: false,
          error: 'البريد الإلكتروني موجود مسبقاً! الرجاء استخدام بريد إلكتروني آخر.',
        }, 400)
      }
      if (msg.includes('users.username')) {
        return c.json({
          success: false,
          error: 'اسم المستخدم موجود مسبقاً! الرجاء اختيار اسم مستخدم آخر.',
        }, 400)
      }
    }
    return c.json({ 
      success: false, 
      error: error.message || 'حدث خطأ أثناء إضافة المستخدم' 
    }, 500)
  }
})

// Banks available for a company (e.g. assigning a bank agent). Super admin or company admin only.
app.get('/api/admin/company-banks', async (c) => {
  try {
    const userInfo = await getUserInfo(c)
    if (!userInfo.userId) {
      return c.json({ success: false, error: 'Unauthorized' }, 401)
    }
    if (!isSuperAdminUser(userInfo) && userInfo.roleId !== 2) {
      return c.json({ success: false, error: 'Forbidden' }, 403)
    }
    const tidRaw = c.req.query('tenant_id')
    const tid = tidRaw != null && String(tidRaw).trim() !== '' ? parseInt(String(tidRaw), 10) : NaN
    if (!tid || Number.isNaN(tid)) {
      return c.json({ success: false, error: 'tenant_id required' }, 400)
    }
    if (!isSuperAdminUser(userInfo) && userInfo.tenantId !== tid) {
      return c.json({ success: false, error: 'Forbidden' }, 403)
    }
    try {
      const { results } = await c.env.DB
        .prepare(
          `SELECT id, bank_name FROM banks WHERE is_active = 1 AND (tenant_id = ? OR tenant_id IS NULL) ORDER BY bank_name`
        )
        .bind(tid)
        .all()
      return c.json({ success: true, data: results || [] })
    } catch {
      const { results } = await c.env.DB
        .prepare(`SELECT id, bank_name FROM banks WHERE tenant_id = ? OR tenant_id IS NULL ORDER BY bank_name`)
        .bind(tid)
        .all()
      return c.json({ success: true, data: results || [] })
    }
  } catch (error: any) {
    return c.json({ success: false, error: error.message }, 500)
  }
})

