// Update user
app.put('/api/users/:id', async (c) => {
  try {
    const requester = await getUserInfo(c)
    if (!requester.userId) {
      return c.json({ success: false, error: 'Unauthorized' }, 401)
    }
    const id = c.req.param('id')
    const body = await c.req.json()
    const { username, full_name, email, phone, role_id, subscription_id, is_active } = body

    const requestedRoleId = Number.parseInt(String(role_id ?? ''), 10)
    if (Number.isNaN(requestedRoleId)) {
      return c.json({ success: false, error: 'Invalid role_id' }, 400)
    }
    if (requestedRoleId === 1 && !isSuperAdminUser(requester)) {
      return c.json({ success: false, error: 'Forbidden: cannot grant SaaS role' }, 403)
    }

    const target = await c.env.DB.prepare(`SELECT id, tenant_id, role_id, assigned_bank_id FROM users WHERE id = ?`).bind(id).first() as {
      id?: number
      tenant_id?: number | null
      role_id?: number | null
      assigned_bank_id?: number | null
    } | null
    if (!target) {
      return c.json({ success: false, error: 'User not found' }, 404)
    }
    const roleChange = await validateStaffRoleChange(
      c.env.DB,
      Number(id),
      target.role_id,
      requestedRoleId
    )
    if (!roleChange.ok) {
      return c.json({ success: false, error: roleChange.error }, 400)
    }
    let assigned_bank_id: number | null = null
    if (requestedRoleId === 5 || requestedRoleId === 6) {
      const canSetBankAgent = isSuperAdminUser(requester) || requester.roleId === 2
      if (!canSetBankAgent) {
        return c.json({ success: false, error: 'Forbidden' }, 403)
      }
      const tid = target.tenant_id != null ? Number(target.tenant_id) : null
      if (!tid) {
        return c.json({ success: false, error: 'This role requires a company (tenant)' }, 400)
      }
      assigned_bank_id =
        target.assigned_bank_id != null && !Number.isNaN(Number(target.assigned_bank_id))
          ? Number(target.assigned_bank_id)
          : null
    }

    await c.env.DB.prepare(`
      UPDATE users 
      SET username = ?, full_name = ?, email = ?, phone = ?, role_id = ?, subscription_id = ?, is_active = ?, assigned_bank_id = ?
      WHERE id = ?
    `).bind(username, full_name, email, phone, requestedRoleId, subscription_id, is_active, assigned_bank_id, id).run()
    return c.json({ success: true })
  } catch (error: any) {
    return c.json({ success: false, error: error.message }, 500)
  }
})

// CUSTOMERS APIs

// Get all customers
app.get('/api/customers', async (c) => {
  try {
    // Get user info (userId, tenantId, roleId)
    const userInfo = await getUserInfo(c);
    
    // Build query with role-based filtering
    // No JOIN to financing_requests + GROUP BY: that duplicates rows and can make c.* / assigned_bank_agent_id
    // ambiguous in SQLite. Count requests via scalar subqueries instead (one row per customer).
    let query = `
      SELECT
        c.*,
        (SELECT COUNT(*) FROM financing_requests f WHERE f.customer_id = c.id) as total_requests,
        (SELECT COUNT(*) FROM financing_requests f WHERE f.customer_id = c.id AND f.status = 'pending') as pending_requests,
        (SELECT COUNT(*) FROM financing_requests f WHERE f.customer_id = c.id AND f.status = 'approved') as approved_requests,
        tl.name as enrollment_location_name,
        (SELECT ca.employee_id FROM customer_assignments ca WHERE ca.customer_id = c.id LIMIT 1) as assigned_employee_id,
        (SELECT u2.full_name FROM customer_assignments ca JOIN users u2 ON ca.employee_id = u2.id WHERE ca.customer_id = c.id LIMIT 1) as assigned_employee_name,
        COALESCE(
          NULLIF(c.assigned_bank_agent_id, 0),
          (
            SELECT CASE
              WHEN frx.assigned_bank_agent_id IS NOT NULL AND frx.assigned_bank_agent_id != 0
                THEN frx.assigned_bank_agent_id
              WHEN frx.created_by IS NOT NULL AND ucx.role_id IN (5, 15, 6)
                THEN frx.created_by
              ELSE NULL
            END
            FROM financing_requests frx
            LEFT JOIN users ucx ON ucx.id = frx.created_by
            WHERE frx.customer_id = c.id
            ORDER BY frx.created_at DESC
            LIMIT 1
          )
        ) AS resolved_bank_agent_id,
        (
          SELECT COALESCE(NULLIF(TRIM(ub.full_name),''), ub.username) FROM users ub
          WHERE ub.id = COALESCE(
            NULLIF(c.assigned_bank_agent_id, 0),
            (
              SELECT CASE
                WHEN frx.assigned_bank_agent_id IS NOT NULL AND frx.assigned_bank_agent_id != 0
                  THEN frx.assigned_bank_agent_id
                WHEN frx.created_by IS NOT NULL AND ucx.role_id IN (5, 15, 6)
                  THEN frx.created_by
                ELSE NULL
              END
              FROM financing_requests frx
              LEFT JOIN users ucx ON ucx.id = frx.created_by
              WHERE frx.customer_id = c.id
              ORDER BY frx.created_at DESC
              LIMIT 1
            )
          )
          LIMIT 1
        ) AS assigned_bank_agent_name
      FROM customers c
      LEFT JOIN tenant_locations tl ON c.location_id = tl.id`
    
    let whereSql = ''
    const whereParams: any[] = []

    const listRoleNorm = normalizeRoleId(userInfo.roleId)
    const listRoleEffective = listRoleNorm ?? userInfo.roleId

    // Apply filtering based on role (normalized so legacy IDs 11–15 still match tenant lists)
    if (listRoleEffective === 1) {
      // Role 1: Super Admin - sees ALL customers (no filter)
    } else if (listRoleEffective === 2 || listRoleEffective === 3) {
      // Role 2: Company Admin & Role 3: Supervisor - see company customers only
      if (userInfo.tenantId) {
        whereSql = ` WHERE c.tenant_id = ?`
        whereParams.push(userInfo.tenantId)
      } else {
        whereSql = ` WHERE 1 = 0`
      }
    } else if (listRoleEffective === 4) {
      // Role 4: Employee - sees only assigned customers in same company
      if (userInfo.tenantId && userInfo.userId) {
        whereSql = ` WHERE c.tenant_id = ? AND EXISTS (
          SELECT 1 FROM customer_assignments ca
          WHERE ca.customer_id = c.id AND ca.employee_id = ?
        )`
        whereParams.push(userInfo.tenantId, userInfo.userId)
      } else {
        whereSql = ` WHERE 1 = 0` // No data if tenant scope is missing
      }
    } else if (listRoleEffective === 5) {
      if (userInfo.tenantId && userInfo.userId) {
        // Role 5: see customers they created, directly assigned to, OR tied via a financing request.
        whereSql = ` WHERE c.tenant_id = ? AND (
          c.created_by = ?
          OR c.assigned_bank_agent_id = ?
          OR EXISTS (
            SELECT 1 FROM financing_requests fr
            LEFT JOIN users fr_creator ON fr_creator.id = fr.created_by
            WHERE fr.customer_id = c.id
              AND (
                fr.assigned_bank_agent_id = ?
                OR (fr.created_by = ? AND fr_creator.role_id IN (5, 15))
              )
          )
        )`
        whereParams.push(userInfo.tenantId, userInfo.userId, userInfo.userId, userInfo.userId, userInfo.userId)
      } else {
        whereSql = ` WHERE 1 = 0`
      }
    } else if (listRoleEffective === 6) {
      if (userInfo.tenantId && userInfo.userId) {
        // Role 6 scope is context-determined by actual assignment data, not role alone:
        // - Employee path: customer_assignments row with employee_id = userId
        // - Bank-agent path: explicit assigned_bank_agent_id on customer or FR
        // Deliberately excludes created_by + fr_creator.role_id fallback to prevent an
        // employee-context FR creation from leaking bank-agent scope.
        whereSql = ` WHERE c.tenant_id = ? AND (
          EXISTS (
            SELECT 1 FROM customer_assignments ca
            WHERE ca.customer_id = c.id AND ca.employee_id = ?
          )
          OR c.assigned_bank_agent_id = ?
          OR EXISTS (
            SELECT 1 FROM financing_requests fr
            WHERE fr.customer_id = c.id AND fr.assigned_bank_agent_id = ?
          )
        )`
        whereParams.push(
          userInfo.tenantId,
          userInfo.userId, userInfo.userId,
          userInfo.userId
        )
      } else {
        whereSql = ` WHERE 1 = 0`
      }
    } else {
      // Unknown role - no data
      whereSql = ` WHERE 1 = 0`
    }

    query += `${whereSql}
      ORDER BY c.created_at DESC`

    const { page, pageSize, offset } = parsePageParams({
      page: c.req.query('page'),
      pageSize: c.req.query('pageSize'),
    })

    let total = 0
    try {
      const countSql = `SELECT COUNT(*) AS total FROM customers c LEFT JOIN tenant_locations tl ON c.location_id = tl.id${whereSql}`
      const countRow = whereParams.length
        ? await c.env.DB.prepare(countSql).bind(...whereParams).first<{ total: number }>()
        : await c.env.DB.prepare(countSql).first<{ total: number }>()
      total = Number(countRow?.total || 0)
    } catch {
      total = 0
    }

    const pagedQuery = `${query} LIMIT ? OFFSET ?`
    const pagedParams = [...whereParams, pageSize, offset]

    let results: any[] = []
    try {
      const r = await c.env.DB.prepare(pagedQuery).bind(...pagedParams).all()
      results = (r.results || []) as any[]
    } catch (e: any) {
      // Backwards-compatible fallback: if created_by or assigned_bank_agent_id column is missing.
      const msg = String(e?.message || e || '')
      const isMissingCreatedBy = /no such column:\s*c\.created_by|no such column:\s*created_by/i.test(msg)
      const isMissingDirectAgent = /no such column:\s*c\.assigned_bank_agent_id/i.test(msg)
      if (isMissingCreatedBy || isMissingDirectAgent) {
        // Rebuild query without the columns that may not exist yet.
        const bankBlockNeedle = ',\n        COALESCE(\n          NULLIF(c.assigned_bank_agent_id, 0),'
        const bankBlockEndMarker = ') AS assigned_bank_agent_name\n      FROM customers c'
        const bStart = query.indexOf(bankBlockNeedle)
        const bEnd = bStart !== -1 ? query.indexOf(bankBlockEndMarker, bStart) : -1
        const bankFieldsFallback =
          ', (SELECT COALESCE(NULLIF(TRIM(u3.full_name),\'\'), u3.username) FROM financing_requests f2 JOIN users u3 ON f2.assigned_bank_agent_id = u3.id WHERE f2.customer_id = c.id AND f2.assigned_bank_agent_id IS NOT NULL ORDER BY f2.created_at DESC LIMIT 1) as assigned_bank_agent_name'
        const legacySelect =
          bStart !== -1 && bEnd !== -1
            ? query.slice(0, bStart) + bankFieldsFallback + query.slice(bEnd + ') AS assigned_bank_agent_name'.length)
            : query
        if (normalizeRoleId(userInfo.roleId) === 5 && userInfo.tenantId && userInfo.userId) {
          const fallbackWhereSql = ` WHERE c.tenant_id = ? AND EXISTS (
            SELECT 1 FROM financing_requests fr
            LEFT JOIN users fr_creator ON fr_creator.id = fr.created_by
            WHERE fr.customer_id = c.id
              AND (
                fr.assigned_bank_agent_id = ?
                OR (fr.created_by = ? AND fr_creator.role_id IN (5, 15))
              )
          )`
          const fallbackQuery = legacySelect.replace(whereSql, fallbackWhereSql) + ' LIMIT ? OFFSET ?'
          const fr = await c.env.DB.prepare(fallbackQuery).bind(userInfo.tenantId, userInfo.userId, userInfo.userId, pageSize, offset).all()
          results = (fr.results || []) as any[]
        } else {
          const legacyParams = isMissingCreatedBy ? whereParams.slice(0, -1) : whereParams
          const legacyWhere = isMissingCreatedBy
            ? whereSql.replace(/\s*c\.created_by = \?\s*OR\s*/g, '').replace(/\s*OR\s*c\.assigned_bank_agent_id = \?/g, '')
            : whereSql.replace(/\s*OR\s*c\.assigned_bank_agent_id = \?/g, '')
          const fallbackQuery = legacySelect.replace(whereSql, legacyWhere) + ' LIMIT ? OFFSET ?'
          const r2 = await c.env.DB.prepare(fallbackQuery).bind(...legacyParams, pageSize, offset).all()
          results = (r2.results || []) as any[]
        }
      } else {
        throw e
      }
    }
    // Attach per-customer unread-alarm count for the current user (drives table glow dot).
    if (userInfo.userId && results.length > 0) {
      try {
        const alarmRows = await c.env.DB
          .prepare(`SELECT customer_id, COUNT(*) AS cnt FROM customer_alarms
                    WHERE user_id = ? AND is_read = 0 AND customer_id IS NOT NULL
                    GROUP BY customer_id`)
          .bind(userInfo.userId)
          .all<{ customer_id: number; cnt: number }>()
        const countByCustomer: Record<string, number> = {}
        for (const row of alarmRows.results || []) {
          countByCustomer[String(row.customer_id)] = Number(row.cnt) || 0
        }
        for (const r of results) {
          r.unread_alarm_count = countByCustomer[String(r.id)] || 0
        }
      } catch (_) { /* table may be missing in legacy DBs */ }
    }
    return c.json({ success: true, data: results, total, page, pageSize })
  } catch (error: any) {
    return c.json({ success: false, error: error.message }, 500)
  }
})

