// Export customers matching current list filters (server-side; avoids embedding CSV in HTML).
app.get('/api/customers/export-csv', async (c) => {
  try {
    const userInfo = await getUserInfo(c)
    if (!userInfo.userId || !userInfo.roleId) return c.json({ success: false, error: 'Unauthorized' }, 401)

    const searchQ = String(c.req.query('q') ?? '').trim()
    const filterField = String(c.req.query('filterField') ?? 'all')
    const dateRangeFilter = String(c.req.query('dateRange') ?? 'all')
    const requestsFilterQ = String(c.req.query('requestsFilter') ?? 'all')
    const ratingFilterQ = String(c.req.query('ratingFilter') ?? 'all')
    const employeeFilterQ = String(c.req.query('employeeFilter') ?? 'all')
    const bankAgentFilterQ = String(c.req.query('bankAgentFilter') ?? 'all')
    const sourceFilterQ = String(c.req.query('sourceFilter') ?? 'all')

    let query = `
      SELECT customers.id, customers.tenant_customer_number, customers.full_name, customers.phone, customers.email,
        customers.enrollment_source, customers.enrollment_source_label, customers.national_id, customers.created_at,
        u.full_name AS assigned_employee_name,
        tl.name AS enrollment_location_name,
        COALESCE(
          NULLIF(customers.assigned_bank_agent_id, 0),
          latest_fr_agent.resolved_bank_agent_id
        ) AS resolved_bank_agent_id,
        COALESCE(
          NULLIF(TRIM(ub_direct.full_name), ''),
          ub_direct.username,
          NULLIF(TRIM(ub_fr.full_name), ''),
          ub_fr.username
        ) AS assigned_bank_agent_name
      FROM customers
      LEFT JOIN customer_assignments ca ON customers.id = ca.customer_id
      LEFT JOIN users u ON ca.employee_id = u.id AND u.role_id IN (4, 5, 6, 14)
      LEFT JOIN tenant_locations tl ON customers.location_id = tl.id
      LEFT JOIN users ub_direct ON ub_direct.id = NULLIF(customers.assigned_bank_agent_id, 0)
      LEFT JOIN (
        SELECT frx.customer_id AS customer_id,
          CASE
            WHEN frx.assigned_bank_agent_id IS NOT NULL AND frx.assigned_bank_agent_id != 0 THEN frx.assigned_bank_agent_id
            WHEN frx.created_by IS NOT NULL AND ucx.role_id IN (5, 15, 6) THEN frx.created_by
            ELSE NULL
          END AS resolved_bank_agent_id
        FROM financing_requests frx
        LEFT JOIN users ucx ON ucx.id = frx.created_by
        INNER JOIN (
          SELECT customer_id, MAX(id) AS max_id FROM financing_requests GROUP BY customer_id
        ) fr_latest ON fr_latest.max_id = frx.id
      ) latest_fr_agent ON latest_fr_agent.customer_id = customers.id
      LEFT JOIN users ub_fr ON ub_fr.id = latest_fr_agent.resolved_bank_agent_id
      WHERE (customers.is_archived = 0 OR customers.is_archived IS NULL)
        AND (customers.is_completed IS NULL OR customers.is_completed = 0)`
    const queryParams: any[] = []
    const role = normalizeRoleId(userInfo.roleId)
    if (role === 1) {
      /* all */
    } else if (role === 2 || role === 3) {
      if (userInfo.tenantId) { query += ' AND customers.tenant_id = ?'; queryParams.push(userInfo.tenantId) }
      else query += ' AND 1 = 0'
    } else if (role === 4) {
      if (userInfo.tenantId && userInfo.userId) {
        query += ` AND customers.tenant_id = ? AND EXISTS (
          SELECT 1 FROM customer_assignments ca2 WHERE ca2.customer_id = customers.id AND ca2.employee_id = ?
        )`
        queryParams.push(userInfo.tenantId, userInfo.userId)
      } else query += ' AND 1 = 0'
    } else if (role === 6) {
      if (userInfo.tenantId && userInfo.userId) {
        query += ` AND customers.tenant_id = ? AND (
          EXISTS (SELECT 1 FROM customer_assignments ca2 WHERE ca2.customer_id = customers.id AND ca2.employee_id = ?)
          OR customers.assigned_bank_agent_id = ?
          OR EXISTS (SELECT 1 FROM financing_requests fr WHERE fr.customer_id = customers.id AND fr.assigned_bank_agent_id = ?)
        )`
        queryParams.push(userInfo.tenantId, userInfo.userId, userInfo.userId, userInfo.userId)
      } else query += ' AND 1 = 0'
    } else if (role === 5) {
      if (userInfo.tenantId && userInfo.userId) {
        query += ` AND customers.tenant_id = ? AND (
          customers.created_by = ? OR customers.assigned_bank_agent_id = ?
          OR EXISTS (
            SELECT 1 FROM financing_requests fr LEFT JOIN users fr_creator ON fr_creator.id = fr.created_by
            WHERE fr.customer_id = customers.id AND (
              fr.assigned_bank_agent_id = ? OR (fr.created_by = ? AND fr_creator.role_id IN (5, 15))
            )
          )
        )`
        queryParams.push(userInfo.tenantId, userInfo.userId, userInfo.userId, userInfo.userId, userInfo.userId)
      } else query += ' AND 1 = 0'
    } else {
      query += ' AND 1 = 0'
    }

    if (searchQ) {
      const like = `%${searchQ}%`
      if (filterField === 'name') { query += ' AND customers.full_name LIKE ?'; queryParams.push(like) }
      else if (filterField === 'phone') { query += ' AND customers.phone LIKE ?'; queryParams.push(like) }
      else if (filterField === 'email') { query += ' AND customers.email LIKE ?'; queryParams.push(like) }
      else {
        query += ` AND (customers.full_name LIKE ? OR customers.phone LIKE ? OR customers.email LIKE ?
          OR IFNULL(customers.enrollment_source_label, '') LIKE ? OR IFNULL(u.full_name, '') LIKE ?)`
        queryParams.push(like, like, like, like, like)
      }
    }
    if (dateRangeFilter !== 'all') {
      const days = Number.parseInt(dateRangeFilter, 10)
      if (Number.isFinite(days) && days > 0) {
        query += ` AND datetime(customers.created_at) >= datetime('now', ?)`
        queryParams.push(`-${days} days`)
      }
    }
    if (requestsFilterQ === '0') query += ` AND NOT EXISTS (SELECT 1 FROM financing_requests fr_rf WHERE fr_rf.customer_id = customers.id)`
    else if (requestsFilterQ === '1') query += ` AND EXISTS (SELECT 1 FROM financing_requests fr_rf WHERE fr_rf.customer_id = customers.id)`
    if (ratingFilterQ !== 'all' && /^\d+$/.test(ratingFilterQ)) {
      query += ` AND EXISTS (
        SELECT 1 FROM customer_reviews cr WHERE cr.customer_id = customers.id AND cr.rating = ?
        AND cr.id = (SELECT id FROM customer_reviews WHERE customer_id = customers.id ORDER BY created_at DESC LIMIT 1)
      )`
      queryParams.push(Number(ratingFilterQ))
    }
    if (employeeFilterQ === 'غير مخصص') query += ` AND (ca.employee_id IS NULL OR IFNULL(TRIM(u.full_name), '') = '')`
    else if (employeeFilterQ !== 'all') { query += ' AND IFNULL(u.full_name, "") = ?'; queryParams.push(employeeFilterQ) }
    if (bankAgentFilterQ === 'غير معيّن' || bankAgentFilterQ === 'غير معين') {
      query += ` AND COALESCE(NULLIF(customers.assigned_bank_agent_id, 0), latest_fr_agent.resolved_bank_agent_id) IS NULL`
    } else if (bankAgentFilterQ !== 'all') {
      query += ` AND (
        (IFNULL(NULLIF(TRIM(ub_direct.full_name), ''), ub_direct.username) || ' #' || CAST(ub_direct.id AS TEXT)) = ?
        OR (IFNULL(NULLIF(TRIM(ub_fr.full_name), ''), ub_fr.username) || ' #' || CAST(ub_fr.id AS TEXT)) = ?
        OR IFNULL(NULLIF(TRIM(ub_direct.full_name), ''), ub_direct.username) = ?
        OR IFNULL(NULLIF(TRIM(ub_fr.full_name), ''), ub_fr.username) = ?
      )`
      queryParams.push(bankAgentFilterQ, bankAgentFilterQ, bankAgentFilterQ, bankAgentFilterQ)
    }
    if (sourceFilterQ !== 'all') {
      const FIXED_SOURCES = ['calculator', 'csv', 'manual', 'affiliate']
      if (FIXED_SOURCES.includes(sourceFilterQ)) {
        query += ' AND customers.enrollment_source = ?'
        queryParams.push(sourceFilterQ)
      } else if (sourceFilterQ.startsWith('label:')) {
        query += ' AND customers.enrollment_source_label = ?'
        queryParams.push(sourceFilterQ.slice(6))
      }
    }

    query += ' ORDER BY customers.created_at DESC LIMIT 10000'
    const rows = await c.env.DB.prepare(query).bind(...queryParams).all()
    const header = ['#', 'الاسم', 'الهاتف', 'البريد الإلكتروني', 'المصدر', 'الموقع', 'الموظف المخصص', 'موظف البنك', 'الرقم الوطني', 'تاريخ التسجيل']
    const dataRows = ((rows.results || []) as any[]).map((customer) => {
      const custAgentId = customer.resolved_bank_agent_id != null ? Number(customer.resolved_bank_agent_id) : null
      const custAgentName = customer.assigned_bank_agent_name ? String(customer.assigned_bank_agent_name) : ''
      const bankCol = !custAgentId || Number.isNaN(custAgentId) ? 'غير معيّن' : custAgentName || '—'
      const src =
        customer.enrollment_source === 'calculator' ? 'الحاسبة'
          : customer.enrollment_source === 'affiliate' ? (customer.enrollment_source_label || 'affiliate')
            : customer.enrollment_source === 'csv' ? String(customer.enrollment_source_label || '').trim() || 'CSV'
              : customer.enrollment_source === 'manual' ? String(customer.enrollment_source_label || '').trim() || 'يدوي'
                : String(customer.enrollment_source_label || '').trim()
      return [
        String(customer.tenant_customer_number ?? ''),
        String(customer.full_name || '-'),
        String(customer.phone || '-'),
        String(customer.email || '-'),
        String(src || ''),
        String(customer.enrollment_location_name || '—'),
        String(customer.assigned_employee_name || 'غير مخصص'),
        String(bankCol || '—'),
        String(customer.national_id || '-'),
        new Date(customer.created_at).toLocaleDateString('ar-SA'),
      ]
    })
    const xml = buildSpreadsheetML([header, ...dataRows], 'العملاء')
    return spreadsheetMLAttachmentResponse(xml, `customers_export_${new Date().toISOString().slice(0, 10)}.xls`)
  } catch (error: any) {
    return c.json({ success: false, error: error.message }, 500)
  }
})

// Import customers from CSV (parsed client-side and sent as JSON)
app.post('/api/customers/import-csv', async (c) => {
  try {
    const userInfo = await getUserInfo(c)
    if (!userInfo.userId || !userInfo.roleId) {
      return c.json({ success: false, error: 'غير مصرح' }, 401)
    }
    if (userInfo.roleId === 3) {
      return c.json({ success: false, error: 'Forbidden' }, 403)
    }

    const body = await c.req.json().catch(() => null) as any
    const incoming = body?.customers
    if (!Array.isArray(incoming) || incoming.length === 0) {
      return c.json({ success: false, error: 'لا توجد بيانات للرفع' }, 400)
    }
    const autoDistributeEmployees = body?.auto_distribute_employees === true
    const autoDistributeBankAgents = body?.auto_distribute_bank_agents === true
    const enrollmentSourceLabel = body?.enrollment_source_label
      ? String(body.enrollment_source_label).trim().slice(0, 200) || null
      : null

    // Resolve tenant scope
    let tenant_id: number | null = userInfo.tenantId != null ? Number(userInfo.tenantId) : null
    if (!tenant_id && userInfo.roleId === 1) {
      const tidFromBody = Number.parseInt(String(body?.tenant_id ?? ''), 10)
      if (!Number.isNaN(tidFromBody) && tidFromBody > 0) tenant_id = tidFromBody
    }
    if (!tenant_id) {
      const defaultTenant = await c.env.DB.prepare(
        `SELECT id FROM tenants WHERE status = 'active' ORDER BY id LIMIT 1`
      ).first<{ id: number }>()
      if (defaultTenant?.id) tenant_id = defaultTenant.id
    }
    if (!tenant_id) {
      return c.json({ success: false, error: 'يجب تحديد الشركة' }, 400)
    }

    let created = 0
    let updated = 0
    const errors: string[] = []
    const newCustomerIds: number[] = []

    for (let i = 0; i < incoming.length; i++) {
      const row = incoming[i] || {}
      try {
        const full_name = String(row.full_name ?? row.name ?? '').trim()
        const rawPhone = String(row.phone ?? '').trim()
        if (!full_name) {
          errors.push(`Row ${i + 1}: full_name is required`)
          continue
        }
        const normalizedPhoneResult = normalizeCustomerPhoneForStorage(rawPhone)
        if (!normalizedPhoneResult.normalized) {
          errors.push(`Row ${i + 1}: phone invalid (${normalizedPhoneResult.error || rawPhone})`)
          continue
        }
        const phone = normalizedPhoneResult.normalized
        const email = row.email != null && String(row.email).trim() ? String(row.email).trim() : null
        const national_id =
          row.national_id != null && String(row.national_id).trim() ? String(row.national_id).trim() : null
        const monthly_salary = row.monthly_salary != null && String(row.monthly_salary).trim()
          ? (parseFloat(String(row.monthly_salary).trim()) || null)
          : null

        const existing = await c.env.DB.prepare(
          `SELECT id FROM customers WHERE phone = ? AND tenant_id = ? LIMIT 1`
        ).bind(phone, tenant_id).first<{ id: number }>()

        if (existing?.id) {
          await c.env.DB.prepare(
            `UPDATE customers
             SET full_name = ?, email = ?, national_id = ?, monthly_salary = COALESCE(?, monthly_salary), updated_at = CURRENT_TIMESTAMP
             WHERE id = ? AND tenant_id = ?`
          ).bind(full_name, email, national_id, monthly_salary, existing.id, tenant_id).run()
          updated++
        } else {
          const insertRes = await c.env.DB.prepare(
            `INSERT INTO customers (full_name, phone, email, national_id, monthly_salary, enrollment_source, enrollment_source_label, tenant_id)
             VALUES (?, ?, ?, ?, ?, 'csv', ?, ?)`
          ).bind(full_name, phone, email, national_id, monthly_salary, enrollmentSourceLabel, tenant_id).run() as { meta?: { last_row_id?: number } }

          const createdCustomerId = Number(insertRes?.meta?.last_row_id || 0)
          if (createdCustomerId) {
            await allocateTenantCustomerNumber(c.env.DB, createdCustomerId, tenant_id)
          }
          if (userInfo.userId && createdCustomerId) {
            try {
              await c.env.DB.prepare(`UPDATE customers SET created_by = ? WHERE id = ?`)
                .bind(userInfo.userId, createdCustomerId).run()
            } catch (_) { /* column may not exist in older DBs */ }
          }
          if (createdCustomerId) {
            newCustomerIds.push(createdCustomerId)
            try {
              await allocateTenantCustomerNumber(c.env.DB, createdCustomerId, tenant_id)
            } catch (_) { /* best-effort */ }
          }
          created++
        }
      } catch (e: any) {
        errors.push(`Row ${i + 1}: ${e?.message || String(e)}`)
      }
    }

    // Distribute newly created customers using tenant rules
    if (newCustomerIds.length) {
      if (autoDistributeEmployees) {
        await distributeCustomersToEmployees(c.env.DB, tenant_id, newCustomerIds, userInfo.userId ?? 1)
      }
      if (autoDistributeBankAgents) {
        await distributeCustomersToBankAgents(c.env.DB, tenant_id, newCustomerIds)
      }
    }

    return c.json({
      success: true,
      created,
      updated,
      errors: errors.length ? errors : undefined,
      message: `تمت إضافة ${created} وتحديث ${updated}`
    })
  } catch (error: any) {
    return c.json({ success: false, error: error.message }, 500)
  }
})

// Add new customer
app.post('/api/customers', async (c) => {
  const inlineCustomerForm = c.req.header('X-Customer-Form') === '1'
  try {
    const formData = await c.req.formData()
    const full_name = formData.get('full_name') as string
    const rawPhone = formData.get('phone') as string
    const normalizedPhoneResult = normalizeCustomerPhoneForStorage(rawPhone)
    if (!normalizedPhoneResult.normalized) {
      if (inlineCustomerForm) {
        return c.json(
          {
            ok: false,
            code: 'INVALID_PHONE',
            message: normalizedPhoneResult.error || 'يرجى مراجعة رقم الجوال',
            hint:
              'أدخل فقط 9 أرقام تبدأ بـ 5. الصيغة: 5XXXXXXXX (يُحفظ تلقائياً كـ 9665XXXXXXXX).',
          },
          400
        )
      }
      return c.html(`
        <!DOCTYPE html>
        <html lang="ar" dir="rtl">
        <head>
          <meta charset="UTF-8">
          <meta name="viewport" content="width=device-width, initial-scale=1.0">
          <title>تنسيق رقم الجوال غير صحيح</title>
          <script src="https://cdn.tailwindcss.com"></script>
          <link href="https://cdn.jsdelivr.net/npm/@fortawesome/fontawesome-free@6.4.0/css/all.min.css" rel="stylesheet">
        </head>
        <body class="bg-gray-50">
          <div class="max-w-2xl mx-auto p-6 mt-20">
            <div class="bg-amber-50 border-r-4 border-amber-500 rounded-lg p-6 shadow-lg">
              <div class="flex items-center mb-3">
                <i class="fas fa-phone-slash text-amber-600 text-3xl ml-3"></i>
                <h1 class="text-2xl font-bold text-amber-800">تنسيق رقم الجوال غير صحيح</h1>
              </div>
              <p class="text-amber-700 mb-3">${normalizedPhoneResult.error || 'يرجى مراجعة رقم الجوال'}</p>
              <div class="bg-white rounded-lg p-3 text-sm text-gray-700 mb-4">
                <p><strong>الطريقة الصحيحة:</strong> أدخل فقط 9 أرقام تبدأ بـ <span dir="ltr">5</span>.</p>
                <p><strong>الصيغة:</strong> <span dir="ltr">5XXXXXXXX</span> (وسيتم حفظه تلقائياً كـ <span dir="ltr">9665XXXXXXXX</span>).</p>
              </div>
              <a href="/admin/customers/add" class="inline-flex items-center bg-blue-600 hover:bg-blue-700 text-white px-5 py-2 rounded-lg font-bold transition-all">
                <i class="fas fa-arrow-right ml-2"></i>
                العودة للنموذج
              </a>
            </div>
          </div>
        </body>
        </html>
      `, 400)
    }
    const phone = normalizedPhoneResult.normalized
    const email = formData.get('email') as string || null
    const national_id_raw = formData.get('national_id') as string | null
    const national_id =
      national_id_raw != null && String(national_id_raw).trim()
        ? String(national_id_raw).trim()
        : null
    const date_of_birth = formData.get('date_of_birth') as string || null
    const dob_calendar_type = (formData.get('dob_calendar_type') as string) || 'gregorian'
    const employer_name = formData.get('employer_name') as string || null
    const job_type = normalizeCustomerJobType(formData.get('job_type'))
    const job_title = formData.get('job_title') as string || null
    const military_rank = formData.get('military_rank') as string || null
    const work_start_date = formData.get('work_start_date') as string || null
    const city = formData.get('city') as string || null
    const product_type = normalizeCustomerProductType(formData.get('product_type'))
    const property_type = normalizeCustomerPropertyType(formData.get('property_type'))
    const property_owner = (formData.get('property_owner') as string)?.trim() || null
    const real_estate_office = (formData.get('real_estate_office') as string)?.trim() || null
    const basic_salary = formData.get('basic_salary') ? parseFloat(formData.get('basic_salary') as string) : null
    const salary_bank_id_raw = Number.parseInt(String(formData.get('salary_bank_id') ?? ''), 10)
    const salary_bank_id = Number.isFinite(salary_bank_id_raw) && salary_bank_id_raw > 0 ? salary_bank_id_raw : null
    const monthly_salary = parseFloat(formData.get('monthly_salary') as string || '0')
    const notes = (formData.get('notes') as string)?.trim() || null
    const rawEnrollmentSource = String(formData.get('enrollment_source') ?? '').trim()
    let enrollment_source: string | null = null
    let enrollment_source_label: string | null = null
    if (rawEnrollmentSource === 'affiliate' || rawEnrollmentSource === 'calculator') {
      enrollment_source = rawEnrollmentSource
      enrollment_source_label =
        rawEnrollmentSource === 'affiliate'
          ? (String(formData.get('enrollment_source_label') ?? '').trim().slice(0, 200) || null)
          : null
    } else {
      const manualSource = String(formData.get('manual_enrollment_source') ?? '').trim().slice(0, 200)
      if (manualSource) {
        enrollment_source = 'manual'
        enrollment_source_label = manualSource
      }
    }
    const solutions_json = normalizeCustomerSolutionsJson(formData.get('solutions_json') as string | null)
    const customerAttachmentsFromForm = normalizeCustomerAttachmentsJson(
      formData.get('attachments_json') as string | null
    )
    const identity_attachment_url = (formData.get('identity_attachment_url') as string || '').trim() || null
    const signature_attachment_url = (formData.get('signature_attachment_url') as string || '').trim() || null
    const salary_profile_attachment_url = (formData.get('salary_profile_attachment_url') as string || '').trim() || null
    const gosi_attachment_url = (formData.get('gosi_attachment_url') as string || '').trim() || null
    const tax_exemption_attachment_url = (formData.get('tax_exemption_attachment_url') as string || '').trim() || null
    const additional_1_attachment_url = (formData.get('additional_1_attachment_url') as string || '').trim() || null
    const additional_2_attachment_url = (formData.get('additional_2_attachment_url') as string || '').trim() || null
    const additional_3_attachment_url = (formData.get('additional_3_attachment_url') as string || '').trim() || null
    
    // Resolve tenant from authenticated user (supports both cookie + bearer flows).
    const userInfo = await getUserInfo(c)
    let tenant_id = userInfo.tenantId
    const creatorUserId = userInfo.userId

    // Super admin may not have a fixed tenant on account; accept form tenant first.
    if (!tenant_id && userInfo.roleId === 1) {
      const tenantIdFromForm = Number.parseInt(String(formData.get('tenant_id') ?? ''), 10)
      if (!Number.isNaN(tenantIdFromForm) && tenantIdFromForm > 0) {
        tenant_id = tenantIdFromForm
      }
    }

    const creatorRoleForTenant = normalizeRoleId(userInfo.roleId)
    if (
      !tenant_id &&
      creatorRoleForTenant != null &&
      creatorRoleForTenant !== 1
    ) {
      const noTenantMsg = 'يجب ربط حسابك بشركة قبل إضافة عملاء.'
      if (inlineCustomerForm) {
        return c.json({ ok: false, code: 'NO_TENANT', message: noTenantMsg }, 400)
      }
      return c.html(
        `<!DOCTYPE html><html lang="ar" dir="rtl"><head><meta charset="UTF-8"><title>خطأ</title><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-gray-50 p-8"><div class="max-w-lg mx-auto bg-red-50 border border-red-200 p-6 rounded-lg"><h1 class="text-xl font-bold text-red-900">شركة غير محددة</h1><p class="text-red-800 mt-2">${noTenantMsg}</p><a href="/admin/customers/add" class="inline-block mt-4 text-blue-600 underline">العودة</a></div></body></html>`,
        400
      )
    }

    // Super-admin only: fallback to first active tenant when form tenant not provided.
    if (!tenant_id && creatorRoleForTenant === 1) {
      const defaultTenant = await c.env.DB.prepare(`
        SELECT id FROM tenants WHERE status = 'active' ORDER BY id LIMIT 1
      `).first<{ id: number }>()
      if (defaultTenant?.id) {
        tenant_id = defaultTenant.id
      }
    }

    if (!tenant_id) {
      throw new Error('Missing tenant context for customer creation')
    }

    const activeLocCountRow = await c.env.DB.prepare(
      `SELECT COUNT(*) as n FROM tenant_locations WHERE tenant_id = ? AND is_active = 1`
    )
      .bind(tenant_id)
      .first<{ n: number }>()
    const activeLocationCount = Number(activeLocCountRow?.n ?? 0)

    const locationIdRaw = formData.get('location_id')
    let resolvedLocationId: number | null = null
    if (locationIdRaw != null && String(locationIdRaw).trim() !== '') {
      const lid = Number.parseInt(String(locationIdRaw), 10)
      if (!Number.isFinite(lid) || lid <= 0) {
        if (inlineCustomerForm) {
          return c.json(
            { ok: false, code: 'INVALID_LOCATION', message: 'يرجى اختيار موقع تسجيل صحيح.' },
            400
          )
        }
        return c.html(
          `<!DOCTYPE html><html lang="ar" dir="rtl"><head><meta charset="UTF-8"><title>خطأ</title><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-gray-50 p-8"><div class="max-w-lg mx-auto bg-amber-50 border border-amber-200 p-6 rounded-lg"><h1 class="text-xl font-bold text-amber-900">موقع غير صالح</h1><p class="text-amber-800 mt-2">يرجى اختيار موقع تسجيل صحيح.</p><a href="/admin/customers/add" class="inline-block mt-4 text-blue-600 underline">العودة</a></div></body></html>`,
          400
        )
      }
      const locOk = await c.env.DB.prepare(
        `SELECT id FROM tenant_locations WHERE id = ? AND tenant_id = ? AND is_active = 1 LIMIT 1`
      )
        .bind(lid, tenant_id)
        .first<{ id: number }>()
      if (!locOk) {
        if (inlineCustomerForm) {
          return c.json(
            { ok: false, code: 'LOCATION_NOT_ALLOWED', message: 'الموقع المختار لا يتبع هذه الشركة أو غير مفعّل.' },
            400
          )
        }
        return c.html(
          `<!DOCTYPE html><html lang="ar" dir="rtl"><head><meta charset="UTF-8"><title>خطأ</title><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-gray-50 p-8"><div class="max-w-lg mx-auto bg-red-50 border border-red-200 p-6 rounded-lg"><h1 class="text-xl font-bold text-red-900">الموقع لا يتبع هذه الشركة</h1><a href="/admin/customers/add" class="inline-block mt-4 text-blue-600 underline">العودة</a></div></body></html>`,
          400
        )
      }
      resolvedLocationId = lid
    } else if (activeLocationCount > 0) {
      if (inlineCustomerForm) {
        return c.json(
          {
            ok: false,
            code: 'LOCATION_REQUIRED',
            message: 'موقع التسجيل مطلوب. اختر الفرع الذي سُجّل فيه العميل.',
          },
          400
        )
      }
      return c.html(
        `<!DOCTYPE html><html lang="ar" dir="rtl"><head><meta charset="UTF-8"><title>خطأ</title><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-gray-50 p-8"><div class="max-w-lg mx-auto bg-amber-50 border border-amber-200 p-6 rounded-lg"><h1 class="text-xl font-bold text-amber-900">موقع التسجيل مطلوب</h1><p class="text-amber-800 mt-2">اختر الفرع الذي سُجّل فيه العميل.</p><a href="/admin/customers/add" class="inline-block mt-4 text-blue-600 underline">العودة</a></div></body></html>`,
        400
      )
    }
    
    // Check if national_id already exists within the same tenant
    if (national_id) {
      let checkQuery = `SELECT id, full_name FROM customers WHERE national_id = ?`
      let bindParams: any[] = [national_id]
      
      if (tenant_id) {
        checkQuery += ` AND tenant_id = ?`
        bindParams.push(tenant_id)
      }
      
      const existing = await c.env.DB.prepare(checkQuery).bind(...bindParams).first()
      
      if (existing) {
        if (inlineCustomerForm) {
          return c.json(
            {
              ok: false,
              code: 'DUPLICATE_NATIONAL_ID',
              message: `الرقم الوطني "${national_id}" مسجل مسبقاً في هذه الشركة لعميل آخر.`,
              hint: 'احذف القيمة من حقل (الرقم الوطني) أو أدخل رقماً مختلفاً. تحقق أيضاً من خاصية الحفظ التلقائي (Autofill) في المتصفح إن كنت قد أزلت القيمة ولا تزال تظهر هذه الرسالة.',
              details: {
                national_id,
                existing: { id: existing.id, full_name: existing.full_name },
              },
            },
            409
          )
        }
        return c.html(`
          <!DOCTYPE html>
          <html lang="ar" dir="rtl">
          <head>
            <meta charset="UTF-8">
            <meta name="viewport" content="width=device-width, initial-scale=1.0">
            <title>خطأ</title>
            <script src="https://cdn.tailwindcss.com"></script>
            <link href="https://cdn.jsdelivr.net/npm/@fortawesome/fontawesome-free@6.4.0/css/all.min.css" rel="stylesheet">
          </head>
          <body class="bg-gray-50">
            <div class="max-w-2xl mx-auto p-6 mt-20">
              <div class="bg-red-50 border-l-4 border-red-500 rounded-lg p-6 shadow-lg">
                <div class="flex items-center mb-4">
                  <i class="fas fa-exclamation-circle text-red-500 text-4xl ml-3"></i>
                  <div>
                    <h1 class="text-2xl font-bold text-red-800">رقم الهوية مكرر!</h1>
                    <p class="text-red-600 mt-1">لا يمكن إضافة عميل برقم هوية موجود مسبقاً</p>
                  </div>
                </div>
                <div class="bg-white rounded-lg p-4 mb-4">
                  <p class="text-gray-700"><strong>الرقم الوطني:</strong> ${national_id}</p>
                  <p class="text-gray-700"><strong>مسجل باسم:</strong> ${existing.full_name}</p>
                  <p class="text-gray-700"><strong>رقم العميل:</strong> #${existing.id}</p>
                </div>
                <div class="flex gap-3">
                  <a href="/admin/customers/add" class="bg-blue-600 hover:bg-blue-700 text-white px-6 py-3 rounded-lg font-bold transition-all">
                    <i class="fas fa-arrow-right ml-2"></i>
                    العودة للنموذج
                  </a>
                  <a href="/admin/customers/${existing.id}" class="bg-green-600 hover:bg-green-700 text-white px-6 py-3 rounded-lg font-bold transition-all">
                    <i class="fas fa-eye ml-2"></i>
                    عرض العميل الموجود
                  </a>
                  <a href="/admin/customers" class="bg-gray-600 hover:bg-gray-700 text-white px-6 py-3 rounded-lg font-bold transition-all">
                    <i class="fas fa-list ml-2"></i>
                    قائمة العملاء
                  </a>
                </div>
              </div>
            </div>
          </body>
          </html>
        `)
      }
    }
    
    // Check if phone already exists within the same tenant
    const phoneLocalPart = phone.slice(3)
    const phoneLegacy10 = `0${phoneLocalPart}`
    let phoneCheckQuery = `SELECT id, full_name FROM customers WHERE (phone = ? OR phone = ? OR phone = ?)`
    let phoneBindParams: any[] = [phone, phoneLocalPart, phoneLegacy10]
    
    if (tenant_id) {
      phoneCheckQuery += ` AND tenant_id = ?`
      phoneBindParams.push(tenant_id)
    }
    
    const existingPhone = await c.env.DB.prepare(phoneCheckQuery).bind(...phoneBindParams).first()
    
    if (existingPhone) {
      if (inlineCustomerForm) {
        return c.json(
          {
            ok: false,
            code: 'DUPLICATE_PHONE',
            message: 'يوجد عميل آخر بنفس رقم الهاتف في هذه الشركة.',
            details: {
              phone,
              existing: { id: existingPhone.id, full_name: existingPhone.full_name },
            },
          },
          409
        )
      }
      return c.html(`
        <!DOCTYPE html>
        <html lang="ar" dir="rtl">
        <head>
          <meta charset="UTF-8">
          <meta name="viewport" content="width=device-width, initial-scale=1.0">
          <title>خطأ</title>
          <script src="https://cdn.tailwindcss.com"></script>
          <link href="https://cdn.jsdelivr.net/npm/@fortawesome/fontawesome-free@6.4.0/css/all.min.css" rel="stylesheet">
        </head>
        <body class="bg-gray-50">
          <div class="max-w-2xl mx-auto p-6 mt-20">
            <div class="bg-yellow-50 border-l-4 border-yellow-500 rounded-lg p-6 shadow-lg">
              <div class="flex items-center mb-4">
                <i class="fas fa-exclamation-triangle text-yellow-500 text-4xl ml-3"></i>
                <div>
                  <h1 class="text-2xl font-bold text-yellow-800">رقم الهاتف مكرر!</h1>
                  <p class="text-yellow-600 mt-1">يوجد عميل آخر بنفس رقم الهاتف</p>
                </div>
              </div>
              <div class="bg-white rounded-lg p-4 mb-4">
                <p class="text-gray-700"><strong>رقم الهاتف:</strong> ${phone}</p>
                <p class="text-gray-700"><strong>مسجل باسم:</strong> ${existingPhone.full_name}</p>
                <p class="text-gray-700"><strong>رقم العميل:</strong> #${existingPhone.id}</p>
              </div>
              <div class="flex gap-3">
                <a href="/admin/customers/add" class="bg-blue-600 hover:bg-blue-700 text-white px-6 py-3 rounded-lg font-bold transition-all">
                  <i class="fas fa-arrow-right ml-2"></i>
                  العودة للنموذج
                </a>
                <a href="/admin/customers/${existingPhone.id}" class="bg-green-600 hover:bg-green-700 text-white px-6 py-3 rounded-lg font-bold transition-all">
                  <i class="fas fa-eye ml-2"></i>
                  عرض العميل الموجود
                </a>
              </div>
            </div>
          </div>
        </body>
        </html>
      `)
    }
    
    const insertBind = [
      full_name,
      phone,
      email,
      national_id,
      date_of_birth,
      dob_calendar_type === 'hijri' ? 'hijri' : 'gregorian',
      employer_name,
      job_type,
      job_title,
      job_type === 'military' ? military_rank : null,
      work_start_date,
      city,
      basic_salary,
      monthly_salary,
      tenant_id,
      notes,
      enrollment_source,
      enrollment_source_label,
      identity_attachment_url,
      signature_attachment_url,
      salary_profile_attachment_url,
      gosi_attachment_url,
      tax_exemption_attachment_url,
      additional_1_attachment_url,
      additional_2_attachment_url,
      additional_3_attachment_url,
      resolvedLocationId,
    ] as const
    let result: { meta?: { last_row_id?: number } }
    try {
      result = await c.env.DB.prepare(`
      INSERT INTO customers (
        full_name, phone, email, national_id, birthdate, dob_calendar_type,
        employer_name, job_type, job_title, military_rank, work_start_date, city,
        basic_salary, monthly_salary, tenant_id, notes, enrollment_source, enrollment_source_label,
        identity_attachment_url, signature_attachment_url, salary_profile_attachment_url, gosi_attachment_url, tax_exemption_attachment_url,
        additional_1_attachment_url, additional_2_attachment_url, additional_3_attachment_url,
        location_id,
        solutions_json
      )
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).bind(...insertBind, solutions_json).run() as { meta?: { last_row_id?: number } }
    } catch (e: unknown) {
      if (isMissingCustomerLocationIdColumnError(e)) {
        try {
          result = await c.env.DB.prepare(`
      INSERT INTO customers (
        full_name, phone, email, national_id, birthdate, dob_calendar_type,
        employer_name, job_type, job_title, military_rank, work_start_date, city,
        basic_salary, monthly_salary, tenant_id, notes, enrollment_source, enrollment_source_label,
        identity_attachment_url, signature_attachment_url, salary_profile_attachment_url, gosi_attachment_url, tax_exemption_attachment_url,
        additional_1_attachment_url, additional_2_attachment_url, additional_3_attachment_url,
        solutions_json
      )
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `)
            .bind(...insertBind.slice(0, -1), solutions_json)
            .run() as { meta?: { last_row_id?: number } }
        } catch (e2: unknown) {
          if (isMissingCustomerSolutionsColumnError(e2)) {
            try {
              result = await c.env.DB.prepare(`
          INSERT INTO customers (
            full_name, phone, email, national_id, birthdate, dob_calendar_type,
            employer_name, job_type, job_title, military_rank, work_start_date, city,
            basic_salary, monthly_salary, tenant_id, notes, enrollment_source, enrollment_source_label,
            identity_attachment_url, signature_attachment_url, salary_profile_attachment_url, gosi_attachment_url, tax_exemption_attachment_url,
            additional_1_attachment_url, additional_2_attachment_url, additional_3_attachment_url
          )
          VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `)
                .bind(...insertBind.slice(0, -1))
                .run() as { meta?: { last_row_id?: number } }
            } catch (innerError: unknown) {
              if (!isMissingCustomerAttachmentsColumnError(innerError)) throw innerError
              result = await c.env.DB.prepare(`
          INSERT INTO customers (full_name, phone, email, national_id, birthdate, dob_calendar_type, employer_name, job_type, job_title, military_rank, work_start_date, city, basic_salary, monthly_salary, tenant_id, notes)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `)
                .bind(...insertBind.slice(0, 16))
                .run() as { meta?: { last_row_id?: number } }
            }
          } else if (isMissingCustomerAttachmentsColumnError(e2)) {
            try {
              result = await c.env.DB.prepare(`
          INSERT INTO customers (full_name, phone, email, national_id, birthdate, dob_calendar_type, employer_name, job_type, job_title, military_rank, work_start_date, city, basic_salary, monthly_salary, tenant_id, notes, solutions_json)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `)
                .bind(...insertBind.slice(0, 16), solutions_json)
                .run() as { meta?: { last_row_id?: number } }
            } catch (innerError: unknown) {
              if (!isMissingCustomerSolutionsColumnError(innerError)) throw innerError
              result = await c.env.DB.prepare(`
          INSERT INTO customers (full_name, phone, email, national_id, birthdate, dob_calendar_type, employer_name, job_type, job_title, military_rank, work_start_date, city, basic_salary, monthly_salary, tenant_id, notes)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `)
                .bind(...insertBind.slice(0, 16))
                .run() as { meta?: { last_row_id?: number } }
            }
          } else {
            throw e2
          }
        }
      } else if (isMissingCustomerSolutionsColumnError(e)) {
        try {
          result = await c.env.DB.prepare(`
          INSERT INTO customers (
            full_name, phone, email, national_id, birthdate, dob_calendar_type,
            employer_name, job_type, job_title, military_rank, work_start_date, city,
            basic_salary, monthly_salary, tenant_id, notes, enrollment_source, enrollment_source_label,
            identity_attachment_url, signature_attachment_url, salary_profile_attachment_url, gosi_attachment_url, tax_exemption_attachment_url,
            additional_1_attachment_url, additional_2_attachment_url, additional_3_attachment_url,
            location_id
          )
          VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `)
            .bind(...insertBind)
            .run() as { meta?: { last_row_id?: number } }
        } catch (innerError: unknown) {
          if (isMissingCustomerLocationIdColumnError(innerError)) {
            try {
              result = await c.env.DB.prepare(`
          INSERT INTO customers (
            full_name, phone, email, national_id, birthdate, dob_calendar_type,
            employer_name, job_type, job_title, military_rank, work_start_date, city,
            basic_salary, monthly_salary, tenant_id, notes, enrollment_source, enrollment_source_label,
            identity_attachment_url, signature_attachment_url, salary_profile_attachment_url, gosi_attachment_url, tax_exemption_attachment_url,
            additional_1_attachment_url, additional_2_attachment_url, additional_3_attachment_url
          )
          VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `)
                .bind(...insertBind.slice(0, -1))
                .run() as { meta?: { last_row_id?: number } }
            } catch (inner2: unknown) {
              if (!isMissingCustomerAttachmentsColumnError(inner2)) throw inner2
              result = await c.env.DB.prepare(`
          INSERT INTO customers (full_name, phone, email, national_id, birthdate, dob_calendar_type, employer_name, job_type, job_title, military_rank, work_start_date, city, basic_salary, monthly_salary, tenant_id, notes)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `)
                .bind(...insertBind.slice(0, 16))
                .run() as { meta?: { last_row_id?: number } }
            }
          } else if (!isMissingCustomerAttachmentsColumnError(innerError)) throw innerError
          else {
            result = await c.env.DB.prepare(`
          INSERT INTO customers (full_name, phone, email, national_id, birthdate, dob_calendar_type, employer_name, job_type, job_title, military_rank, work_start_date, city, basic_salary, monthly_salary, tenant_id, notes)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `)
              .bind(...insertBind.slice(0, 16))
              .run() as { meta?: { last_row_id?: number } }
          }
        }
      } else if (isMissingCustomerAttachmentsColumnError(e)) {
        try {
          result = await c.env.DB.prepare(`
          INSERT INTO customers (full_name, phone, email, national_id, birthdate, dob_calendar_type, employer_name, job_type, job_title, military_rank, work_start_date, city, basic_salary, monthly_salary, tenant_id, notes, solutions_json)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `).bind(...insertBind.slice(0, 16), solutions_json).run() as { meta?: { last_row_id?: number } }
        } catch (innerError: unknown) {
          if (!isMissingCustomerSolutionsColumnError(innerError)) throw innerError
          result = await c.env.DB.prepare(`
          INSERT INTO customers (full_name, phone, email, national_id, birthdate, dob_calendar_type, employer_name, job_type, job_title, military_rank, work_start_date, city, basic_salary, monthly_salary, tenant_id, notes)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `).bind(...insertBind.slice(0, 16)).run() as { meta?: { last_row_id?: number } }
        }
      } else {
        throw e
      }
    }

    // Track creator + (for bank agents / eligible dual agents) self-assign as موظف التمويل.
    const createdCustomerId = Number(result?.meta?.last_row_id || 0)
    if (createdCustomerId) {
      await allocateTenantCustomerNumber(c.env.DB, createdCustomerId, tenant_id)
    }
    const normRoleAfterInsert = normalizeRoleId(userInfo.roleId)
    if (creatorUserId && createdCustomerId) {
      try {
        const uidNum = Number(creatorUserId)
        const selfAssignBankAgent =
          isBankAgentAssignableRole(normRoleAfterInsert) && uidNum > 0
        if (selfAssignBankAgent) {
          try {
            await c.env.DB
              .prepare(
                `UPDATE customers SET created_by = ?, assigned_bank_agent_id = ? WHERE id = ?`
              )
              .bind(uidNum, uidNum, createdCustomerId)
              .run()
            await syncFinancingRequestsBankAgentForCustomer(c.env.DB, createdCustomerId, uidNum)
          } catch (eCol: unknown) {
            const m = String((eCol as { message?: string })?.message || eCol || '')
            if (/no such column:\s*assigned_bank_agent_id/i.test(m)) {
              await c.env.DB
                .prepare(`UPDATE customers SET created_by = ? WHERE id = ?`)
                .bind(creatorUserId, createdCustomerId)
                .run()
            }
          }
        } else {
          await c.env.DB
            .prepare(`UPDATE customers SET created_by = ? WHERE id = ?`)
            .bind(creatorUserId, createdCustomerId)
            .run()
        }
      } catch (_) {
        /* columns may not exist in older DBs */
      }
    }
    if (createdCustomerId) {
      try {
        await c.env.DB.prepare(`UPDATE customers SET product_type = ? WHERE id = ?`).bind(product_type, createdCustomerId).run()
      } catch (_) {
        /* column may not exist until migration 0071 is applied */
      }
      try {
        await c.env.DB.prepare(`UPDATE customers SET property_type = ? WHERE id = ?`).bind(property_type, createdCustomerId).run()
      } catch (_) {
        /* column may not exist until migration 0072 is applied */
      }
      try {
        await c.env.DB.prepare(`UPDATE customers SET property_owner = ?, real_estate_office = ? WHERE id = ?`).bind(property_owner, real_estate_office, createdCustomerId).run()
      } catch (_) {
        /* columns may not exist until migration 0075 is applied */
      }
      if (salary_bank_id != null) {
        try {
          await c.env.DB.prepare(`UPDATE customers SET salary_bank_id = ? WHERE id = ?`).bind(salary_bank_id, createdCustomerId).run()
        } catch (_) {
          /* column may not exist until migration 0138 is applied */
        }
      }
      if (customerAttachmentsFromForm.length > 0) {
        await saveCustomerAttachmentsJson(c.env.DB, createdCustomerId, customerAttachmentsFromForm)
      }
    }
    const newId = result.meta?.last_row_id
    const obligationsJson = formData.get('obligations_json') as string | null
    if (newId && obligationsJson) {
      try {
        const obligations = JSON.parse(obligationsJson) as Array<{ obligation_type?: string; total_amount?: number; monthly_installment?: number; due_date?: string | null }>
        if (Array.isArray(obligations) && obligations.length > 0) {
          let monthlySum = 0
          for (const o of obligations) {
            const type = (o.obligation_type ?? '') as string
            const total = Number(o.total_amount) || 0
            const monthly = Number(o.monthly_installment) || 0
            const due = o.due_date || null
            monthlySum += monthly
            await c.env.DB.prepare('INSERT INTO customer_obligations (customer_id, obligation_type, total_amount, monthly_installment, due_date, tenant_id) VALUES (?, ?, ?, ?, ?, ?)').bind(newId, type, total, monthly, due, tenant_id).run()
          }
          await c.env.DB.prepare('UPDATE customers SET monthly_obligations = ? WHERE id = ?').bind(monthlySum, newId).run()
        }
      } catch (_) {}
    }
    // Employees (role 4 / dual agent role 6): auto-assign the new customer to themselves.
    // Role 6 list scope uses customer_assignments — created_by alone does not grant visibility.
    const creatorRole = normalizeRoleId(userInfo.roleId)
    const assignCustomerId = createdCustomerId || Number(newId || 0)
    if (assignCustomerId > 0 && userInfo.userId && isEmployeeAssignableRole(creatorRole)) {
      try {
        await assignNewCustomerToEmployee(
          c.env.DB,
          assignCustomerId,
          Number(userInfo.userId),
          Number(userInfo.userId),
          ''
        )
      } catch (e) {
        console.error('Auto-assign new customer to employee (role 4/6) failed:', e)
      }
    }
    // Role 2/1: optional bank agent from form (role 5 self-assign is handled with created_by above).
    const customerIdForAgent = createdCustomerId || Number(newId || 0)
    if (customerIdForAgent > 0) {
      const normRolePick = normalizeRoleId(userInfo.roleId)
      if ((normRolePick === 2 || normRolePick === 1) && tenant_id) {
        const rawAgentField = formData.get('assigned_bank_agent_id')
        if (rawAgentField) {
          const agentId = Number(rawAgentField)
          if (
            agentId > 0 &&
            (await isActiveBankAgentForTenant(c.env.DB, agentId, tenant_id))
          ) {
            const persisted = await setCustomerAssignedBankAgent(
              c.env.DB,
              customerIdForAgent,
              agentId
            )
            if (persisted.missingColumn) {
              console.error(
                '[customer create] customers.assigned_bank_agent_id column missing — apply migration 0073 on D1'
              )
            } else if (persisted.ok) {
              await syncFinancingRequestsBankAgentForCustomer(
                c.env.DB,
                customerIdForAgent,
                agentId
              )
            }
          }
        }
      }
    }
    // Carry over rating from followup task if registration came from my-tasks flow
    const taskIdFromForm = Number.parseInt(String(formData.get('task_id') ?? ''), 10)
    if (Number.isFinite(taskIdFromForm) && taskIdFromForm > 0 && createdCustomerId && tenant_id) {
      try {
        const taskRow = await c.env.DB.prepare(
          `SELECT rating, rating_note FROM company_contact_followup_tasks WHERE id = ? AND tenant_id = ? LIMIT 1`
        ).bind(taskIdFromForm, tenant_id).first<{ rating: number | null; rating_note: string | null }>()
        if (taskRow?.rating && taskRow.rating >= 1 && taskRow.rating <= 5) {
          await c.env.DB.prepare(
            `INSERT INTO customer_reviews (customer_id, customer_name, rating, note, user_id, tenant_id) VALUES (?, ?, ?, ?, ?, ?)`
          ).bind(createdCustomerId, full_name, taskRow.rating, taskRow.rating_note || null, userInfo.userId || null, tenant_id).run()
        }
      } catch (_) { /* don't fail customer creation if rating carry-over fails */ }
      try {
        await c.env.DB.prepare(
          `UPDATE company_contact_followup_tasks SET status = 'completed' WHERE id = ? AND tenant_id = ?`
        ).bind(taskIdFromForm, tenant_id).run()
      } catch (_) { /* don't fail customer creation if task completion fails */ }
    }

    if (inlineCustomerForm) {
      return c.json({
        ok: true,
        redirect: '/admin/customers',
        id: newId || null,
      })
    }
    return c.redirect('/admin/customers')
  } catch (error: any) {
    if (inlineCustomerForm) {
      return c.json(
        {
          ok: false,
          code: 'SERVER_ERROR',
          message: error?.message || 'لم نتمكن من إضافة العميل.',
        },
        500
      )
    }
    return c.html(`
      <!DOCTYPE html>
      <html lang="ar" dir="rtl">
      <head>
        <meta charset="UTF-8">
        <meta name="viewport" content="width=device-width, initial-scale=1.0">
        <title>خطأ</title>
        <script src="https://cdn.tailwindcss.com"></script>
        <link href="https://cdn.jsdelivr.net/npm/@fortawesome/fontawesome-free@6.4.0/css/all.min.css" rel="stylesheet">
      </head>
      <body class="bg-gray-50">
        <div class="max-w-2xl mx-auto p-6 mt-20">
          <div class="bg-red-50 border-l-4 border-red-500 rounded-lg p-6 shadow-lg">
            <div class="flex items-center mb-4">
              <i class="fas fa-times-circle text-red-500 text-4xl ml-3"></i>
              <div>
                <h1 class="text-2xl font-bold text-red-800">حدث خطأ!</h1>
                <p class="text-red-600 mt-1">لم نتمكن من إضافة العميل</p>
              </div>
            </div>
            <div class="bg-white rounded-lg p-4 mb-4">
              <p class="text-gray-700 font-mono text-sm">${error.message}</p>
            </div>
            <a href="/admin/customers/add" class="bg-blue-600 hover:bg-blue-700 text-white px-6 py-3 rounded-lg font-bold transition-all inline-block">
              <i class="fas fa-arrow-right ml-2"></i>
              العودة للنموذج
            </a>
          </div>
        </div>
      </body>
      </html>
    `)
  }
})

// Update customer
app.post('/api/customers/:id', async (c) => {
  try {
    const id = c.req.param('id')
    const userInfo = await getUserInfo(c)
    if (!userInfo.userId || !userInfo.roleId) {
      return c.redirect('/login')
    }
    const existingCustomer = await c.env.DB.prepare(
      'SELECT id, tenant_id, enrollment_source, enrollment_source_label FROM customers WHERE id = ?'
    )
      .bind(id)
      .first() as {
      id: number
      tenant_id: number | null
      enrollment_source?: string | null
      enrollment_source_label?: string | null
    } | null
    if (!existingCustomer) {
      return c.html('<!DOCTYPE html><html lang="ar" dir="rtl"><head><meta charset="UTF-8"><title>غير موجود</title></head><body class="p-8"><h1>العميل غير موجود</h1></body></html>', 404)
    }
    if (!(await canUserAccessCustomer(c.env.DB, userInfo, existingCustomer))) {
      return c.html('<!DOCTYPE html><html lang="ar" dir="rtl"><head><meta charset="UTF-8"><title>غير مصرح</title></head><body class="p-8"><h1>غير مصرح بتعديل هذا العميل</h1></body></html>', 403)
    }
    const formData = await c.req.formData()
    if (String(formData.get('attachments_only') || '') === '1') {
      const customerAttachmentsFromForm = normalizeCustomerAttachmentsJson(
        formData.get('attachments_json') as string | null
      )
      await saveCustomerAttachmentsJson(c.env.DB, id, customerAttachmentsFromForm)
      return c.json({ success: true })
    }
    const full_name = formData.get('full_name') as string
    const rawPhone = formData.get('phone') as string
    const normalizedPhoneResult = normalizeCustomerPhoneForStorage(rawPhone)
    if (!normalizedPhoneResult.normalized) {
      return c.html(`
        <!DOCTYPE html>
        <html lang="ar" dir="rtl">
        <head>
          <meta charset="UTF-8">
          <meta name="viewport" content="width=device-width, initial-scale=1.0">
          <title>تنسيق رقم الجوال غير صحيح</title>
          <script src="https://cdn.tailwindcss.com"></script>
          <link href="https://cdn.jsdelivr.net/npm/@fortawesome/fontawesome-free@6.4.0/css/all.min.css" rel="stylesheet">
        </head>
        <body class="bg-gray-50">
          <div class="max-w-2xl mx-auto p-6 mt-20">
            <div class="bg-amber-50 border-r-4 border-amber-500 rounded-lg p-6 shadow-lg">
              <div class="flex items-center mb-3">
                <i class="fas fa-phone-slash text-amber-600 text-3xl ml-3"></i>
                <h1 class="text-2xl font-bold text-amber-800">تنسيق رقم الجوال غير صحيح</h1>
              </div>
              <p class="text-amber-700 mb-3">${normalizedPhoneResult.error || 'يرجى مراجعة رقم الجوال'}</p>
              <div class="bg-white rounded-lg p-3 text-sm text-gray-700 mb-4">
                <p><strong>الطريقة الصحيحة:</strong> أدخل فقط 9 أرقام تبدأ بـ <span dir="ltr">5</span>.</p>
                <p><strong>الصيغة:</strong> <span dir="ltr">5XXXXXXXX</span> (وسيتم حفظه تلقائياً كـ <span dir="ltr">9665XXXXXXXX</span>).</p>
              </div>
              <a href="/admin/customers/${id}/edit" class="inline-flex items-center bg-blue-600 hover:bg-blue-700 text-white px-5 py-2 rounded-lg font-bold transition-all">
                <i class="fas fa-arrow-right ml-2"></i>
                العودة للتعديل
              </a>
            </div>
          </div>
        </body>
        </html>
      `, 400)
    }
    const phone = normalizedPhoneResult.normalized
    const email = formData.get('email') as string || null
    const national_id_raw = formData.get('national_id') as string | null
    const national_id =
      national_id_raw != null && String(national_id_raw).trim()
        ? String(national_id_raw).trim()
        : null
    const date_of_birth = formData.get('date_of_birth') as string || null
    const dob_calendar_type = (formData.get('dob_calendar_type') as string) || 'gregorian'
    const employer_name = formData.get('employer_name') as string || null
    const job_type = normalizeCustomerJobType(formData.get('job_type'))
    const job_title = formData.get('job_title') as string || null
    const military_rank = formData.get('military_rank') as string || null
    const work_start_date = formData.get('work_start_date') as string || null
    const city = formData.get('city') as string || null
    const product_type = normalizeCustomerProductType(formData.get('product_type'))
    const property_type = normalizeCustomerPropertyType(formData.get('property_type'))
    const property_owner = (formData.get('property_owner') as string)?.trim() || null
    const real_estate_office = (formData.get('real_estate_office') as string)?.trim() || null
    const basic_salary = formData.get('basic_salary') ? parseFloat(formData.get('basic_salary') as string) : null
    const salary_bank_id_raw = Number.parseInt(String(formData.get('salary_bank_id') ?? ''), 10)
    const salary_bank_id = Number.isFinite(salary_bank_id_raw) && salary_bank_id_raw > 0 ? salary_bank_id_raw : null
    const monthly_salary = parseFloat(formData.get('monthly_salary') as string || '0')
    const notes = (formData.get('notes') as string)?.trim() || null
    const solutions_json = normalizeCustomerSolutionsJson(formData.get('solutions_json') as string | null)
    const customerAttachmentsFromForm = normalizeCustomerAttachmentsJson(
      formData.get('attachments_json') as string | null
    )

    // Attachment URLs (legacy 8-doc model; dynamic attachments_json preferred)
    const identity_attachment_url =
      (formData.get('identity_attachment_url') as string | null)?.trim() ||
      (formData.get('id_attachment_url') as string | null)?.trim() ||
      null
    const signature_attachment_url =
      (formData.get('signature_attachment_url') as string | null)?.trim() ||
      (formData.get('bank_statement_attachment_url') as string | null)?.trim() ||
      null
    const salary_profile_attachment_url =
      (formData.get('salary_profile_attachment_url') as string | null)?.trim() ||
      (formData.get('salary_attachment_url') as string | null)?.trim() ||
      null
    const gosi_attachment_url = (formData.get('gosi_attachment_url') as string | null)?.trim() || null
    const tax_exemption_attachment_url = (formData.get('tax_exemption_attachment_url') as string | null)?.trim() || null
    const additional_1_attachment_url =
      (formData.get('additional_1_attachment_url') as string | null)?.trim() ||
      (formData.get('additional_attachment_url') as string | null)?.trim() ||
      null
    const additional_2_attachment_url = (formData.get('additional_2_attachment_url') as string | null)?.trim() || null
    const additional_3_attachment_url = (formData.get('additional_3_attachment_url') as string | null)?.trim() || null

    let enrollmentLocationUpdate: number | null | undefined = undefined
    const tenantIdForLoc =
      existingCustomer.tenant_id != null ? Number(existingCustomer.tenant_id) : NaN
    if (Number.isFinite(tenantIdForLoc) && tenantIdForLoc > 0) {
      const activeLocCountRow = await c.env.DB.prepare(
        `SELECT COUNT(*) as n FROM tenant_locations WHERE tenant_id = ? AND is_active = 1`
      )
        .bind(tenantIdForLoc)
        .first<{ n: number }>()
      const activeLocationCount = Number(activeLocCountRow?.n ?? 0)
      if (activeLocationCount > 0) {
        const locationIdRaw = formData.get('location_id')
        if (locationIdRaw == null || String(locationIdRaw).trim() === '') {
          return c.html(
            `<!DOCTYPE html><html lang="ar" dir="rtl"><head><meta charset="UTF-8"><title>خطأ</title><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-gray-50 p-8"><div class="max-w-lg mx-auto bg-amber-50 border border-amber-200 p-6 rounded-lg"><h1 class="text-xl font-bold text-amber-900">موقع التسجيل مطلوب</h1><p class="text-amber-800 mt-2">اختر الفرع الذي سُجّل فيه العميل.</p><a href="/admin/customers/${id}/edit" class="inline-block mt-4 text-blue-600 underline">العودة للتعديل</a></div></body></html>`,
            400
          )
        }
        const lid = Number.parseInt(String(locationIdRaw), 10)
        if (!Number.isFinite(lid) || lid <= 0) {
          return c.html(
            `<!DOCTYPE html><html lang="ar" dir="rtl"><head><meta charset="UTF-8"><title>خطأ</title><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-gray-50 p-8"><div class="max-w-lg mx-auto bg-amber-50 border border-amber-200 p-6 rounded-lg"><h1 class="text-xl font-bold text-amber-900">موقع غير صالح</h1><p class="text-amber-800 mt-2">يرجى اختيار موقع تسجيل صحيح.</p><a href="/admin/customers/${id}/edit" class="inline-block mt-4 text-blue-600 underline">العودة للتعديل</a></div></body></html>`,
            400
          )
        }
        const locOk = await c.env.DB.prepare(
          `SELECT id FROM tenant_locations WHERE id = ? AND tenant_id = ? AND is_active = 1 LIMIT 1`
        )
          .bind(lid, tenantIdForLoc)
          .first<{ id: number }>()
        if (!locOk) {
          return c.html(
            `<!DOCTYPE html><html lang="ar" dir="rtl"><head><meta charset="UTF-8"><title>خطأ</title><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-gray-50 p-8"><div class="max-w-lg mx-auto bg-red-50 border border-red-200 p-6 rounded-lg"><h1 class="text-xl font-bold text-red-900">الموقع لا يتبع هذه الشركة</h1><a href="/admin/customers/${id}/edit" class="inline-block mt-4 text-blue-600 underline">العودة للتعديل</a></div></body></html>`,
            400
          )
        }
        enrollmentLocationUpdate = lid
      }
    }
    
    const updateBind = [
      full_name,
      phone,
      email,
      national_id,
      date_of_birth,
      dob_calendar_type === 'hijri' ? 'hijri' : 'gregorian',
      employer_name,
      job_type,
      job_title,
      job_type === 'military' ? military_rank : null,
      work_start_date,
      city,
      basic_salary,
      monthly_salary,
      notes,
      identity_attachment_url,
      signature_attachment_url,
      salary_profile_attachment_url,
      gosi_attachment_url,
      tax_exemption_attachment_url,
      additional_1_attachment_url,
      additional_2_attachment_url,
      additional_3_attachment_url
    ] as const
    try {
      await c.env.DB.prepare(`
      UPDATE customers 
      SET full_name = ?, phone = ?, email = ?, national_id = ?, birthdate = ?, dob_calendar_type = ?,
          employer_name = ?, job_type = ?, job_title = ?, military_rank = ?, work_start_date = ?, city = ?, basic_salary = ?, monthly_salary = ?, notes = ?,
          identity_attachment_url = ?, signature_attachment_url = ?, salary_profile_attachment_url = ?, gosi_attachment_url = ?, tax_exemption_attachment_url = ?,
          additional_1_attachment_url = ?, additional_2_attachment_url = ?, additional_3_attachment_url = ?,
          solutions_json = ?
      WHERE id = ?
    `).bind(...updateBind, solutions_json, id).run()
    } catch (e: unknown) {
      if (isMissingCustomerSolutionsColumnError(e)) {
        try {
          await c.env.DB.prepare(`
          UPDATE customers 
          SET full_name = ?, phone = ?, email = ?, national_id = ?, birthdate = ?, dob_calendar_type = ?,
              employer_name = ?, job_type = ?, job_title = ?, military_rank = ?, work_start_date = ?, city = ?, basic_salary = ?, monthly_salary = ?, notes = ?,
              identity_attachment_url = ?, signature_attachment_url = ?, salary_profile_attachment_url = ?, gosi_attachment_url = ?, tax_exemption_attachment_url = ?,
              additional_1_attachment_url = ?, additional_2_attachment_url = ?, additional_3_attachment_url = ?
          WHERE id = ?
        `).bind(...updateBind, id).run()
        } catch (innerError: unknown) {
          if (!isMissingCustomerAttachmentsColumnError(innerError)) throw innerError
          await c.env.DB.prepare(`
          UPDATE customers 
          SET full_name = ?, phone = ?, email = ?, national_id = ?, birthdate = ?, dob_calendar_type = ?,
              employer_name = ?, job_type = ?, job_title = ?, military_rank = ?, work_start_date = ?, city = ?, basic_salary = ?, monthly_salary = ?, notes = ?
          WHERE id = ?
        `).bind(...updateBind.slice(0, 15), id).run()
        }
      } else if (isMissingCustomerAttachmentsColumnError(e)) {
        try {
          await c.env.DB.prepare(`
          UPDATE customers 
          SET full_name = ?, phone = ?, email = ?, national_id = ?, birthdate = ?, dob_calendar_type = ?,
              employer_name = ?, job_type = ?, job_title = ?, military_rank = ?, work_start_date = ?, city = ?, basic_salary = ?, monthly_salary = ?, notes = ?, solutions_json = ?
          WHERE id = ?
        `).bind(...updateBind.slice(0, 15), solutions_json, id).run()
        } catch (innerError: unknown) {
          if (!isMissingCustomerSolutionsColumnError(innerError)) throw innerError
          await c.env.DB.prepare(`
          UPDATE customers 
          SET full_name = ?, phone = ?, email = ?, national_id = ?, birthdate = ?, dob_calendar_type = ?,
              employer_name = ?, job_type = ?, job_title = ?, military_rank = ?, work_start_date = ?, city = ?, basic_salary = ?, monthly_salary = ?, notes = ?
          WHERE id = ?
        `).bind(...updateBind.slice(0, 15), id).run()
        }
      } else {
        throw e
      }
    }
    if (enrollmentLocationUpdate !== undefined) {
      try {
        await c.env.DB.prepare('UPDATE customers SET location_id = ? WHERE id = ?').bind(enrollmentLocationUpdate, id).run()
      } catch (e: unknown) {
        if (!isMissingCustomerLocationIdColumnError(e)) throw e
      }
      await syncFinancingRequestsLocationForCustomer(c.env.DB, id, enrollmentLocationUpdate)
    }
    try {
      await c.env.DB.prepare(`UPDATE customers SET product_type = ? WHERE id = ?`).bind(product_type, id).run()
    } catch (_) {
      /* column may not exist until migration 0071 is applied */
    }
    try {
      await c.env.DB.prepare(`UPDATE customers SET property_type = ? WHERE id = ?`).bind(property_type, id).run()
    } catch (_) {
      /* column may not exist until migration 0072 is applied */
    }
    try {
      await c.env.DB.prepare(`UPDATE customers SET property_owner = ?, real_estate_office = ? WHERE id = ?`).bind(property_owner, real_estate_office, id).run()
    } catch (_) {
      /* columns may not exist until migration 0075 is applied */
    }
    try {
      await c.env.DB.prepare(`UPDATE customers SET salary_bank_id = ? WHERE id = ?`).bind(salary_bank_id, id).run()
    } catch (_) {
      /* column may not exist until migration 0138 is applied */
    }
    if (formData.get('attachments_json') != null) {
      await saveCustomerAttachmentsJson(c.env.DB, id, customerAttachmentsFromForm)
    }
    // Role 2/1: reassign or clear the bank agent on a customer (single source of truth).
    const editorRole = normalizeRoleId(userInfo.roleId)
    if (editorRole === 2 || editorRole === 1) {
      const rawAgentField = formData.get('assigned_bank_agent_id')
      if (rawAgentField !== null) {
        const custTenantId =
          existingCustomer.tenant_id != null ? Number(existingCustomer.tenant_id) : null

        let skipBankAgentPersist = false
        const parsedRaw =
          rawAgentField != null ? String(rawAgentField).trim() : ''

        /** null = explicitly clear dropdown; omit invalid numbers (do not wipe column). */
        let agentToStore: number | null = null

        if (parsedRaw === '') {
          agentToStore = null
        } else {
          const n = Number(parsedRaw)
          if (Number.isFinite(n) && n > 0) {
            const pick = Math.floor(n)
            if (await isActiveBankAgentForTenant(c.env.DB, pick, custTenantId)) {
              agentToStore = pick
            } else {
              console.warn(
                '[customer edit] bank agent rejected — keeping existing assignment',
                pick,
                custTenantId
              )
              skipBankAgentPersist = true
            }
          } else {
            skipBankAgentPersist = true
          }
        }

        if (!skipBankAgentPersist) {
          const persisted = await setCustomerAssignedBankAgent(
            c.env.DB,
            Number(id),
            agentToStore
          )
          if (persisted.missingColumn) {
            console.error(
              '[customer edit] customers.assigned_bank_agent_id column missing — apply migration 0073 on D1'
            )
          } else if (persisted.ok) {
            await syncFinancingRequestsBankAgentForCustomer(c.env.DB, Number(id), agentToStore)
          }
        }
      }
    }
    const obligationsJson = formData.get('obligations_json') as string | null
    if (obligationsJson) {
      try {
        const customerRow = await c.env.DB.prepare('SELECT tenant_id FROM customers WHERE id = ?').bind(id).first() as { tenant_id: number } | null
        const tenant_id = customerRow?.tenant_id ?? null
        await c.env.DB.prepare('DELETE FROM customer_obligations WHERE customer_id = ?').bind(id).run()
        const obligations = JSON.parse(obligationsJson) as Array<{ obligation_type?: string; total_amount?: number; monthly_installment?: number; due_date?: string | null }>
        if (Array.isArray(obligations) && obligations.length > 0) {
          let monthlySum = 0
          for (const o of obligations) {
            const type = (o.obligation_type ?? '') as string
            const total = Number(o.total_amount) || 0
            const monthly = Number(o.monthly_installment) || 0
            const due = o.due_date || null
            monthlySum += monthly
            await c.env.DB.prepare('INSERT INTO customer_obligations (customer_id, obligation_type, total_amount, monthly_installment, due_date, tenant_id) VALUES (?, ?, ?, ?, ?, ?)').bind(id, type, total, monthly, due, tenant_id).run()
          }
          await c.env.DB.prepare('UPDATE customers SET monthly_obligations = ? WHERE id = ?').bind(monthlySum, id).run()
        } else {
          await c.env.DB.prepare('UPDATE customers SET monthly_obligations = 0 WHERE id = ?').bind(id).run()
        }
      } catch (_) {}
    }
    await syncAttachmentsForCustomer(c.env.DB, id, {
      identity_attachment_url,
      signature_attachment_url,
      salary_profile_attachment_url,
      gosi_attachment_url,
      tax_exemption_attachment_url,
      additional_1_attachment_url,
      additional_2_attachment_url,
      additional_3_attachment_url
    })
    const prevEnrollmentSrc = String(existingCustomer?.enrollment_source ?? '').trim()
    const enrollmentSourceLocked =
      prevEnrollmentSrc === 'calculator' || prevEnrollmentSrc === 'affiliate'
    if (!enrollmentSourceLocked) {
      const manualSource = String(formData.get('manual_enrollment_source') ?? '').trim().slice(0, 200)
      const newSrc = manualSource ? 'manual' : null
      const newLab = manualSource ? manualSource : null
      try {
        await c.env.DB.prepare(
          `UPDATE customers SET enrollment_source = ?, enrollment_source_label = ? WHERE id = ?`
        )
          .bind(newSrc, newLab, id)
          .run()
      } catch (_) {
        /* columns may be missing on very old DBs */
      }
    }
    return c.redirect('/admin/customers')
  } catch (error: any) {
    return c.json({ success: false, error: error.message }, 500)
  }
})

// Calculator: list customers for tenant (dropdown; tenant_slug required)
app.get('/api/calculator/customers', async (c) => {
  try {
    const tenant_slug = c.req.query('tenant_slug') as string | undefined
    if (!tenant_slug) {
      return c.json({ success: false, error: 'tenant_slug required' }, 400)
    }
    const t = await c.env.DB.prepare('SELECT id FROM tenants WHERE slug = ?').bind(tenant_slug).first() as { id: number } | null
    if (!t) return c.json({ success: false, customers: [] })
    const result = await c.env.DB.prepare(
      'SELECT id, full_name, phone, national_id, basic_salary, monthly_salary FROM customers WHERE tenant_id = ? ORDER BY full_name'
    ).bind(t.id).all()
    const customers = (result.results || []) as Array<{ id: number; full_name: string; phone?: string; national_id?: string; basic_salary?: number; monthly_salary?: number }>
    return c.json({ success: true, customers })
  } catch (error: any) {
    return c.json({ success: false, error: error.message }, 500)
  }
})

// Calculator: get customer by id with obligations (tenant check; for dropdown selection)
app.get('/api/calculator/customer-by-id', async (c) => {
  try {
    const customer_id = c.req.query('customer_id') as string | undefined
    const tenant_slug = c.req.query('tenant_slug') as string | undefined
    if (!customer_id || !tenant_slug) {
      return c.json({ success: false, error: 'customer_id and tenant_slug required' }, 400)
    }
    const t = await c.env.DB.prepare('SELECT id FROM tenants WHERE slug = ?').bind(tenant_slug).first() as { id: number } | null
    if (!t) return c.json({ success: false, customer: null, obligations: [], solutions: [] })
    let customer: Record<string, unknown> | null = null
    try {
      customer = (await c.env.DB.prepare(
        'SELECT id, full_name, phone, national_id, basic_salary, monthly_salary, monthly_obligations, solutions_json FROM customers WHERE id = ? AND tenant_id = ?'
      ).bind(customer_id, t.id).first()) as Record<string, unknown> | null
    } catch (e: unknown) {
      if (!isMissingCustomerSolutionsColumnError(e)) throw e
      customer = (await c.env.DB.prepare(
        'SELECT id, full_name, phone, national_id, basic_salary, monthly_salary, monthly_obligations FROM customers WHERE id = ? AND tenant_id = ?'
      ).bind(customer_id, t.id).first()) as Record<string, unknown> | null
    }
    if (!customer) return c.json({ success: false, customer: null, obligations: [], solutions: [] })
    const obligationsResult = await c.env.DB.prepare('SELECT id, obligation_type, total_amount, monthly_installment, due_date FROM customer_obligations WHERE customer_id = ? ORDER BY id').bind(customer_id).all()
    const obligations = (obligationsResult.results || []) as Array<{ id?: number; obligation_type?: string; total_amount?: number; monthly_installment?: number; due_date?: string | null }>
    let solutions: Array<{ note: string }> = []
    try {
      const sj = (customer as { solutions_json?: string | null }).solutions_json
      if (sj) {
        const parsed = JSON.parse(sj)
        if (Array.isArray(parsed)) {
          solutions = parsed.map((item: unknown) => ({
            note: typeof item === 'string' ? item : String((item as { note?: string })?.note ?? '')
          }))
        }
      }
    } catch (_) {}
    return c.json({ success: true, customer, obligations, solutions })
  } catch (error: any) {
    return c.json({ success: false, error: error.message }, 500)
  }
})

// Calculator: lookup customer by national_id or phone (optional tenant_slug for tenant calculator)
app.get('/api/calculator/customer-by-identifier', async (c) => {
  try {
    const national_id = c.req.query('national_id') as string | undefined
    const phone = c.req.query('phone') as string | undefined
    const tenant_slug = c.req.query('tenant_slug') as string | undefined
    if (!national_id && !phone) {
      return c.json({ success: false, error: 'Provide national_id or phone' }, 400)
    }
    let tenant_id: number | null = null
    if (tenant_slug) {
      const t = await c.env.DB.prepare('SELECT id FROM tenants WHERE slug = ?').bind(tenant_slug).first() as { id: number } | null
      tenant_id = t?.id ?? null
    }
    let customer: any = null
    if (tenant_id != null) {
      customer = await c.env.DB.prepare(
        'SELECT id, full_name, phone, national_id, basic_salary, monthly_salary, monthly_obligations FROM customers WHERE tenant_id = ? AND (national_id = ? OR phone = ?) LIMIT 1'
      ).bind(tenant_id, national_id || '', phone || '').first()
    } else {
      customer = await c.env.DB.prepare(
        'SELECT id, full_name, phone, national_id, basic_salary, monthly_salary, monthly_obligations FROM customers WHERE national_id = ? OR phone = ? LIMIT 1'
      ).bind(national_id || '', phone || '').first()
    }
    if (!customer) {
      return c.json({ success: false, customer: null, obligations: [] })
    }
    const obligationsResult = await c.env.DB.prepare('SELECT id, obligation_type, total_amount, monthly_installment, due_date FROM customer_obligations WHERE customer_id = ? ORDER BY id').bind((customer as any).id).all()
    const obligations = (obligationsResult.results || []) as Array<{ id?: number; obligation_type?: string; total_amount?: number; monthly_installment?: number; due_date?: string | null }>
    return c.json({ success: true, customer, obligations })
  } catch (error: any) {
    return c.json({ success: false, error: error.message }, 500)
  }
})

// Get obligations for a customer (auth + tenant check)
app.get('/api/customers/:id/obligations', async (c) => {
  try {
    const userInfo = await getUserInfo(c)
    if (!userInfo.userId || !userInfo.roleId) return c.json({ success: false, error: 'Unauthorized' }, 401)
    const id = c.req.param('id')
    const customer = await c.env.DB.prepare('SELECT id, tenant_id FROM customers WHERE id = ?').bind(id).first() as { id: number; tenant_id: number } | null
    if (!customer) return c.json({ success: false, error: 'Not found' }, 404)
    if (!(await canUserAccessCustomer(c.env.DB, userInfo, customer))) return c.json({ success: false, error: 'Forbidden' }, 403)
    const obligationsResult = await c.env.DB.prepare('SELECT id, obligation_type, total_amount, monthly_installment, due_date FROM customer_obligations WHERE customer_id = ? ORDER BY id').bind(id).all()
    const obligations = obligationsResult.results || []
    return c.json({ success: true, obligations })
  } catch (error: any) {
    return c.json({ success: false, error: error.message }, 500)
  }
})

// Replace obligations for a customer (auth + tenant check)
app.post('/api/customers/:id/obligations', async (c) => {
  try {
    const userInfo = await getUserInfo(c)
    if (!userInfo.userId || !userInfo.roleId) return c.json({ success: false, error: 'Unauthorized' }, 401)
    const id = c.req.param('id')
    const customer = await c.env.DB.prepare('SELECT id, tenant_id FROM customers WHERE id = ?').bind(id).first() as { id: number; tenant_id: number } | null
    if (!customer) return c.json({ success: false, error: 'Not found' }, 404)
    if (!(await canUserAccessCustomer(c.env.DB, userInfo, customer))) return c.json({ success: false, error: 'Forbidden' }, 403)
    const body = await c.req.json() as { obligations?: Array<{ obligation_type?: string; total_amount?: number; monthly_installment?: number; due_date?: string | null }> }
    const obligations = Array.isArray(body?.obligations) ? body.obligations : []
    await c.env.DB.prepare('DELETE FROM customer_obligations WHERE customer_id = ?').bind(id).run()
    let monthlySum = 0
    for (const o of obligations) {
      const type = (o.obligation_type ?? '') as string
      const total = Number(o.total_amount) || 0
      const monthly = Number(o.monthly_installment) || 0
      const due = o.due_date || null
      monthlySum += monthly
      await c.env.DB.prepare('INSERT INTO customer_obligations (customer_id, obligation_type, total_amount, monthly_installment, due_date, tenant_id) VALUES (?, ?, ?, ?, ?, ?)').bind(id, type, total, monthly, due, customer.tenant_id).run()
    }
    await c.env.DB.prepare('UPDATE customers SET monthly_obligations = ? WHERE id = ?').bind(monthlySum, id).run()
    return c.json({ success: true })
  } catch (error: any) {
    return c.json({ success: false, error: error.message }, 500)
  }
})

// FINANCING REQUESTS APIs

// Get all financing requests
app.get('/api/financing-requests', async (c) => {
  try {
    const userInfo = await getUserInfo(c)
    if (!userInfo.userId || !userInfo.roleId) {
      return c.json({ success: false, error: 'غير مصرح' }, 401)
    }
    
    let query = `
      SELECT
        f.*,
        c.full_name as customer_name,
        c.phone as customer_phone,
        c.national_id,
        c.attachments_json,
        c.identity_attachment_url,
        c.signature_attachment_url,
        c.salary_profile_attachment_url,
        c.gosi_attachment_url,
        c.tax_exemption_attachment_url,
        c.additional_1_attachment_url,
        c.additional_2_attachment_url,
        c.additional_3_attachment_url,
        c.employer_name,
        c.job_title,
        b.bank_name as selected_bank_name,
        ft.type_name as financing_type_name,
        ca.employee_id as assigned_employee_id,
        u.full_name as assigned_employee_name,
        COALESCE(NULLIF(TRIM(ba.full_name),''), ba.username) as assigned_bank_agent_name,
        tl.name as enrollment_location_name
      FROM financing_requests f
      JOIN customers c ON f.customer_id = c.id
      LEFT JOIN tenant_locations tl ON tl.id = COALESCE(f.location_id, c.location_id)
      LEFT JOIN banks b ON f.selected_bank_id = b.id
      LEFT JOIN financing_types ft ON f.financing_type_id = ft.id
      LEFT JOIN customer_assignments ca ON c.id = ca.customer_id
      LEFT JOIN users u ON ca.employee_id = u.id
      LEFT JOIN users ba ON ba.id = c.assigned_bank_agent_id`

    const queryParams: any[] = []
    if (userInfo.roleId === 1) {
      // sees all
    } else if (userInfo.roleId === 2 || userInfo.roleId === 3) {
      if (userInfo.tenantId) {
        query += ' WHERE f.tenant_id = ?'
        queryParams.push(userInfo.tenantId)
      } else {
        query += ' WHERE 1 = 0'
      }
    } else if (userInfo.roleId === 4) {
      if (userInfo.tenantId && userInfo.userId) {
        query += ` WHERE f.tenant_id = ? AND EXISTS (
          SELECT 1 FROM customer_assignments ca2
          WHERE ca2.customer_id = c.id AND ca2.employee_id = ?
        )`
        queryParams.push(userInfo.tenantId, userInfo.userId)
      } else {
        query += ' WHERE 1 = 0'
      }
    } else if (normalizeRoleId(userInfo.roleId) === 6) {
      if (userInfo.tenantId && userInfo.userId) {
        query += ` WHERE f.tenant_id = ? AND (
          EXISTS (
            SELECT 1 FROM customer_assignments ca2
            WHERE ca2.customer_id = c.id AND ca2.employee_id = ?
          )
          OR c.assigned_bank_agent_id = ?
          OR f.assigned_bank_agent_id = ?
        )`
        queryParams.push(userInfo.tenantId, userInfo.userId, userInfo.userId, userInfo.userId)
      } else {
        query += ' WHERE 1 = 0'
      }
    } else if (normalizeRoleId(userInfo.roleId) === 5) {
      // Bank agent: requests assigned to them or that they created (created_by), same tenant
      if (userInfo.tenantId && userInfo.userId) {
        query += ` WHERE f.tenant_id = ? AND (
          c.assigned_bank_agent_id = ?
          OR f.assigned_bank_agent_id = ?
          OR f.created_by = ?
        )`
        queryParams.push(userInfo.tenantId, userInfo.userId, userInfo.userId, userInfo.userId)
      } else {
        query += ' WHERE 1 = 0'
      }
    } else {
      query += ' WHERE 1 = 0'
    }
    
    query += ` ORDER BY f.created_at DESC`
    
    const { results } = queryParams.length > 0
      ? await c.env.DB.prepare(query).bind(...queryParams).all()
      : await c.env.DB.prepare(query).all()
    const rows = (results || []) as any[]
    // Attach per-customer unread-alarm count for the current user (drives table glow dot).
    if (userInfo.userId && rows.length > 0) {
      try {
        const alarmRows = await c.env.DB
          .prepare(`SELECT customer_id, COUNT(*) AS cnt FROM customer_alarms
                    WHERE user_id = ? AND is_read = 0 AND customer_id IS NOT NULL
                    GROUP BY customer_id`)
          .bind(userInfo.userId)
          .all<{ customer_id: number; cnt: number }>()
        const countByCustomer: Record<string, number> = {}
        for (const row of alarmRows.results || []) {
          countByCustomer[String(row.customer_id)] = Number(row.cnt) || 0
        }
        for (const r of rows) {
          r.unread_alarm_count = countByCustomer[String(r.customer_id)] || 0
        }
      } catch (_) { /* table may be missing in legacy DBs */ }
    }
    return c.json({ success: true, data: rows })
  } catch (error: any) {
    return c.json({ success: false, error: error.message }, 500)
  }
})

app.get('/api/sidebar-filter-counts', async (c) => {
  try {
    const userInfo = await getUserInfo(c)
    if (!userInfo.userId || !userInfo.roleId) {
      return c.json({ success: false, error: 'غير مصرح' }, 401)
    }

    const customerWhereParts: string[] = []
    const customerParams: any[] = []

    if (userInfo.roleId === 1) {
      // Super admin sees all
    } else if (userInfo.roleId === 2 || userInfo.roleId === 3) {
      if (userInfo.tenantId) {
        customerWhereParts.push('c.tenant_id = ?')
        customerParams.push(userInfo.tenantId)
      } else {
        customerWhereParts.push('1 = 0')
      }
    } else if (userInfo.roleId === 4) {
      if (userInfo.tenantId && userInfo.userId) {
        customerWhereParts.push('c.tenant_id = ?')
        customerWhereParts.push(`EXISTS (
          SELECT 1 FROM customer_assignments ca
          WHERE ca.customer_id = c.id AND ca.employee_id = ?
        )`)
        customerParams.push(userInfo.tenantId, userInfo.userId)
      } else {
        customerWhereParts.push('1 = 0')
      }
    } else if (normalizeRoleId(userInfo.roleId) === 6) {
      if (userInfo.tenantId && userInfo.userId) {
        customerWhereParts.push('c.tenant_id = ?')
        customerWhereParts.push(`(
          EXISTS (
            SELECT 1 FROM customer_assignments ca
            WHERE ca.customer_id = c.id AND ca.employee_id = ?
          )
          OR c.assigned_bank_agent_id = ?
          OR EXISTS (
            SELECT 1 FROM financing_requests fr
            WHERE fr.customer_id = c.id AND fr.assigned_bank_agent_id = ?
          )
        )`)
        customerParams.push(userInfo.tenantId, userInfo.userId, userInfo.userId, userInfo.userId)
      } else {
        customerWhereParts.push('1 = 0')
      }
    } else if (normalizeRoleId(userInfo.roleId) === 5) {
      // Role 5: customers they created OR assigned via a funding request.
      if (userInfo.tenantId && userInfo.userId) {
        customerWhereParts.push('c.tenant_id = ?')
        customerWhereParts.push(`(
          c.created_by = ?
          OR c.assigned_bank_agent_id = ?
          OR EXISTS (
            SELECT 1 FROM financing_requests fr
            LEFT JOIN users fr_creator ON fr_creator.id = fr.created_by
            WHERE fr.customer_id = c.id
              AND (
                fr.assigned_bank_agent_id = ?
                OR (fr.created_by = ? AND fr_creator.role_id IN (5, 15))
              )
          )
        )`)
        customerParams.push(userInfo.tenantId, userInfo.userId, userInfo.userId, userInfo.userId, userInfo.userId)
      } else {
        customerWhereParts.push('1 = 0')
      }
    } else {
      customerWhereParts.push('1 = 0')
    }

    const customerWhereSql = customerWhereParts.length > 0 ? `WHERE ${customerWhereParts.join(' AND ')}` : ''
    const customerCountsRow = await c.env.DB.prepare(`
      WITH scoped_customers AS (
        SELECT c.id
        FROM customers c
        ${customerWhereSql}
      ),
      latest_reviews AS (
        SELECT cr.customer_id, cr.rating
        FROM customer_reviews cr
        INNER JOIN (
          SELECT customer_id, MAX(created_at) AS max_created
          FROM customer_reviews
          GROUP BY customer_id
        ) latest
          ON latest.customer_id = cr.customer_id
         AND latest.max_created = cr.created_at
      )
      SELECT
        COUNT(sc.id) AS all_count,
        SUM(CASE WHEN lr.rating = 1 THEN 1 ELSE 0 END) AS rating_1,
        SUM(CASE WHEN lr.rating = 2 THEN 1 ELSE 0 END) AS rating_2,
        SUM(CASE WHEN lr.rating = 3 THEN 1 ELSE 0 END) AS rating_3,
        SUM(CASE WHEN lr.rating = 4 THEN 1 ELSE 0 END) AS rating_4,
        SUM(CASE WHEN lr.rating = 5 THEN 1 ELSE 0 END) AS rating_5
      FROM scoped_customers sc
      LEFT JOIN latest_reviews lr ON lr.customer_id = sc.id
    `).bind(...customerParams).first() as {
      all_count?: number
      rating_1?: number
      rating_2?: number
      rating_3?: number
      rating_4?: number
      rating_5?: number
    } | null

    const allCustomers = Number(customerCountsRow?.all_count || 0)
    const ratedCustomers =
      Number(customerCountsRow?.rating_1 || 0) +
      Number(customerCountsRow?.rating_2 || 0) +
      Number(customerCountsRow?.rating_3 || 0) +
      Number(customerCountsRow?.rating_4 || 0) +
      Number(customerCountsRow?.rating_5 || 0)
    const withoutRating = Math.max(0, allCustomers - ratedCustomers)

    const completedCustomerWhereSql = customerWhereSql
      ? `${customerWhereSql} AND COALESCE(c.is_completed, 0) = 1`
      : 'WHERE COALESCE(c.is_completed, 0) = 1'
    const completedCustomersRow = (await c.env.DB.prepare(`
      SELECT COUNT(*) AS count
      FROM customers c
      ${completedCustomerWhereSql}
    `).bind(...customerParams).first()) as { count?: number } | null
    const completedCustomersCount = Number(completedCustomersRow?.count || 0)

    const archivedCustomerWhereParts: string[] = ['COALESCE(c.is_archived, 0) = 1']
    const archivedCustomerParams: any[] = []
    if (userInfo.roleId === 1) {
      // Super admin sees all archived
    } else if (userInfo.roleId === 2 || userInfo.roleId === 3) {
      if (userInfo.tenantId) {
        archivedCustomerWhereParts.push('c.tenant_id = ?')
        archivedCustomerParams.push(userInfo.tenantId)
      } else {
        archivedCustomerWhereParts.push('1 = 0')
      }
    } else if (userInfo.roleId === 4) {
      if (userInfo.tenantId && userInfo.userId) {
        archivedCustomerWhereParts.push('c.tenant_id = ?')
        archivedCustomerWhereParts.push(`EXISTS (
          SELECT 1 FROM customer_assignments ca
          WHERE ca.customer_id = c.id AND ca.employee_id = ?
        )`)
        archivedCustomerParams.push(userInfo.tenantId, userInfo.userId)
      } else {
        archivedCustomerWhereParts.push('1 = 0')
      }
    } else if (normalizeRoleId(userInfo.roleId) === 6) {
      if (userInfo.tenantId && userInfo.userId) {
        archivedCustomerWhereParts.push('c.tenant_id = ?')
        archivedCustomerWhereParts.push(`(
          EXISTS (
            SELECT 1 FROM customer_assignments ca
            WHERE ca.customer_id = c.id AND ca.employee_id = ?
          )
          OR c.assigned_bank_agent_id = ?
          OR EXISTS (
            SELECT 1 FROM financing_requests fr
            WHERE fr.customer_id = c.id AND fr.assigned_bank_agent_id = ?
          )
        )`)
        archivedCustomerParams.push(userInfo.tenantId, userInfo.userId, userInfo.userId, userInfo.userId)
      } else {
        archivedCustomerWhereParts.push('1 = 0')
      }
    } else if (normalizeRoleId(userInfo.roleId) === 5) {
      if (userInfo.tenantId && userInfo.userId) {
        archivedCustomerWhereParts.push('c.tenant_id = ?')
        archivedCustomerWhereParts.push(`(
          c.created_by = ?
          OR EXISTS (
            SELECT 1 FROM financing_requests fr
            WHERE fr.customer_id = c.id AND fr.assigned_bank_agent_id = ?
          )
        )`)
        archivedCustomerParams.push(userInfo.tenantId, userInfo.userId, userInfo.userId)
      } else {
        archivedCustomerWhereParts.push('1 = 0')
      }
    } else {
      archivedCustomerWhereParts.push('1 = 0')
    }
    const archivedCustomerWhereSql = `WHERE ${archivedCustomerWhereParts.join(' AND ')}`
    const archivedCustomersRow = (await c.env.DB.prepare(`
      SELECT COUNT(*) AS count
      FROM customers c
      ${archivedCustomerWhereSql}
    `).bind(...archivedCustomerParams).first()) as { count?: number } | null
    const archivedCustomersCount = Number(archivedCustomersRow?.count || 0)

    const requestWhereParts: string[] = []
    const requestParams: any[] = []

    if (userInfo.roleId === 1) {
      // Super admin sees all
    } else if (userInfo.roleId === 2 || userInfo.roleId === 3) {
      if (userInfo.tenantId) {
        requestWhereParts.push('c.tenant_id = ?')
        requestParams.push(userInfo.tenantId)
      } else {
        requestWhereParts.push('1 = 0')
      }
    } else if (userInfo.roleId === 4) {
      if (userInfo.tenantId && userInfo.userId) {
        requestWhereParts.push('c.tenant_id = ?')
        requestWhereParts.push(`EXISTS (
          SELECT 1 FROM customer_assignments ca
          WHERE ca.customer_id = c.id AND ca.employee_id = ?
        )`)
        requestParams.push(userInfo.tenantId, userInfo.userId)
      } else {
        requestWhereParts.push('1 = 0')
      }
    } else if (normalizeRoleId(userInfo.roleId) === 6) {
      if (userInfo.tenantId && userInfo.userId) {
        requestWhereParts.push('c.tenant_id = ?')
        requestWhereParts.push(`(
          EXISTS (
            SELECT 1 FROM customer_assignments ca
            WHERE ca.customer_id = c.id AND ca.employee_id = ?
          )
          OR c.assigned_bank_agent_id = ?
          OR fr.assigned_bank_agent_id = ?
        )`)
        requestParams.push(userInfo.tenantId, userInfo.userId, userInfo.userId, userInfo.userId)
      } else {
        requestWhereParts.push('1 = 0')
      }
    } else if (normalizeRoleId(userInfo.roleId) === 5) {
      // Role 5: requests assigned to them or that they created
      if (userInfo.userId) {
        if (userInfo.tenantId) {
          requestWhereParts.push('c.tenant_id = ?')
          requestParams.push(userInfo.tenantId)
        }
        requestWhereParts.push('(fr.assigned_bank_agent_id = ? OR fr.created_by = ?)')
        requestParams.push(userInfo.userId, userInfo.userId)
      } else {
        requestWhereParts.push('1 = 0')
      }
    } else {
      requestWhereParts.push('1 = 0')
    }

    const requestWhereSql = requestWhereParts.length > 0 ? `WHERE ${requestWhereParts.join(' AND ')}` : ''
    // Exclude completed requests — they live on /admin/requests/completed, not the main table
    const activeRequestWhereSql = requestWhereSql
      ? `${requestWhereSql} AND COALESCE(fr.is_completed, 0) = 0`
      : 'WHERE COALESCE(fr.is_completed, 0) = 0'

    const requestRows = (await c.env.DB.prepare(`
      SELECT
        COALESCE(
          ws.stage_name_ar,
          CASE fr.status
            WHEN 'pending' THEN 'قيد الانتظار'
            WHEN 'under_review' THEN 'قيد المراجعة'
            WHEN 'approved' THEN 'موافق عليه'
            WHEN 'rejected' THEN 'مرفوض'
            WHEN 'processing' THEN 'قيد المعالجة'
            WHEN 'completed' THEN 'مكتمل'
            WHEN 'cancelled' THEN 'ملغي'
            ELSE fr.status
          END,
          'غير محدد'
        ) AS status_label,
        COUNT(*) AS count
      FROM financing_requests fr
      LEFT JOIN customers c ON fr.customer_id = c.id
      LEFT JOIN workflow_stages ws ON fr.current_stage_id = ws.id
      ${activeRequestWhereSql}
      GROUP BY status_label
    `).bind(...requestParams).all()).results as Array<{ status_label?: string; count?: number }>

    const requestCountsByState: Record<string, number> = {}
    let allRequests = 0
    requestRows.forEach((row) => {
      const key = String(row?.status_label || '').trim()
      const val = Number(row?.count || 0)
      if (!key) return
      requestCountsByState[key] = val
      allRequests += val
    })

    // Count completed requests separately (shown on /admin/requests/completed)
    const completedWhereSql = requestWhereSql
      ? `${requestWhereSql} AND COALESCE(fr.is_completed, 0) = 1`
      : 'WHERE COALESCE(fr.is_completed, 0) = 1'
    const completedRow = (await c.env.DB.prepare(`
      SELECT COUNT(*) AS count
      FROM financing_requests fr
      LEFT JOIN customers c ON fr.customer_id = c.id
      ${completedWhereSql}
    `).bind(...requestParams).first()) as { count?: number } | null
    const completedCount = Number(completedRow?.count || 0)

    return c.json({
      success: true,
      customers: {
        all: allCustomers,
        '0': withoutRating,
        '1': Number(customerCountsRow?.rating_1 || 0),
        '2': Number(customerCountsRow?.rating_2 || 0),
        '3': Number(customerCountsRow?.rating_3 || 0),
        '4': Number(customerCountsRow?.rating_4 || 0),
        '5': Number(customerCountsRow?.rating_5 || 0),
        completed: completedCustomersCount,
        archived: archivedCustomersCount,
      },
      requests: {
        all: allRequests,
        byState: requestCountsByState,
        completed: completedCount,
      },
    })
  } catch (error: any) {
    return c.json({ success: false, error: error.message }, 500)
  }
})

// Create new financing request
app.post('/api/requests', async (c) => {
  try {
    const acceptHeader = c.req.header('Accept') || ''
    const wantsJson = acceptHeader.includes('application/json') || c.req.header('X-Requested-With') === 'fetch'
    const formData = await c.req.formData()
    const customer_id = formData.get('customer_id')
    const financing_type_id = formData.get('financing_type_id')
    const requested_amount = formData.get('requested_amount')
    const duration_months = formData.get('duration_months')
    const salary_at_request = formData.get('salary_at_request')
    const selected_bank_id_raw = formData.get('selected_bank_id')
    let selected_bank_id: number | null =
      selected_bank_id_raw != null && String(selected_bank_id_raw).trim() !== ''
        ? parseInt(String(selected_bank_id_raw), 10)
        : null
    if (selected_bank_id != null && Number.isNaN(selected_bank_id)) {
      selected_bank_id = null
    }
    const assigned_agent_raw = formData.get('assigned_bank_agent_id')
    let formAssignedBankAgent: number | null =
      assigned_agent_raw != null && String(assigned_agent_raw).trim() !== ''
        ? parseInt(String(assigned_agent_raw), 10)
        : null
    if (formAssignedBankAgent != null && Number.isNaN(formAssignedBankAgent)) {
      formAssignedBankAgent = null
    }
    const status = formData.get('status') || 'pending'
    const notes = formData.get('notes') || ''
    
    const userInfo = await getUserInfo(c)
    if (!userInfo.userId || !userInfo.roleId) {
      return c.json({ success: false, error: 'غير مصرح' }, 401)
    }

    const customer = await c.env.DB.prepare(`
      SELECT id, tenant_id, location_id, assigned_bank_agent_id FROM customers WHERE id = ?
    `).bind(customer_id).first() as {
      id: number
      tenant_id: number | null
      location_id?: number | null
      assigned_bank_agent_id?: number | null
    } | null

    if (!customer) {
      return c.json({ success: false, error: 'العميل غير موجود' }, 400)
    }

    if (await customerHasFinancingRequest(c.env.DB, customer.id)) {
      return c.json({ success: false, error: 'يوجد طلب تمويل مسبق لهذا العميل' }, 400)
    }

    const requestLocationId =
      customer.location_id != null && Number.isFinite(Number(customer.location_id))
        ? Number(customer.location_id)
        : null

    // Enforce tenant scope for non-superadmins
    if (userInfo.roleId !== 1) {
      if (!userInfo.tenantId) {
        return c.json({ success: false, error: 'يجب تحديد الشركة' }, 400)
      }
      if (customer.tenant_id !== userInfo.tenantId) {
        return c.json({ success: false, error: 'غير مصرح لهذه الشركة' }, 403)
      }
    }
    const effectiveBankAgent: number | null =
      formAssignedBankAgent ?? customer.assigned_bank_agent_id ?? null

    const custRow = customer as { id: number; tenant_id: number | null }
    const ridCreate = normalizeRoleId(userInfo.roleId)
    if (ridCreate === 4 || ridCreate === 6) {
      const hasAccess = await canUserAccessCustomer(c.env.DB, userInfo, custRow)
      const selfAssign =
        userInfo.userId != null &&
        formAssignedBankAgent != null &&
        Number(formAssignedBankAgent) === Number(userInfo.userId)
      if (!hasAccess && !selfAssign) {
        return c.json(
          {
            success: false,
            error:
              ridCreate === 6
                ? 'غير مصرح: اختر عميلاً مخصصاً لك أو عيّن نفسك موظف تمويل على الطلب'
                : 'غير مصرح: العميل غير مخصص لك',
          },
          403
        )
      }
    } else if (ridCreate === 5) {
      const hasAccess = await canUserAccessCustomer(c.env.DB, userInfo, custRow)
      const selfAssign =
        userInfo.userId != null &&
        formAssignedBankAgent != null &&
        Number(formAssignedBankAgent) === Number(userInfo.userId)
      if (!hasAccess && !selfAssign) {
        return c.json(
          {
            success: false,
            error:
              'غير مصرح: اختر نفسك كموظف تمويل على هذا الطلب لربط العميل بك، أو اختر عميلاً مرتبطًا بطلباتك',
          },
          403
        )
      }
    }

    const tenant_id = userInfo.roleId === 1 ? customer.tenant_id : userInfo.tenantId

    if (effectiveBankAgent != null) {
      if (!selected_bank_id || Number.isNaN(selected_bank_id)) {
        return c.json({ success: false, error: 'يجب اختيار البنك عند تعيين موظف التمويل' }, 400)
      }
      const tidNum = tenant_id != null ? Number(tenant_id) : NaN
      if (!tidNum || Number.isNaN(tidNum)) {
        return c.json({ success: false, error: 'تعذر تحديد الشركة لتعيين موظف التمويل' }, 400)
      }
      const agentOk = await validateBankAgentForFinancingRequest(c.env.DB, tidNum, effectiveBankAgent)
      if (!agentOk) {
        return c.json({ success: false, error: 'موظف التمويل غير صالح لهذه الشركة' }, 400)
      }
    }
    
    // Insert financing request directly (customer already exists from dropdown).
    // Prefer created_by + location_id; fall back for legacy DBs missing either column.
    const creatorId = userInfo.userId as number
    const bindCommon = [
      customer_id,
      financing_type_id,
      selected_bank_id,
      requested_amount,
      salary_at_request,
      duration_months,
      status,
      notes,
      tenant_id,
      effectiveBankAgent,
    ]
    const attempts: Array<{ loc: boolean; cb: boolean }> = [
      { loc: true, cb: true },
      { loc: false, cb: true },
      { loc: true, cb: false },
      { loc: false, cb: false },
    ]
    let result: { meta: { last_row_id?: number } } | undefined
    let lastInsertErr: unknown
    for (const a of attempts) {
      try {
        if (a.loc && a.cb) {
          result = (await c.env.DB
            .prepare(
              `
      INSERT INTO financing_requests (
        customer_id, financing_type_id, selected_bank_id, 
        requested_amount, salary_at_request, duration_months, 
        status, notes, tenant_id, assigned_bank_agent_id, created_by, location_id
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `
            )
            .bind(...bindCommon, creatorId, requestLocationId)
            .run()) as { meta: { last_row_id?: number } }
        } else if (!a.loc && a.cb) {
          result = (await c.env.DB
            .prepare(
              `
      INSERT INTO financing_requests (
        customer_id, financing_type_id, selected_bank_id, 
        requested_amount, salary_at_request, duration_months, 
        status, notes, tenant_id, assigned_bank_agent_id, created_by
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `
            )
            .bind(...bindCommon, creatorId)
            .run()) as { meta: { last_row_id?: number } }
        } else if (a.loc && !a.cb) {
          result = (await c.env.DB
            .prepare(
              `
      INSERT INTO financing_requests (
        customer_id, financing_type_id, selected_bank_id, 
        requested_amount, salary_at_request, duration_months, 
        status, notes, tenant_id, assigned_bank_agent_id, location_id
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `
            )
            .bind(...bindCommon, requestLocationId)
            .run()) as { meta: { last_row_id?: number } }
        } else {
          result = (await c.env.DB
            .prepare(
              `
      INSERT INTO financing_requests (
        customer_id, financing_type_id, selected_bank_id, 
        requested_amount, salary_at_request, duration_months, 
        status, notes, tenant_id, assigned_bank_agent_id
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `
            )
            .bind(...bindCommon)
            .run()) as { meta: { last_row_id?: number } }
        }
        lastInsertErr = undefined
        break
      } catch (e: unknown) {
        lastInsertErr = e
        result = undefined
      }
    }
    if (result == null) {
      throw lastInsertErr instanceof Error ? lastInsertErr : new Error(String(lastInsertErr))
    }

    // Single source of truth: customers.assigned_bank_agent_id; mirror onto the new financing_requests row.
    try {
      if (formAssignedBankAgent != null) {
        await setCustomerAssignedBankAgent(c.env.DB, Number(customer_id), formAssignedBankAgent)
      }
      const custRow = await c.env.DB.prepare(
        `SELECT assigned_bank_agent_id FROM customers WHERE id = ? LIMIT 1`
      )
        .bind(customer_id)
        .first<{ assigned_bank_agent_id: number | null }>()
      const finalAgent = custRow?.assigned_bank_agent_id ?? null
      if (result.meta.last_row_id != null) {
        await c.env.DB.prepare(`UPDATE financing_requests SET assigned_bank_agent_id = ? WHERE id = ?`)
          .bind(finalAgent, result.meta.last_row_id)
          .run()
      }
    } catch (_) {
      // Non-fatal: sync failure should not block the request creation response.
    }

    if (wantsJson) {
      return c.json({ success: true, id: result.meta.last_row_id }, 201)
    }
    return c.redirect('/admin/requests')
  } catch (error: any) {
    console.error('Error creating request:', error)
    return c.json({ success: false, error: error.message, message: 'حدث خطأ أثناء حفظ الطلب' }, 500)
  }
})

