// Get workflow timeline for a specific request
app.get('/api/workflow/timeline/:requestId', async (c) => {
  try {
    const userInfo = await getUserInfo(c)
    if (!userInfo.userId) return c.json({ success: false, error: 'Unauthorized' }, 401)
    const requestId = c.req.param('requestId')
    if (!(await canUserAccessRequestWorkflow(c.env.DB, userInfo, Number(requestId)))) {
      return c.json({ success: false, error: 'Forbidden' }, 403)
    }

    // Get all stage transitions
    const { results: transitions } = await c.env.DB.prepare(`
      SELECT 
        wst.*,
        from_stage.stage_name_ar as from_stage_name,
        from_stage.stage_color as from_stage_color,
        from_stage.stage_icon as from_stage_icon,
        to_stage.stage_name_ar as to_stage_name,
        to_stage.stage_color as to_stage_color,
        to_stage.stage_icon as to_stage_icon,
        u.full_name as transitioned_by_name
      FROM workflow_stage_transitions wst
      LEFT JOIN workflow_stages from_stage ON wst.from_stage_id = from_stage.id
      LEFT JOIN workflow_stages to_stage ON wst.to_stage_id = to_stage.id
      LEFT JOIN users u ON wst.transitioned_by = u.id
      WHERE wst.request_id = ?
      ORDER BY wst.created_at ASC
    `).bind(requestId).all()
    
    // Get all actions for this request
    const { results: actions } = await c.env.DB.prepare(`
      SELECT 
        wsa.*,
        ws.stage_name_ar,
        ws.stage_color,
        ws.stage_icon,
        u.full_name as performed_by_name
      FROM workflow_stage_actions wsa
      LEFT JOIN workflow_stages ws ON wsa.stage_id = ws.id
      LEFT JOIN users u ON wsa.performed_by = u.id
      WHERE wsa.request_id = ?
      ORDER BY wsa.created_at ASC
    `).bind(requestId).all()
    
    // Get all tasks for this request
    const { results: tasks } = await c.env.DB.prepare(`
      SELECT 
        wst.*,
        ws.stage_name_ar,
        assigned_user.full_name as assigned_to_name,
        completed_user.full_name as completed_by_name
      FROM workflow_stage_tasks wst
      LEFT JOIN workflow_stages ws ON wst.stage_id = ws.id
      LEFT JOIN users assigned_user ON wst.assigned_to = assigned_user.id
      LEFT JOIN users completed_user ON wst.completed_by = completed_user.id
      WHERE wst.request_id = ?
      ORDER BY wst.due_date ASC
    `).bind(requestId).all()
    
    return c.json({ 
      success: true, 
      data: {
        transitions,
        actions,
        tasks
      }
    })
  } catch (error: any) {
    return c.json({ success: false, error: error.message }, 500)
  }
})

const WORKFLOW_STATUS_BY_STAGE: Record<string, 'pending' | 'under_review' | 'approved' | 'rejected' | 'cancelled'> = {
  draft: 'pending',
  submitted: 'pending',
  missing_docs: 'under_review',
  processing: 'under_review',
  underwriting: 'under_review',
  conditional_approval: 'under_review',
  documentation: 'under_review',
  approved: 'approved',
  final_approval: 'approved',
  disbursed: 'approved',
  active: 'approved',
  closed: 'approved',
  rejected: 'rejected',
  cancelled: 'cancelled'
}

function mapWorkflowStageToRequestStatus(stageName?: string | null) {
  if (!stageName) return null
  return WORKFLOW_STATUS_BY_STAGE[stageName] || null
}

// Update request stage
app.post('/api/workflow/update-stage', async (c) => {
  try {
    const requester = await getUserInfo(c)
    if (!requester.userId) return c.json({ success: false, error: 'Unauthorized' }, 401)
    if (normalizeRoleId(requester.roleId) === 4) {
      return c.json({ success: false, error: 'Forbidden' }, 403)
    }
    const { requestId, newStageId, notes, userId } = await c.req.json()
    if (!(await canUserAccessRequestWorkflow(c.env.DB, requester, Number(requestId)))) {
      return c.json({ success: false, error: 'Forbidden' }, 403)
    }

    const stage = await c.env.DB.prepare(`
      SELECT stage_name FROM workflow_stages WHERE id = ?
    `).bind(newStageId).first() as { stage_name?: string } | null

    const currentRequest = await c.env.DB.prepare(`
      SELECT status, current_stage_id FROM financing_requests WHERE id = ?
    `).bind(requestId).first() as { status?: string; current_stage_id?: number | null } | null

    // Ignore duplicate submits (double-click) for the same stage within a short window
    const recentDup = await c.env.DB.prepare(`
      SELECT id FROM workflow_stage_transitions
      WHERE request_id = ? AND to_stage_id = ?
        AND created_at >= datetime('now', '-20 seconds')
      LIMIT 1
    `).bind(requestId, newStageId).first()
    if (recentDup && currentRequest?.current_stage_id === newStageId) {
      if (notes) {
        await c.env.DB.prepare(`
          UPDATE workflow_stage_transitions
          SET notes = ?, transitioned_by = ?
          WHERE request_id = ? AND to_stage_id = ?
          ORDER BY created_at DESC
          LIMIT 1
        `).bind(notes, userId, requestId, newStageId).run()
      }
      return c.json({ success: true, message: 'تم تحديث مرحلة الطلب بنجاح' })
    }

    const mappedStatus = mapWorkflowStageToRequestStatus(stage?.stage_name || null)

    const updateFields = [
      'current_stage_id = ?',
      'stage_entered_at = CURRENT_TIMESTAMP'
    ]
    const updateParams: any[] = [newStageId]

    if (mappedStatus) {
      updateFields.push('status = ?')
      updateParams.push(mappedStatus)

      if (mappedStatus === 'pending') {
        updateFields.push("pending_at = COALESCE(pending_at, CURRENT_TIMESTAMP)")
      } else if (mappedStatus === 'under_review') {
        updateFields.push("under_review_at = COALESCE(under_review_at, CURRENT_TIMESTAMP)")
      } else if (mappedStatus === 'approved') {
        updateFields.push("approved_at = COALESCE(approved_at, CURRENT_TIMESTAMP)")
      } else if (mappedStatus === 'rejected') {
        updateFields.push("rejected_at = COALESCE(rejected_at, CURRENT_TIMESTAMP)")
      }

      if (mappedStatus === 'approved' || mappedStatus === 'rejected' || mappedStatus === 'under_review') {
        updateFields.push('reviewed_at = CURRENT_TIMESTAMP')
      }
    }

    updateParams.push(requestId)

    // Update stage + keep legacy status aligned for compatibility
    await c.env.DB.prepare(`
      UPDATE financing_requests 
      SET ${updateFields.join(', ')}
      WHERE id = ?
    `).bind(...updateParams).run()
    
    // The trigger will automatically create a transition record
    // But we can add notes if provided
    if (notes) {
      await c.env.DB.prepare(`
        UPDATE workflow_stage_transitions 
        SET notes = ?, transitioned_by = ?
        WHERE request_id = ? AND to_stage_id = ?
        ORDER BY created_at DESC
        LIMIT 1
      `).bind(notes, userId, requestId, newStageId).run()
    }

    if (mappedStatus && currentRequest?.status && currentRequest.status !== mappedStatus) {
      await c.env.DB.prepare(`
        INSERT INTO financing_request_status_history (request_id, old_status, new_status, changed_by, notes)
        VALUES (?, ?, ?, ?, ?)
      `).bind(requestId, currentRequest.status, mappedStatus, userId || null, notes || '').run()
    }

    // Notify the other party (role 4 ↔ role 5) about this stage update — assigned user only
    try {
      const stageNameAr = (await c.env.DB.prepare(`SELECT stage_name_ar FROM workflow_stages WHERE id = ?`).bind(newStageId).first() as any)?.stage_name_ar || stage?.stage_name || ''
      const actorRow = await c.env.DB.prepare(`SELECT full_name, tenant_id FROM users WHERE id = ?`).bind(requester.userId).first() as any
      const actorName = actorRow?.full_name || ''
      const actorTenant = actorRow?.tenant_id ?? null
      const reqRow = await c.env.DB.prepare(`SELECT customer_id FROM financing_requests WHERE id = ?`).bind(requestId).first() as any
      const customerId = reqRow?.customer_id ?? null
      if (customerId) {
        const targetUserIds = await resolveWorkflowCrossPartyNotifyTargetUserIds(
          c.env.DB,
          customerId,
          requester.userId,
          requester.roleId,
          actorTenant,
          Number(requestId)
        )
        if (targetUserIds.length) {
          await insertWorkflowCrossPartyAlarms(c.env.DB, {
            customerId,
            tenantId: actorTenant,
            targetUserIds,
            customerName: `تحديث مرحلة: ${stageNameAr}`,
            note: `قام ${actorName} بتحديث مرحلة الطلب #${requestId} إلى: ${stageNameAr}`,
            linkUrl: `/admin/requests/${requestId}/workflow#request`
          })
        }
      }
    } catch (_) {}

    return c.json({ success: true, message: 'تم تحديث مرحلة الطلب بنجاح' })
  } catch (error: any) {
    return c.json({ success: false, error: error.message }, 500)
  }
})

// Add action to a stage (not phase notes — see /api/workflow/add-note)
app.post('/api/workflow/add-action', async (c) => {
  try {
    const requester = await getUserInfo(c)
    if (!requester.userId) return c.json({ success: false, error: 'Unauthorized' }, 401)
    if (normalizeRoleId(requester.roleId) === 5) {
      return c.json({ success: false, error: 'Forbidden' }, 403)
    }
    const { requestId, stageId, actionType, actionData, performedBy, notes } = await c.req.json()
    if (!(await canUserAccessRequestWorkflow(c.env.DB, requester, Number(requestId)))) {
      return c.json({ success: false, error: 'Forbidden' }, 403)
    }
    const actorId = performedBy || requester.userId
    const effectiveStageId = await resolveRequestWorkflowStageId(c.env.DB, requestId, stageId)

    const recentDup = await c.env.DB.prepare(`
      SELECT id FROM workflow_stage_actions
      WHERE request_id = ? AND stage_id = ? AND action_type = ?
        AND performed_by = ?
        AND COALESCE(notes, '') = COALESCE(?, '')
        AND created_at >= datetime('now', '-20 seconds')
      LIMIT 1
    `).bind(requestId, effectiveStageId, actionType, actorId, notes ?? '').first()
    if (recentDup) return c.json({ success: true })

    await c.env.DB.prepare(`
      INSERT INTO workflow_stage_actions
      (request_id, stage_id, action_type, action_data, performed_by, notes)
      VALUES (?, ?, ?, ?, ?, ?)
    `).bind(requestId, effectiveStageId, actionType, actionData ?? null, actorId, notes ?? null).run()

    // Notify the other party about this action — assigned user only
    try {
      const actionLabel = ({ call: 'اتصال هاتفي', email: 'بريد إلكتروني', meeting: 'اجتماع', document: 'مستند', approval: 'موافقة', rejection: 'رفض', followup: 'متابعة', other: 'أخرى' } as Record<string,string>)[actionType] || actionType
      const actorRow = await c.env.DB.prepare(`SELECT full_name, tenant_id FROM users WHERE id = ?`).bind(requester.userId).first() as any
      const actorName = actorRow?.full_name || ''
      const actorTenant = actorRow?.tenant_id ?? null
      const reqRow = await c.env.DB.prepare(`SELECT customer_id FROM financing_requests WHERE id = ?`).bind(requestId).first() as any
      const customerId = reqRow?.customer_id ?? null
      if (customerId) {
        const targetUserIds = await resolveWorkflowCrossPartyNotifyTargetUserIds(
          c.env.DB,
          customerId,
          requester.userId,
          requester.roleId,
          actorTenant,
          Number(requestId)
        )
        if (targetUserIds.length) {
          await insertWorkflowCrossPartyAlarms(c.env.DB, {
            customerId,
            tenantId: actorTenant,
            targetUserIds,
            customerName: `إجراء: ${actionLabel}`,
            note: `قام ${actorName} بإضافة إجراء "${actionLabel}" على الطلب #${requestId}${notes ? ' — ' + notes : ''}`,
            linkUrl: `/admin/requests/${requestId}/workflow#request`
          })
        }
      }
    } catch (_) {}

    return c.json({ success: true, message: 'تم إضافة الإجراء بنجاح' })
  } catch (error: any) {
    return c.json({ success: false, error: error.message }, 500)
  }
})

// Add a phase note to a request stage (separate from actions)
app.post('/api/workflow/add-note', async (c) => {
  try {
    const requester = await getUserInfo(c)
    if (!requester.userId) return c.json({ success: false, error: 'Unauthorized' }, 401)
    if (!canAddWorkflowNote(requester.roleId)) {
      return c.json({ success: false, error: 'Forbidden' }, 403)
    }
    const { requestId, stageId, noteText, performedBy } = await c.req.json()
    const text = String(noteText || '').trim()
    if (!text) return c.json({ success: false, error: 'Note text is required' }, 400)
    if (!(await canUserAccessRequestWorkflow(c.env.DB, requester, Number(requestId)))) {
      return c.json({ success: false, error: 'Forbidden' }, 403)
    }
    await ensureWorkflowPhaseNotesTables(c.env.DB)
    const actorId = performedBy || requester.userId
    const effectiveStageId = await resolveRequestWorkflowStageId(c.env.DB, requestId, stageId)

    const recentDup = await c.env.DB.prepare(`
      SELECT id FROM workflow_stage_notes
      WHERE request_id = ? AND stage_id = ? AND performed_by = ?
        AND note_text = ?
        AND created_at >= datetime('now', '-20 seconds')
      LIMIT 1
    `).bind(requestId, effectiveStageId, actorId, text).first()
    if (recentDup) return c.json({ success: true })

    await c.env.DB.prepare(`
      INSERT INTO workflow_stage_notes (request_id, stage_id, note_text, performed_by)
      VALUES (?, ?, ?, ?)
    `).bind(requestId, effectiveStageId, text, actorId).run()

    try {
      const actorRow = await c.env.DB.prepare(`SELECT full_name, tenant_id FROM users WHERE id = ?`).bind(requester.userId).first() as any
      const actorName = actorRow?.full_name || ''
      const actorTenant = actorRow?.tenant_id ?? null
      const reqRow = await c.env.DB.prepare(`SELECT customer_id FROM financing_requests WHERE id = ?`).bind(requestId).first() as any
      const customerId = reqRow?.customer_id ?? null
      if (customerId) {
        const targetUserIds = await resolveWorkflowCrossPartyNotifyTargetUserIds(
          c.env.DB,
          customerId,
          requester.userId,
          requester.roleId,
          actorTenant,
          Number(requestId)
        )
        if (targetUserIds.length) {
          await insertWorkflowCrossPartyAlarms(c.env.DB, {
            customerId,
            tenantId: actorTenant,
            targetUserIds,
            customerName: 'ملاحظة على سير العمل',
            note: `قام ${actorName} بإضافة ملاحظة على الطلب #${requestId} — ${text}`,
            linkUrl: `/admin/requests/${requestId}/workflow#request`
          })
        }
      }
    } catch (_) {}

    return c.json({ success: true, message: 'تم إضافة الملاحظة بنجاح' })
  } catch (error: any) {
    return c.json({ success: false, error: error.message }, 500)
  }
})

