// Delete role
app.delete('/api/roles/:id', async (c) => {
  try {
    const requester = await getUserInfo(c)
    if (!requester.userId) {
      return c.json({ success: false, error: 'Unauthorized' }, 401)
    }
    if (!isSuperAdminUser(requester)) {
      return c.json({ success: false, error: 'Forbidden' }, 403)
    }
    const id = c.req.param('id')
    
    // Check if role is in use
    const usersCount = await c.env.DB.prepare(`
      SELECT COUNT(*) as count FROM users WHERE role_id = ?
    `).bind(id).first()
    
    if (usersCount && usersCount.count > 0) {
      return c.json({ 
        success: false, 
        error: 'لا يمكن حذف هذا الدور لأنه مرتبط بمستخدمين' 
      }, 400)
    }
    
    // Delete role permissions first
    await c.env.DB.prepare(`
      DELETE FROM role_permissions WHERE role_id = ?
    `).bind(id).run()
    
    // Delete role
    await c.env.DB.prepare(`
      DELETE FROM roles WHERE id = ?
    `).bind(id).run()
    
    return c.json({ success: true, message: 'تم حذف الدور بنجاح' })
  } catch (error: any) {
    return c.json({ success: false, error: error.message }, 500)
  }
})

// Update user (including role change)
app.put('/api/users/:id', async (c) => {
  try {
    const id = c.req.param('id')
    const body = await c.req.json()
    const { full_name, email, phone, role_id, is_active } = body
    const customerLimitRaw = body.customer_limit
    const customerLimit =
      customerLimitRaw === '' || customerLimitRaw == null
        ? null
        : parseInt(String(customerLimitRaw), 10) || null

    await c.env.DB.prepare(`
      UPDATE users
      SET full_name = ?, email = ?, phone = ?, role_id = ?, is_active = ?, customer_limit = ?
      WHERE id = ?
    `).bind(full_name, email, phone, role_id, is_active, customerLimit, id).run()

    return c.json({ success: true, message: 'تم تحديث بيانات المستخدم بنجاح' })
  } catch (error: any) {
    return c.json({ success: false, error: error.message }, 500)
  }
})

