app.get('/admin/contracts/new', async (c) => {
  const denied = await ensureContractsModuleAccess(c, 'list-new-only', { allowRole4: true })
  if (denied) return denied
  const userInfo = await getUserInfo(c)
  if (!userInfo.userId || !userInfo.roleId) {
    return c.redirect('/login')
  }
  if (userInfo.roleId === 3 && c.req.query('edit')) {
    return c.redirect('/admin/contracts/list')
  }
  if ((userInfo.roleId === 2 || userInfo.roleId === 3 || userInfo.roleId === 4 || userInfo.roleId === 5 || userInfo.roleId === 6) && !userInfo.tenantId) {
    return c.html('<h1>خطأ: يجب تحديد الشركة</h1>', 400)
  }
  const { results } = await loadCustomersForAdminForms(c, userInfo, { scopeSuperAdminToTenant: true, filterRole4ByFundingRequests: true })
  const escAttr = (s: string) => (s || '').replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  const escText = (s: string) => (s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  const optionsHtml = (results as any[]).map((cust: any) => {
    const natId = (cust.national_id && !String(cust.national_id).startsWith('TEMP-')) ? String(cust.national_id) : ''
    const label = escText(cust.full_name || '')
      + (cust.phone ? ' — ' + escText(cust.phone) : '')
      + (natId ? ' (' + escText(natId) + ')' : '')
    return `<option value="${escAttr(String(cust.id))}" data-name="${escAttr(cust.full_name || '')}" data-national-id="${escAttr(natId)}" data-phone="${escAttr(cust.phone || '')}" data-city="${escAttr(cust.city || '')}">${label}</option>`
  }).join('\n')

  let partyOneSummaryHtml = ''
  let partyOneNameAttr = ''
  let partyOnePhoneAttr = ''
  let locationOptionsHtml = ''
  const tid = userInfo.tenantId
  if (tid) {
    const trow = await c.env.DB.prepare(
      'SELECT company_name, contact_phone FROM tenants WHERE id = ?'
    )
      .bind(tid)
      .first<{ company_name: string | null; contact_phone: string | null }>()
    if (trow) {
      partyOneNameAttr = escAttr(trow.company_name || '')
      partyOnePhoneAttr = escAttr((trow.contact_phone || '').trim())
      partyOneSummaryHtml =
        '<span class="text-muted">تُعبأ الحقول أدناه تلقائياً من بيانات شركتك الحالية؛ يمكنك تعديلها قبل الحفظ.</span>'
      if (trow.company_name) {
        const phone = (trow.contact_phone || '').trim()
        partyOneSummaryHtml += `<br><span style="margin-top:8px;display:inline-block;"><strong>${escText(
          trow.company_name
        )}</strong>${phone ? ` — ${escText(phone)}` : ''}</span>`
      }
    }
  }
  if (!partyOneSummaryHtml) {
    partyOneSummaryHtml =
      userInfo.roleId === 1
        ? '<span class="text-muted">لم يُحدد معرّف شركة. أضف <code>?tenant_id=</code> إلى الرابط لعرض بيانات الطرف الأول.</span>'
        : '<span class="text-muted">تعذر تحميل بيانات الشركة.</span>'
  }
  if (tid) {
    try {
      const locRows = (await c.env.DB.prepare(
        `SELECT id, name, contact_phone FROM tenant_locations WHERE tenant_id = ? AND is_active = 1 ORDER BY is_primary DESC, name ASC`
      ).bind(tid).all()).results as { id: number; name: string; contact_phone: string | null }[]
      locationOptionsHtml = locRows
        .map(l => `<option value="${escAttr(String(l.id))}" data-phone="${escAttr(l.contact_phone || '')}">${escText(l.name)}</option>`)
        .join('\n')
    } catch (_) {}
  }

  // Build financing requests JSON keyed by customer_id for the funding request dropdown
  let frScriptTag = ''
  try {
    const frTenantId = userInfo.tenantId
    if (frTenantId) {
      let frSql: string
      let frBinds: (number | string)[]
      if ((userInfo.roleId === 4 || userInfo.roleId === 6) && userInfo.userId) {
        frSql = `SELECT fr.id, fr.customer_id, fr.requested_amount,
                        ft.type_name, b.bank_name
                 FROM financing_requests fr
                 LEFT JOIN financing_types ft ON ft.id = fr.financing_type_id
                 LEFT JOIN banks b ON b.id = fr.selected_bank_id
                 WHERE fr.tenant_id = ?
                   AND COALESCE(fr.is_completed, 0) = 0
                   AND EXISTS (SELECT 1 FROM customer_assignments ca
                               WHERE ca.customer_id = fr.customer_id AND ca.employee_id = ?)
                 ORDER BY fr.id DESC LIMIT 500`
        frBinds = [frTenantId, userInfo.userId]
      } else {
        frSql = `SELECT fr.id, fr.customer_id, fr.requested_amount,
                        ft.type_name, b.bank_name
                 FROM financing_requests fr
                 LEFT JOIN financing_types ft ON ft.id = fr.financing_type_id
                 LEFT JOIN banks b ON b.id = fr.selected_bank_id
                 WHERE fr.tenant_id = ?
                 ORDER BY fr.id DESC LIMIT 500`
        frBinds = [frTenantId]
      }
      const frRows = (await c.env.DB.prepare(frSql).bind(...frBinds).all()).results as any[]
      const frMap: Record<string, { id: number; requested_amount: number | null; type_name: string | null; bank_name: string | null }[]> = {}
      for (const row of frRows) {
        const key = String(row.customer_id)
        if (!frMap[key]) frMap[key] = []
        frMap[key].push({ id: row.id, requested_amount: row.requested_amount ?? null, type_name: row.type_name ?? null, bank_name: row.bank_name ?? null })
      }
      frScriptTag = `<script>window._contractsFRs = ${JSON.stringify(frMap)};</script>`
    }
  } catch (_) {}

  let financeTypeOptionsHtml = ''
  try {
    let ftTenantId: number | null = userInfo.tenantId
    if (ftTenantId == null && userInfo.roleId === 1) {
      const q = c.req.query('tenant_id')
      if (q != null && /^\d+$/.test(String(q))) ftTenantId = parseInt(String(q), 10)
    }
    const ftRows = ftTenantId
      ? ((await c.env.DB.prepare(
          `SELECT type_name FROM financing_types WHERE tenant_id = ? AND is_active = 1 ORDER BY id ASC`
        ).bind(ftTenantId).all()).results as { type_name: string }[])
      : []
    financeTypeOptionsHtml = ftRows.map(ft => `<option value="${escAttr(ft.type_name)}">${escText(ft.type_name)}</option>`).join('\n')
  } catch (_) {}

  let html = contractsNewPage
    .replace('<!--CONTRACTS_CUSTOMERS_OPTIONS-->', optionsHtml)
    .replace('<!--CONTRACTS_PARTY_ONE_SUMMARY-->', partyOneSummaryHtml)
    .replace('<!--CONTRACTS_PARTY_ONE_NAME_ATTR-->', partyOneNameAttr)
    .replaceAll('<!--CONTRACTS_PARTY_ONE_PHONE_ATTR-->', partyOnePhoneAttr)
    .replace('<!--CONTRACTS_FINANCING_REQUESTS_JSON-->', frScriptTag)
    .replace('<!--CONTRACTS_FINANCE_TYPE_OPTIONS-->', financeTypeOptionsHtml)
    .replace('<!--CONTRACTS_LOCATION_OPTIONS-->', locationOptionsHtml)
  if (userInfo.roleId === 3) {
    html = markContractsHtmlRole3Restricted(html)
  }
  return c.html(withContractsUserRoleHtml(html, userInfo.roleId))
})
