// Public contact form submit (tenant slug at root path)
app.post('/api/public/:slug/contact-submissions', async (c) => {
  try {
    const slug = normalizeTenantSlug(c.req.param('slug'))
    if (!slug || isReservedRootSlug(slug)) {
      return c.json({ success: false, error: 'Invalid slug' }, 400)
    }

    const payload = await c.req.json().catch(() => ({}))
    const customerName = String(payload?.customer_name ?? '').trim()
    const customerPhoneRaw = String(payload?.customer_phone ?? '').trim()
    const customerMessage = String(payload?.customer_message ?? '').trim()
    const affiliatePathRaw = normalizeAffiliatePathSegment(payload?.affiliate_path)
    const locationSlugRaw = normalizeLocationSlugInput(payload?.location_slug)

    if (!customerName || !customerPhoneRaw || !customerMessage) {
      return c.json({ success: false, error: 'الاسم ورقم الجوال والرسالة مطلوبة' }, 400)
    }

    // Collect custom field values (keyed by label)
    let customFieldsDataJson: string | null = null
    if (payload?.custom_fields && typeof payload.custom_fields === 'object' && !Array.isArray(payload.custom_fields)) {
      const entries = Object.entries(payload.custom_fields as Record<string, unknown>)
        .filter(([k]) => String(k).trim())
        .map(([k, v]) => [String(k).trim().slice(0, 100), String(v ?? '').trim().slice(0, 1000)])
      if (entries.length > 0) customFieldsDataJson = JSON.stringify(Object.fromEntries(entries))
    }

    const phoneNorm = normalizeCustomerPhoneForStorage(customerPhoneRaw)
    if (!phoneNorm.normalized) {
      return c.json({ success: false, error: phoneNorm.error || 'صيغة رقم الجوال غير صحيحة' }, 400)
    }
    const customerPhone = phoneNorm.normalized

    const tenant = await c.env.DB.prepare(`
      SELECT id, contact_assignment_mode, contact_assignment_branch_id
      FROM tenants
      WHERE slug = ? AND status = 'active'
      LIMIT 1
    `).bind(slug).first<{ id: number; contact_assignment_mode: string | null; contact_assignment_branch_id: number | null }>()

    if (!tenant?.id) {
      return c.json({ success: false, error: 'الشركة غير موجودة' }, 404)
    }

    const existingFollowup = await c.env.DB.prepare(
      `SELECT 1 FROM company_contact_followups WHERE tenant_id = ? AND customer_phone = ? LIMIT 1`
    ).bind(tenant.id, customerPhone).first<{ 1: number }>()
    if (existingFollowup) {
      return c.json({ success: false, error: 'رقم الجوال مسجّل مسبقاً كطلب تواصل' }, 409)
    }

    const existingCustomer = await c.env.DB.prepare(
      `SELECT 1 FROM customers WHERE tenant_id = ? AND phone = ? LIMIT 1`
    ).bind(tenant.id, customerPhone).first<{ 1: number }>()
    if (existingCustomer) {
      return c.json({ success: false, error: 'رقم الجوال مسجّل مسبقاً كعميل' }, 409)
    }

    let affiliatePathSegment: string | null = null
    let affiliateLabel: string | null = null
    let affiliateLinkId: number | null = null
    let affiliateLinkAssignmentMode: string = 'auto'
    let affiliateLinkAssignmentBranchId: number | null = null
    const companyLinkAssignmentMode = tenant.contact_assignment_mode ?? 'auto'
    const companyLinkAssignmentBranchId = tenant.contact_assignment_branch_id ?? null
    if (affiliatePathRaw) {
      if (!isValidAffiliatePathSegment(affiliatePathRaw)) {
        return c.json({ success: false, error: 'مسار الإحالة غير صالح' }, 400)
      }
      const affRow = await c.env.DB.prepare(`
        SELECT id, path_segment, label, assignment_mode, assignment_branch_id
        FROM tenant_contact_affiliate_links
        WHERE tenant_id = ? AND path_segment = ?
        LIMIT 1
      `)
        .bind(tenant.id, affiliatePathRaw)
        .first<{ id: number; path_segment: string; label: string; assignment_mode: string | null; assignment_branch_id: number | null }>()
      if (!affRow) {
        return c.json({ success: false, error: 'رابط الإحالة غير معروف' }, 400)
      }
      affiliatePathSegment = affRow.path_segment
      affiliateLabel = affRow.label
      affiliateLinkId = affRow.id
      affiliateLinkAssignmentMode = affRow.assignment_mode ?? 'auto'
      affiliateLinkAssignmentBranchId = affRow.assignment_branch_id ?? null
    } else {
      affiliateLabel = CONTACT_COMPANY_LINK_SOURCE_LABEL
    }

    let locationIdForFollowup: number | null = null
    if (locationSlugRaw) {
      if (!isValidAffiliatePathSegment(locationSlugRaw)) {
        return c.json({ success: false, error: 'مسار الموقع غير صالح' }, 400)
      }
      const locRow = await c.env.DB.prepare(`
        SELECT id FROM tenant_locations
        WHERE tenant_id = ? AND slug = ? AND is_active = 1
        LIMIT 1
      `)
        .bind(tenant.id, locationSlugRaw)
        .first<{ id: number }>()
      if (!locRow) {
        return c.json({ success: false, error: 'الموقع غير معروف' }, 400)
      }
      locationIdForFollowup = locRow.id
    }

    // Columns location_id / custom_fields_data are applied via migrations (not runtime ALTER).

    let insertFollowupResult: any
    insertFollowupResult = await c.env.DB.prepare(`
      INSERT INTO company_contact_followups (
        tenant_id, customer_name, customer_phone, customer_message, source_slug,
        affiliate_path_segment, affiliate_label, location_id, custom_fields_data
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
    `)
      .bind(
        tenant.id,
        customerName,
        customerPhone,
        customerMessage,
        slug,
        affiliatePathSegment,
        affiliateLabel,
        locationIdForFollowup,
        customFieldsDataJson
      )
      .run()

    // Automatically create + assign one follow-up task (roles 4/5/6).
    // Fair queue among eligible staff. If none, the task is created unassigned.
    const createdFollowupIdRaw =
      (insertFollowupResult as any)?.meta?.last_row_id ??
      (insertFollowupResult as any)?.meta?.lastRowId ??
      (insertFollowupResult as any)?.meta?.last_insert_rowid ??
      null
    const createdFollowupId = Number(createdFollowupIdRaw)

    let assignedUserId: number | null = null
    let usedCustomRoster = false
    try {
      const useCustomRoster =
        (affiliateLinkId != null && affiliateLinkAssignmentMode === 'custom') ||
        (affiliateLinkId == null && companyLinkAssignmentMode === 'custom')
      usedCustomRoster = useCustomRoster
      if (useCustomRoster) {
        // Affiliate links use their own roster; the company link uses the tenant default roster.
        const assignmentTable = affiliateLinkId != null
          ? 'affiliate_link_employee_assignments'
          : 'tenant_contact_employee_assignments'
        const scopeColumn = affiliateLinkId != null ? 'affiliate_link_id' : 'tenant_id'
        const assignmentScopeId = affiliateLinkId ?? tenant.id
        const { results: rosterRows } = await c.env.DB.prepare(`
          SELECT a.id, a.user_id, a.assignment_limit,
            (${FOLLOWUP_OPEN_TASK_COUNT_SQL}) AS open_task_count
          FROM ${assignmentTable} a
          INNER JOIN users u ON u.id = a.user_id
          WHERE a.${scopeColumn} = ? AND u.is_active = 1
          ORDER BY a.id ASC
        `).bind(tenant.id, assignmentScopeId).all<{
          id: number
          user_id: number
          assignment_limit: number | null
          open_task_count: number
        }>()

        // One slot per user_id (dual agents must never occupy two rotation slots).
        const byUser = new Map<number, { id: number; user_id: number; assignment_limit: number | null; open_task_count: number }>()
        for (const row of (rosterRows || []) as {
          id: number; user_id: number; assignment_limit: number | null; open_task_count: number
        }[]) {
          const existing = byUser.get(row.user_id)
          if (!existing) {
            byUser.set(row.user_id, row)
            continue
          }
          // Prefer the earlier row; keep the tighter limit if both define one.
          const nextLimit =
            existing.assignment_limit == null
              ? row.assignment_limit
              : row.assignment_limit == null
                ? existing.assignment_limit
                : Math.min(existing.assignment_limit, row.assignment_limit)
          byUser.set(row.user_id, { ...existing, assignment_limit: nextLimit })
        }

        const eligible = Array.from(byUser.values()).filter((row) =>
          row.assignment_limit == null || Number(row.open_task_count || 0) < row.assignment_limit
        )

        if (!eligible.length) {
          if (affiliateLinkId != null) {
            await c.env.DB.prepare(`
              UPDATE tenant_contact_affiliate_links
              SET unassigned_limit_count = unassigned_limit_count + 1
              WHERE id = ?
            `).bind(affiliateLinkId).run()
          } else {
            await c.env.DB.prepare(`
              UPDATE tenants
              SET contact_unassigned_limit_count = contact_unassigned_limit_count + 1
              WHERE id = ?
            `).bind(tenant.id).run()
          }
          assignedUserId = null
        } else {
          const cursorRow = affiliateLinkId != null
            ? await c.env.DB.prepare(`
                SELECT last_picked_roster_id AS last_picked_roster_id
                FROM tenant_contact_affiliate_links WHERE id = ? LIMIT 1
              `).bind(affiliateLinkId).first<{ last_picked_roster_id: number | null }>()
            : await c.env.DB.prepare(`
                SELECT contact_last_picked_roster_id AS last_picked_roster_id
                FROM tenants WHERE id = ? LIMIT 1
              `).bind(tenant.id).first<{ last_picked_roster_id: number | null }>()

          const lastRosterId = cursorRow?.last_picked_roster_id ?? null
          let picked = eligible[0]
          if (lastRosterId != null) {
            const afterIdx = eligible.findIndex((r) => r.id > lastRosterId)
            if (afterIdx >= 0) picked = eligible[afterIdx]
          }

          assignedUserId = picked.user_id
          if (affiliateLinkId != null) {
            await c.env.DB.prepare(`
              UPDATE tenant_contact_affiliate_links SET last_picked_roster_id = ? WHERE id = ?
            `).bind(picked.id, affiliateLinkId).run()
          } else {
            await c.env.DB.prepare(`
              UPDATE tenants SET contact_last_picked_roster_id = ? WHERE id = ?
            `).bind(picked.id, tenant.id).run()
          }
        }
      } else {
        // Auto, branch, and exclusion modes all round-robin among roles 4/5/6.
        // Branch modes first restrict the pool to their configured branch; exclusion
        // modes then remove the saved roster members from that pool.
        const activeAssignmentMode = affiliateLinkId != null
          ? affiliateLinkAssignmentMode
          : companyLinkAssignmentMode
        const useBranchMode =
          activeAssignmentMode === 'branch' || activeAssignmentMode === 'branch_excl'
        const useExclusionRoster =
          activeAssignmentMode === 'custom_excl' || activeAssignmentMode === 'branch_excl'
        const branchIdForFilter = useBranchMode
          ? (affiliateLinkId != null ? affiliateLinkAssignmentBranchId : companyLinkAssignmentBranchId)
          : null

        let staff = await listFollowupAssignableStaff(c.env.DB, tenant.id)
        if (useBranchMode && branchIdForFilter != null && staff.length) {
          const placeholders = staff.map(() => '?').join(',')
          const { results: branchStaff } = await c.env.DB.prepare(
            `SELECT id FROM users WHERE id IN (${placeholders}) AND assigned_location_id = ?`
          ).bind(...staff.map((u) => u.id), branchIdForFilter).all<{ id: number }>()
          const allowed = new Set(((branchStaff || []) as { id: number }[]).map((r) => r.id))
          staff = staff.filter((u) => allowed.has(u.id))
        }
        if (useExclusionRoster && staff.length) {
          const assignmentTable = affiliateLinkId != null
            ? 'affiliate_link_employee_assignments'
            : 'tenant_contact_employee_assignments'
          const scopeColumn = affiliateLinkId != null ? 'affiliate_link_id' : 'tenant_id'
          const assignmentScopeId = affiliateLinkId ?? tenant.id
          const { results: excludedRows } = await c.env.DB.prepare(
            `SELECT user_id FROM ${assignmentTable} WHERE ${scopeColumn} = ?`
          ).bind(assignmentScopeId).all<{ user_id: number }>()
          const excludedUserIds = new Set(((excludedRows || []) as { user_id: number }[]).map((row) => row.user_id))
          staff = staff.filter((user) => !excludedUserIds.has(user.id))
        }

        if (staff.length) {
          const stateRow = await c.env.DB.prepare(`
            SELECT last_auto_assigned_user_id
            FROM tenant_followup_auto_assign_state
            WHERE tenant_id = ?
            LIMIT 1
          `).bind(tenant.id).first<{ last_auto_assigned_user_id: number | null }>()

          const staffIds = staff.map((u) => u.id)
          const lastId: number | null = stateRow?.last_auto_assigned_user_id ?? null
          function pickNextUserId(last: number | null): number {
            if (last == null) return staffIds[0]
            const idx = staffIds.indexOf(last)
            if (idx === -1) return staffIds[0]
            return staffIds[(idx + 1) % staffIds.length]
          }
          assignedUserId = pickNextUserId(lastId)
        }
      }
    } catch (_assignError) {
      assignedUserId = null
    }

    if (Number.isFinite(createdFollowupId) && createdFollowupId > 0) {
      const scheduledAtNow = new Date().toISOString()
      const taskTitle = `متابعة طلب تواصل: ${customerName}`

      await c.env.DB.prepare(`
        INSERT INTO company_contact_followup_tasks
          (followup_id, tenant_id, task_title, scheduled_at_gregorian, scheduled_at_hijri,
           assigned_user_id, priority, created_by_user_id)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
      `).bind(
        createdFollowupId,
        tenant.id,
        taskTitle,
        scheduledAtNow,
        null,
        assignedUserId,
        'regular',
        null
      ).run()

      if (assignedUserId != null && !usedCustomRoster) {
        await c.env.DB.prepare(`
          INSERT INTO tenant_followup_auto_assign_state (tenant_id, last_auto_assigned_user_id, updated_at)
          VALUES (?, ?, CURRENT_TIMESTAMP)
          ON CONFLICT(tenant_id) DO UPDATE SET
            last_auto_assigned_user_id = excluded.last_auto_assigned_user_id,
            updated_at = CURRENT_TIMESTAMP
        `).bind(tenant.id, assignedUserId).run()
      }
    }

    return c.json({ success: true, message: 'تم إرسال طلبك بنجاح' })
  } catch (error: any) {
    return c.json({ success: false, error: error?.message || 'Server error' }, 500)
  }
})

app.get('/api/tenant-contact-affiliates', async (c) => {
  try {
    const userInfo = await getUserInfo(c)
    if (!userInfo.userId) return c.json({ success: false, error: 'Unauthorized' }, 401)
    const rid = userInfo.roleId
    if (rid == null) return c.json({ success: false, error: 'Forbidden' }, 403)

    let tenantId: number | null = null
    if (rid === 1) {
      const q = c.req.query('tenant_id')
      tenantId = q && /^\d+$/.test(String(q)) ? parseInt(String(q), 10) : null
      if (!tenantId) {
        return c.json({ success: false, error: 'tenant_id مطلوب' }, 400)
      }
    } else {
      tenantId = userInfo.tenantId
      if (!tenantId) {
        return c.json({ success: false, error: 'لا شركة مرتبطة' }, 400)
      }
    }

    const { results } = await c.env.DB.prepare(`
      SELECT id, tenant_id, path_segment, label, created_at,
             contact_bg_color, contact_form_color, contact_text_color, contact_custom_fields,
             contact_bg_image_url, contact_logo_url, contact_trust_badges, contact_form_badges,
             contact_hero_title, contact_hero_subtitle, contact_accent_color,
             assignment_mode, unassigned_limit_count
      FROM tenant_contact_affiliate_links
      WHERE tenant_id = ?
      ORDER BY created_at DESC, id DESC
    `).bind(tenantId).all()

    const tenantRow = await c.env.DB.prepare(`
      SELECT slug, contact_bg_color, contact_form_color, contact_text_color, contact_custom_fields,
             contact_bg_image_url, contact_trust_badges, contact_form_badges, contact_hero_title, contact_hero_subtitle, contact_accent_color
      FROM tenants WHERE id = ? LIMIT 1
    `)
      .bind(tenantId)
      .first<
        { slug: string } & ContactPageDesignFields & {
          contact_bg_image_url: string | null
          contact_trust_badges: string | null
          contact_form_badges: string | null
          contact_hero_title: string | null
          contact_hero_subtitle: string | null
          contact_accent_color: string | null
        }
      >()

    const locRes = await c.env.DB.prepare(`
      SELECT id, name, slug FROM tenant_locations
      WHERE tenant_id = ? AND is_active = 1
      ORDER BY is_primary DESC, name ASC
    `)
      .bind(tenantId)
      .all()

    return c.json({
      success: true,
      data: results || [],
      tenant_slug: tenantRow?.slug ?? null,
      tenant_design: tenantRow
        ? {
            contact_bg_color: tenantRow.contact_bg_color ?? null,
            contact_form_color: tenantRow.contact_form_color ?? null,
            contact_text_color: tenantRow.contact_text_color ?? null,
            contact_custom_fields: tenantRow.contact_custom_fields ?? null,
            contact_bg_image_url: tenantRow.contact_bg_image_url ?? null,
            contact_trust_badges: tenantRow.contact_trust_badges ?? null,
            contact_form_badges: tenantRow.contact_form_badges ?? null,
            contact_hero_title: tenantRow.contact_hero_title ?? null,
            contact_hero_subtitle: tenantRow.contact_hero_subtitle ?? null,
            contact_accent_color: tenantRow.contact_accent_color ?? null,
          }
        : null,
      locations: locRes.results || [],
    })
  } catch (error: any) {
    return c.json({ success: false, error: error?.message || 'Server error' }, 500)
  }
})

app.post('/api/tenant-contact-affiliates', async (c) => {
  try {
    const userInfo = await getUserInfo(c)
    if (!userInfo.userId) return c.json({ success: false, error: 'Unauthorized' }, 401)
    if (userInfo.roleId !== 1 && userInfo.roleId !== 2) {
      return c.json({ success: false, error: 'Forbidden' }, 403)
    }

    const payload = await c.req.json().catch(() => ({}))
    const pathSegment = normalizeAffiliatePathSegment(payload?.path_segment)
    const label = String(payload?.label ?? '').trim()

    let tenantId: number | null = userInfo.roleId === 2 ? userInfo.tenantId : null
    if (userInfo.roleId === 1) {
      const raw = payload?.tenant_id
      const n = parseInt(String(raw ?? ''), 10)
      tenantId = Number.isFinite(n) && n > 0 ? n : null
    }

    if (!tenantId) {
      return c.json(
        { success: false, error: userInfo.roleId === 1 ? 'tenant_id مطلوب' : 'لا شركة مرتبطة' },
        400
      )
    }

    if (userInfo.roleId === 2 && userInfo.tenantId !== tenantId) {
      return c.json({ success: false, error: 'Forbidden' }, 403)
    }

    if (!pathSegment || !isValidAffiliatePathSegment(pathSegment)) {
      return c.json(
        {
          success: false,
          error:
            'مسار غير صالح. استخدم أحرفاً إنجليزية صغيرة وأرقاماً وشرطة سفلية أو وسطية فقط (مثل facebook أو fb-ads)'
        },
        400
      )
    }
    if (!label || label.length > 120) {
      return c.json({ success: false, error: 'العنوان مطلوب (حتى 120 حرفاً)' }, 400)
    }

    const rawForkFrom = payload?.fork_from
    const forkFrom = rawForkFrom == null || rawForkFrom === ''
      ? null
      : parseInt(String(rawForkFrom), 10)
    if (forkFrom !== null && (!Number.isFinite(forkFrom) || forkFrom <= 0)) {
      return c.json({ success: false, error: 'رابط المصدر غير صالح' }, 400)
    }

    // Snapshot the company-link design and task-distribution configuration at creation time.
    const companyDesign = await c.env.DB.prepare(`
      SELECT contact_bg_color, contact_form_color, contact_text_color, contact_custom_fields,
             contact_assignment_mode, contact_assignment_branch_id
      FROM tenants WHERE id = ? LIMIT 1
    `)
      .bind(tenantId)
      .first<ContactPageDesignFields & { contact_assignment_mode: string | null; contact_assignment_branch_id: number | null }>()

    let sourceDesign: ContactPageDesignFields | null = null
    if (forkFrom != null) {
      sourceDesign = await c.env.DB.prepare(`
        SELECT contact_bg_color, contact_form_color, contact_text_color, contact_custom_fields,
               contact_bg_image_url, contact_logo_url, contact_trust_badges, contact_form_badges,
               contact_hero_title, contact_hero_subtitle, contact_accent_color
        FROM tenant_contact_affiliate_links
        WHERE id = ? AND tenant_id = ? LIMIT 1
      `)
        .bind(forkFrom, tenantId)
        .first<ContactPageDesignFields>()
      if (!sourceDesign) {
        return c.json({ success: false, error: 'رابط المصدر غير موجود' }, 404)
      }
    }

    const designToCopy = sourceDesign ?? companyDesign
    const insertResult = await c.env.DB.prepare(`
      INSERT INTO tenant_contact_affiliate_links (
        tenant_id, path_segment, label,
        contact_bg_color, contact_form_color, contact_text_color, contact_custom_fields,
        contact_bg_image_url, contact_logo_url, contact_trust_badges, contact_form_badges,
        contact_hero_title, contact_hero_subtitle, contact_accent_color
      )
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `)
      .bind(
        tenantId,
        pathSegment,
        label,
        designToCopy?.contact_bg_color ?? null,
        designToCopy?.contact_form_color ?? null,
        designToCopy?.contact_text_color ?? null,
        designToCopy?.contact_custom_fields ?? null,
        designToCopy?.contact_bg_image_url ?? null,
        designToCopy?.contact_logo_url ?? null,
        designToCopy?.contact_trust_badges ?? null,
        designToCopy?.contact_form_badges ?? null,
        designToCopy?.contact_hero_title ?? null,
        designToCopy?.contact_hero_subtitle ?? null,
        designToCopy?.contact_accent_color ?? null
      )
      .run()

    const affiliateLinkId = Number(
      (insertResult as any)?.meta?.last_row_id ??
      (insertResult as any)?.meta?.lastRowId ??
      (insertResult as any)?.meta?.last_insert_rowid
    )
    if (
      forkFrom == null &&
      Number.isFinite(affiliateLinkId) &&
      affiliateLinkId > 0 &&
      ['custom', 'custom_excl', 'branch_excl'].includes(companyDesign?.contact_assignment_mode ?? '')
    ) {
      await c.env.DB.prepare(`
        UPDATE tenant_contact_affiliate_links
        SET assignment_mode = ?, assignment_branch_id = ?
        WHERE id = ?
      `).bind(
        companyDesign?.contact_assignment_mode,
        companyDesign?.contact_assignment_mode === 'branch_excl'
          ? companyDesign?.contact_assignment_branch_id ?? null
          : null,
        affiliateLinkId
      ).run()
      // Snapshot one roster entry per user (follow-up owner roles 4/5/6).
      await c.env.DB.prepare(`
        INSERT INTO affiliate_link_employee_assignments (affiliate_link_id, user_id, role_context, assignment_limit)
        SELECT ?, user_id, 'employee', MIN(assignment_limit)
        FROM tenant_contact_employee_assignments
        WHERE tenant_id = ?
        GROUP BY user_id
      `).bind(affiliateLinkId, tenantId).run()
    }

    return c.json({ success: true, message: 'تم إنشاء رابط الإحالة' })
  } catch (error: any) {
    const msg = String(error?.message || '')
    if (msg.includes('UNIQUE') || msg.toLowerCase().includes('unique')) {
      return c.json({ success: false, error: 'هذا المسار مستخدم بالفعل لهذه الشركة' }, 400)
    }
    return c.json({ success: false, error: error?.message || 'Server error' }, 500)
  }
})

app.patch('/api/tenant-contact-affiliates/:id', async (c) => {
  try {
    const userInfo = await getUserInfo(c)
    if (!userInfo.userId) return c.json({ success: false, error: 'Unauthorized' }, 401)
    if (userInfo.roleId !== 1 && userInfo.roleId !== 2) {
      return c.json({ success: false, error: 'Forbidden' }, 403)
    }

    const linkId = parseInt(c.req.param('id'), 10)
    if (!Number.isFinite(linkId) || linkId <= 0) {
      return c.json({ success: false, error: 'Invalid id' }, 400)
    }

    const row = await c.env.DB.prepare(`
      SELECT id, tenant_id FROM tenant_contact_affiliate_links WHERE id = ? LIMIT 1
    `)
      .bind(linkId)
      .first<{ id: number; tenant_id: number }>()

    if (!row) return c.json({ success: false, error: 'Not found' }, 404)

    if (userInfo.roleId === 2) {
      if (!userInfo.tenantId || row.tenant_id !== userInfo.tenantId) {
        return c.json({ success: false, error: 'Forbidden' }, 403)
      }
    }

    const body = (await c.req.json().catch(() => ({}))) as Record<string, unknown>
    const updates: Record<string, string | null> = {}

    if ('label' in body) {
      const label = String(body.label ?? '').trim()
      if (!label || label.length > 120) {
        return c.json({ success: false, error: 'العنوان مطلوب (حتى 120 حرفاً)' }, 400)
      }
      updates.label = label
    }

    const designParsed = parseContactDesignBodyFields(body)
    if (!designParsed.ok) {
      return c.json({ success: false, error: designParsed.error }, 400)
    }
    Object.assign(updates, designParsed.updates)

    if ('contact_bg_image_url' in body) {
      const raw = body.contact_bg_image_url
      updates.contact_bg_image_url = (raw == null || raw === '') ? null : String(raw).trim()
    }

    if ('contact_logo_url' in body) {
      const raw = body.contact_logo_url
      updates.contact_logo_url = (raw == null || raw === '') ? null : String(raw).trim()
    }

    if ('copy_from_company' in body && body.copy_from_company) {
      const companyDesign = await c.env.DB.prepare(`
        SELECT contact_bg_color, contact_form_color, contact_text_color, contact_custom_fields
        FROM tenants WHERE id = ? LIMIT 1
      `)
        .bind(row.tenant_id)
        .first<ContactPageDesignFields>()
      updates.contact_bg_color = companyDesign?.contact_bg_color ?? null
      updates.contact_form_color = companyDesign?.contact_form_color ?? null
      updates.contact_text_color = companyDesign?.contact_text_color ?? null
      updates.contact_custom_fields = companyDesign?.contact_custom_fields ?? null
    }

    const keys = Object.keys(updates)
    if (keys.length === 0) {
      return c.json({ success: false, error: 'لا توجد حقول للتحديث' }, 400)
    }

    const setSql = keys.map((k) => `${k} = ?`).join(', ')
    const values = keys.map((k) => updates[k]!)
    await c.env.DB.prepare(`UPDATE tenant_contact_affiliate_links SET ${setSql} WHERE id = ?`)
      .bind(...values, linkId)
      .run()

    return c.json({ success: true, message: 'تم حفظ تصميم الرابط' })
  } catch (error: any) {
    return c.json({ success: false, error: error?.message || 'Server error' }, 500)
  }
})

