app.patch('/api/my-followup-tasks/:id/rating', async (c) => {
  try {
    const userInfo = await getUserInfo(c)
    if (!userInfo.userId) return c.json({ success: false, error: 'Unauthorized' }, 401)
    if (!canAccessMyFollowupTasksPage(userInfo.roleId)) return c.json({ success: false, error: 'Forbidden' }, 403)
    if (!userInfo.tenantId) return c.json({ success: false, error: 'Forbidden' }, 403)

    const taskId = parseInt(c.req.param('id'), 10)
    if (!Number.isFinite(taskId) || taskId <= 0) {
      return c.json({ success: false, error: 'Invalid task id' }, 400)
    }

    const body = await c.req.json().catch(() => ({})) as { rating?: number | null; note?: string | null }
    const ratingRaw = body.rating == null ? null : parseInt(String(body.rating), 10)
    if (ratingRaw !== null && (ratingRaw < 1 || ratingRaw > 5)) {
      return c.json({ success: false, error: 'rating must be 1–5 or null' }, 400)
    }
    const noteVal = ratingRaw != null ? (String(body.note ?? '').trim().slice(0, 1000) || null) : null

    const task = await c.env.DB.prepare(`
      SELECT t.id, t.tenant_id, t.assigned_user_id
      FROM company_contact_followup_tasks t
      WHERE t.id = ? AND t.tenant_id = ? AND t.assigned_user_id = ?
      LIMIT 1
    `).bind(taskId, userInfo.tenantId, userInfo.userId).first<{ id: number }>()

    if (!task?.id) return c.json({ success: false, error: 'Task not found or not assigned to you' }, 404)

    await c.env.DB.prepare(`
      UPDATE company_contact_followup_tasks SET rating = ?, rating_note = ? WHERE id = ?
    `).bind(ratingRaw, noteVal, taskId).run()

    return c.json({ success: true })
  } catch (error: any) {
    return c.json({ success: false, error: error?.message || 'Server error' }, 500)
  }
})

app.patch('/api/my-followup-tasks/:id', async (c) => {
  try {
    const userInfo = await getUserInfo(c)
    if (!userInfo.userId) return c.json({ success: false, error: 'Unauthorized' }, 401)
    if (!canAccessMyFollowupTasksPage(userInfo.roleId)) return c.json({ success: false, error: 'Forbidden' }, 403)
    if (!userInfo.tenantId) return c.json({ success: false, error: 'Forbidden' }, 403)

    const taskId = parseInt(c.req.param('id'), 10)
    if (!Number.isFinite(taskId) || taskId <= 0) {
      return c.json({ success: false, error: 'Invalid task id' }, 400)
    }

    const payload = await c.req.json().catch(() => ({}))
    const hasStatus = payload?.status != null && String(payload.status).trim() !== ''
    const status = hasStatus ? String(payload?.status ?? '').trim().toLowerCase() : null
    if (hasStatus && !['pending', 'completed'].includes(String(status))) {
      return c.json({ success: false, error: 'حالة غير صالحة' }, 400)
    }

    const noteTextRaw = payload?.note_text
    const hasNote = noteTextRaw != null
    const noteText = hasNote ? String(noteTextRaw ?? '').trim() : null
    if (!hasStatus && !hasNote) {
      return c.json({ success: false, error: 'لا توجد بيانات للتحديث' }, 400)
    }
    // If the UI sends an explicit note_text, require it to be non-empty.
    if (hasNote && !noteText) {
      return c.json({ success: false, error: 'يرجى إدخال الملاحظة' }, 400)
    }

    const task = await c.env.DB.prepare(`
      SELECT id, tenant_id, assigned_user_id FROM company_contact_followup_tasks WHERE id = ? LIMIT 1
    `).bind(taskId).first<{ id: number; tenant_id: number; assigned_user_id: number | null }>()

    if (!task?.id) return c.json({ success: false, error: 'Task not found' }, 404)
    if (task.tenant_id !== userInfo.tenantId || task.assigned_user_id !== userInfo.userId) {
      return c.json({ success: false, error: 'Forbidden' }, 403)
    }

    if (hasStatus && status) {
      await c.env.DB.prepare(`
        UPDATE company_contact_followup_tasks SET status = ? WHERE id = ?
      `).bind(status, taskId).run()

      if (status === 'completed') {
        await c.env.DB.prepare(`
          UPDATE company_contact_followup_task_pass_requests
          SET status = 'cancelled', resolved_at = CURRENT_TIMESTAMP
          WHERE task_id = ? AND status = 'pending'
        `).bind(taskId).run()
      }
    }

    if (hasNote && noteText) {
      await c.env.DB.prepare(`
        UPDATE company_contact_followup_tasks
        SET employee_note_text = ?, employee_note_updated_at = CURRENT_TIMESTAMP
        WHERE id = ?
      `).bind(noteText, taskId).run()

      const userRow = await c.env.DB.prepare(`
        SELECT full_name FROM users WHERE id = ? LIMIT 1
      `).bind(userInfo.userId).first<{ full_name: string }>()
      const userName = userRow?.full_name || ''

      await c.env.DB.prepare(`
        INSERT INTO company_contact_followup_task_notes
          (task_id, tenant_id, user_id, user_name, note_text, note_type)
        VALUES (?, ?, ?, ?, ?, 'employee_note')
      `).bind(taskId, userInfo.tenantId, userInfo.userId, userName, noteText).run()
    }

    const msg =
      hasStatus && status === 'completed'
        ? 'تم إكمال المهمة'
        : hasStatus && status === 'pending'
          ? 'أعيدت المهمة إلى قيد التنفيذ'
          : 'تم حفظ الملاحظة'

    return c.json({ success: true, message: msg })
  } catch (error: any) {
    return c.json({ success: false, error: error?.message || 'Server error' }, 500)
  }
})

