// ─── Customer Rating Reminder System ─────────────────────────────────────────
// Runs daily via Cloudflare cron (see wrangler.toml [triggers]).
// For each customer with a rating (excluding عميل موقوف = 1), inserts a
// customer_alarm for the assigned user when the interval since the last
// auto-reminder has elapsed.

const REMINDER_NOTE_PREFIX = '[تذكير-تلقائي-تقييم]'

const RATING_REMINDER_INTERVALS: Record<number, number> = {
  5: 3, // عميل ممتاز
  4: 5, // عميل جيد
  3: 7, // عميل مقبول
  2: 9, // عميل سيئ
}

const RATING_REMINDER_LABELS: Record<number, string> = {
  5: 'عميل ممتاز',
  4: 'عميل جيد',
  3: 'عميل مقبول',
  2: 'عميل سيئ',
}

async function processCustomerReminders(db: D1Database): Promise<{ created: number; skipped: number }> {
  const today = new Date()
  const todayStr = today.toISOString().split('T')[0]

  // Two separate assignment paths — role 4 via customer_assignments, role 5 via
  // customers.assigned_bank_agent_id — combined with UNION ALL so both assigned
  // users each get their own alarm independently.
  // cr.created_at is the rating date; the reminder cycle is anchored to it.
  const { results: customers } = await db.prepare(`
    SELECT
      c.id        AS customer_id,
      c.full_name AS customer_name,
      ca.employee_id AS user_id,
      c.tenant_id,
      cr.rating,
      cr.created_at AS rating_date
    FROM customers c
    INNER JOIN customer_assignments ca ON ca.customer_id = c.id
    INNER JOIN users u ON u.id = ca.employee_id AND u.role_id = 4 AND u.is_active = 1
    INNER JOIN customer_reviews cr ON cr.customer_id = c.id
    WHERE cr.id = (
      SELECT id FROM customer_reviews
      WHERE customer_id = c.id
      ORDER BY created_at DESC
      LIMIT 1
    )
    AND cr.rating BETWEEN 2 AND 5
    AND c.tenant_id IS NOT NULL

    UNION ALL

    SELECT
      c.id        AS customer_id,
      c.full_name AS customer_name,
      c.assigned_bank_agent_id AS user_id,
      c.tenant_id,
      cr.rating,
      cr.created_at AS rating_date
    FROM customers c
    INNER JOIN users u ON u.id = c.assigned_bank_agent_id AND u.role_id IN (5, 6) AND u.is_active = 1
    INNER JOIN customer_reviews cr ON cr.customer_id = c.id
    WHERE cr.id = (
      SELECT id FROM customer_reviews
      WHERE customer_id = c.id
      ORDER BY created_at DESC
      LIMIT 1
    )
    AND cr.rating BETWEEN 2 AND 5
    AND c.assigned_bank_agent_id IS NOT NULL
    AND c.tenant_id IS NOT NULL
  `).all()

  let created = 0
  let skipped = 0

  const todayMidnight = new Date(today)
  todayMidnight.setHours(0, 0, 0, 0)

  const candidates: Array<{
    customer_id: number
    customer_name: string
    user_id: number
    tenant_id: number
    rating: number
    cycleStartStr: string
    note: string
  }> = []

  for (const row of customers as any[]) {
    const interval = RATING_REMINDER_INTERVALS[row.rating as number]
    if (!interval) { skipped++; continue }

    const ratingDate = new Date(String(row.rating_date))
    ratingDate.setHours(0, 0, 0, 0)
    const daysSinceRating = Math.floor(
      (todayMidnight.getTime() - ratingDate.getTime()) / 86_400_000
    )

    if (daysSinceRating < interval) { skipped++; continue }

    const cycleNumber = Math.floor(daysSinceRating / interval)
    const cycleStart = new Date(ratingDate)
    cycleStart.setDate(cycleStart.getDate() + cycleNumber * interval)
    const cycleStartStr = cycleStart.toISOString().split('T')[0]

    const label = RATING_REMINDER_LABELS[row.rating as number]
    const note = `${REMINDER_NOTE_PREFIX} راجع العميل: ${row.customer_name} - التقييم: ${label} (كل ${interval} أيام)`
    candidates.push({
      customer_id: row.customer_id,
      customer_name: row.customer_name,
      user_id: row.user_id,
      tenant_id: row.tenant_id,
      rating: row.rating,
      cycleStartStr,
      note,
    })
  }

  if (candidates.length === 0) return { created, skipped }

  // Batch-load existing reminder alarms for candidate pairs to avoid N+1 SELECTs.
  const minCycleStart = candidates.reduce((min, c) => (c.cycleStartStr < min ? c.cycleStartStr : min), candidates[0].cycleStartStr)
  const existing = await db.prepare(`
    SELECT customer_id, user_id, alarm_date_gregorian, note
    FROM customer_alarms
    WHERE note LIKE ?
      AND alarm_date_gregorian >= ?
  `).bind(`${REMINDER_NOTE_PREFIX}%`, minCycleStart).all<{
    customer_id: number
    user_id: number
    alarm_date_gregorian: string
    note: string
  }>()

  const existingKeys = new Set<string>()
  for (const row of existing.results || []) {
    existingKeys.add(`${row.customer_id}:${row.user_id}:${row.alarm_date_gregorian}`)
    // Also key by cycle window: any alarm for pair on/after cycle start
    existingKeys.add(`${row.customer_id}:${row.user_id}:since:${row.alarm_date_gregorian}`)
  }

  const toInsert: typeof candidates = []
  for (const cand of candidates) {
    let hasExisting = false
    for (const key of existingKeys) {
      if (!key.startsWith(`${cand.customer_id}:${cand.user_id}:`)) continue
      if (key === `${cand.customer_id}:${cand.user_id}:${todayStr}`) { hasExisting = true; break }
      const sinceMatch = key.match(new RegExp(`^${cand.customer_id}:${cand.user_id}:since:(.+)$`))
      if (sinceMatch && sinceMatch[1] >= cand.cycleStartStr) { hasExisting = true; break }
    }
    // More precise: scan existing.results for this pair with date >= cycleStart
    if (!hasExisting) {
      for (const row of existing.results || []) {
        if (Number(row.customer_id) === Number(cand.customer_id)
          && Number(row.user_id) === Number(cand.user_id)
          && String(row.alarm_date_gregorian) >= cand.cycleStartStr) {
          hasExisting = true
          break
        }
      }
    }
    if (hasExisting) { skipped++; continue }
    toInsert.push(cand)
  }

  const insertStmt = db.prepare(`
    INSERT INTO customer_alarms
      (customer_id, customer_name, alarm_date_gregorian, note, user_id, tenant_id, alarm_type, is_read)
    VALUES (?, ?, ?, ?, ?, ?, 'reminder', 0)
  `)
  for (let i = 0; i < toInsert.length; i += 25) {
    const chunk = toInsert.slice(i, i + 25)
    await db.batch(
      chunk.map((row) =>
        insertStmt.bind(
          row.customer_id,
          row.customer_name,
          todayStr,
          row.note,
          row.user_id,
          row.tenant_id,
        )
      )
    )
    created += chunk.length
  }

  return { created, skipped }
}

// Manual trigger endpoint (admin only) for testing without waiting for the cron.
app.post('/api/customer-reminders/trigger', async (c) => {
  try {
    const userInfo = await getUserInfo(c)
    if (!userInfo.userId) return c.json({ success: false, error: 'Unauthorized' }, 401)

    // Only role 1 (super admin) or role 2 (tenant admin) may trigger this.
    const role = normalizeRoleId(userInfo.roleId)
    if (role !== 1 && role !== 2) {
      return c.json({ success: false, error: 'Forbidden' }, 403)
    }

    const result = await processCustomerReminders(c.env.DB)
    return c.json({ success: true, ...result })
  } catch (error: any) {
    console.error('Error triggering customer reminders:', error)
    return c.json({ success: false, error: error.message }, 500)
  }
})

// Auto-transfer "no response" followup tasks to the next eligible employee after 48 hours.
// Distribution order mirrors the follow-up CSV import: staff ordered by name, cursor from
// tenant_followup_auto_assign_state, pure round-robin excluding the current assignee.
async function processNoResponseTransfers(db: D1Database): Promise<{ transferred: number; skipped: number }> {
  const { results: expiredRows } = await db.prepare(`
    SELECT t.id AS task_id, t.tenant_id, t.assigned_user_id, t.followup_id
    FROM company_contact_followup_tasks t
    INNER JOIN company_contact_followups f ON f.id = t.followup_id
    WHERE COALESCE(f.is_no_response, 0) = 1
      AND f.no_response_at IS NOT NULL
      AND datetime(f.no_response_at) <= datetime('now', '-48 hours')
      AND COALESCE(f.is_archived, 0) = 0
    ORDER BY f.no_response_at ASC
    LIMIT 200
  `).all<{ task_id: number; tenant_id: number; assigned_user_id: number; followup_id: number }>()

  let transferred = 0
  let skipped = 0

  // Per-tenant cache: staff list, round-robin cursor, and user name lookup
  const tenantStaffCache = new Map<number, { id: number; full_name: string }[]>()
  const tenantStateCache = new Map<number, number | null>()
  const userNameCache = new Map<number, string>()

  for (const row of (expiredRows || [])) {
    const tenantId = row.tenant_id

    if (!tenantStaffCache.has(tenantId)) {
      // Same staff query as follow-up CSV import (roles 4/5/6, ordered by name)
      const { results: staffRows } = await db.prepare(`
        SELECT u.id, u.full_name
        FROM users u
        WHERE u.is_active = 1
          AND (
            (u.role_id IN (4, 6, 14) AND u.tenant_id = ?)
            OR (
              u.role_id IN (5, 15, 6)
              AND (
                u.tenant_id = ?
                OR EXISTS (SELECT 1 FROM banks b WHERE b.id = u.assigned_bank_id AND b.tenant_id = ?)
              )
            )
          )
        ORDER BY COALESCE(NULLIF(TRIM(u.full_name), ''), u.username) ASC
      `).bind(tenantId, tenantId, tenantId).all<{ id: number; full_name: string }>()

      // Deduplicate (role 6 can appear twice from both clauses)
      const seen = new Set<number>()
      const dedupedStaff: { id: number; full_name: string }[] = []
      for (const s of (staffRows || [])) {
        if (!seen.has(s.id)) { seen.add(s.id); dedupedStaff.push(s) }
      }
      tenantStaffCache.set(tenantId, dedupedStaff)
      for (const s of dedupedStaff) userNameCache.set(s.id, s.full_name || '')

      const stateRow = await db.prepare(`
        SELECT last_auto_assigned_user_id FROM tenant_followup_auto_assign_state
        WHERE tenant_id = ? LIMIT 1
      `).bind(tenantId).first<{ last_auto_assigned_user_id: number | null }>()
      tenantStateCache.set(tenantId, stateRow?.last_auto_assigned_user_id ?? null)
    }

    const staff = tenantStaffCache.get(tenantId) || []
    if (!staff.length) { skipped++; continue }

    const staffIds = staff.map((s) => s.id)

    // Prefer staff other than the current assignee; fall back to full list if only one person
    const preferred = staffIds.filter((id) => id !== row.assigned_user_id)
    const eligible = preferred.length ? preferred : staffIds
    if (!eligible.length) { skipped++; continue }

    // Round-robin pick from eligible using the follow-up cursor
    const lastId = tenantStateCache.get(tenantId) ?? null
    const lastIdx = lastId != null ? staffIds.indexOf(lastId) : -1
    let nextId: number | null = null
    for (let i = 1; i <= staffIds.length; i++) {
      const candidate = staffIds[(lastIdx + i) % staffIds.length]
      if (eligible.includes(candidate)) { nextId = candidate; break }
    }
    if (nextId == null) nextId = eligible[0]

    // Transfer the task
    await db.prepare(`
      UPDATE company_contact_followup_tasks SET assigned_user_id = ? WHERE id = ? AND tenant_id = ?
    `).bind(nextId, row.task_id, tenantId).run()

    // Clear the no-response flag so the task appears normally in the new employee's list
    await db.prepare(`
      UPDATE company_contact_followups
      SET is_no_response = 0, no_response_at = NULL, no_response_by = NULL
      WHERE id = ? AND tenant_id = ?
    `).bind(row.followup_id, tenantId).run()

    // Audit trail: note visible to anyone reviewing the task
    const fromName = userNameCache.get(row.assigned_user_id) || String(row.assigned_user_id)
    const toName = userNameCache.get(nextId) || String(nextId)
    try {
      await db.prepare(`
        INSERT INTO company_contact_followup_task_notes
          (task_id, tenant_id, user_id, user_name, note_text, note_type)
        VALUES (?, ?, 0, 'النظام', ?, 'auto_transfer')
      `).bind(
        row.task_id, tenantId,
        `تم تحويل المهمة تلقائياً من ${fromName} إلى ${toName} بسبب عدم الرد خلال 48 ساعة`
      ).run()
    } catch { /* note table may be missing in test envs */ }

    // Update follow-up round-robin cursor (same state table as CSV import)
    await db.prepare(`
      INSERT INTO tenant_followup_auto_assign_state (tenant_id, last_auto_assigned_user_id, updated_at)
      VALUES (?, ?, CURRENT_TIMESTAMP)
      ON CONFLICT(tenant_id) DO UPDATE SET
        last_auto_assigned_user_id = excluded.last_auto_assigned_user_id,
        updated_at = CURRENT_TIMESTAMP
    `).bind(tenantId, nextId).run()

    tenantStateCache.set(tenantId, nextId)
    transferred++
  }

  return { transferred, skipped }
}

// Manual trigger for admins to test without waiting for cron.
app.post('/api/followup-no-response/trigger', async (c) => {
  try {
    const userInfo = await getUserInfo(c)
    if (!userInfo.userId) return c.json({ success: false, error: 'Unauthorized' }, 401)
    const role = normalizeRoleId(userInfo.roleId)
    if (role !== 1 && role !== 2) return c.json({ success: false, error: 'Forbidden' }, 403)
    const result = await processNoResponseTransfers(c.env.DB)
    return c.json({ success: true, ...result })
  } catch (error: any) {
    return c.json({ success: false, error: error.message }, 500)
  }
})

export { ChatConversationRoom, UserNotificationRoom }

export default {
  fetch: app.fetch.bind(app),
  async scheduled(_event: ScheduledEvent, env: Bindings, ctx: ExecutionContext) {
    ctx.waitUntil(
      processCustomerReminders(env.DB).then(({ created, skipped }) => {
        console.log(`[customer-reminders] created=${created} skipped=${skipped}`)
      })
    )
    ctx.waitUntil(
      processNoResponseTransfers(env.DB).then(({ transferred, skipped }) => {
        console.log(`[no-response-transfers] transferred=${transferred} skipped=${skipped}`)
      })
    )
  },
}


